window.EXAM_PAPERS=window.EXAM_PAPERS||{};window.EXAM_PAPERS["1756566913"]={"id":"1756566913","title":"【言语理解】逻辑填空刷题题库","group":"专项练习","items":[{"id":"1718789646113","type":"single","material":"","stem":"农村电网（）升级，事关广大农村地区的长远发展。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"改造"},{"label":"B","content":"改线"},{"label":"C","content":"改变"},{"label":"D","content":"改良"}],"answer":"A","explanation":"“网络改造升级”为习惯表述。","no":1},{"id":"1718789646114","type":"single","material":"","stem":"陕西林业厅公布了猎人周某用数码相机和胶片相机拍摄的华南虎照片。随后，照片真实性受到来自部分网友、华南虎专家和中科院专家等方面的质疑。华南虎照：真相（），努力（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"不致;不只"},{"label":"B","content":"不致;不止"},{"label":"C","content":"不至;不只"},{"label":"D","content":"不至;不止"}],"answer":"D","explanation":"第一空，“不至”是动词，指不出现、不到达；“不致”是副词，指不会引起某种后果。横线处所填词语应为谓语，表示“真相不出现”之意，应选“不至”,排除A、B第二空，C项“不只”是连词，表示还有其他；“不止”是动词，指不停止。文段表达“真相不查明，努力就不停止”之意，应选“不止”。","no":2},{"id":"1718789646115","type":"single","material":"","stem":"在过去十年里，中国南部几乎每个省都发现了古人类化石，其中许多都来自可以追溯到10万年或者更多年头之前的沉积物，但是从解剖学来看，这些人类的（）跟生活在今天的中国人几乎没有什么不同。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"外形"},{"label":"B","content":"特征"},{"label":"C","content":"样貌"},{"label":"D","content":"特质"}],"answer":"B","explanation":"对应“从解剖学来看”,可知看到的不是表面的“外形”或者“样貌”,排除A、C“特质”为心理学用词，用于描述个人人格的特点。由“古人类化石”无法看出人格特点，排除D“特征”是某一物质自身所具备的特殊性质，可以用来描述从解剖学角度看出来的人类特性。","no":3},{"id":"1718789646116","type":"single","material":"","stem":"作为全国最高的货币管理机构，央行独具优势，颇有“惯看秋月春风”的（）。由此而一展“任凭风浪起，稳坐钓鱼台”的“定力”是毫无疑问的。不过，一旦说到“精准发力”，央行究竟是为了稳定预期，还是真的自信能“精确打击”，倒是值得（）一番的。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"气度;琢磨"},{"label":"B","content":"气概;捉摸"},{"label":"C","content":"气质;期待"},{"label":"D","content":"气派;商榷"}],"answer":"A","explanation":"先看第二空，“期待”的对象多为乐见其成的事情；“值得商榷”本身暗含否定、不认同的意思。句中“央行究竟是……还是……”表达的是不确定的意思，既没有乐见其成，也没有否定、不认同，由此排除C、D“琢磨”指思考，考虑；“捉摸”指猜测，预料。二者均符合句意。<br>再看第一空，“气度”指气魄、风度、度量；“气概”指正直、豪迈的态度或某种气势。对应“惯看秋月春风”和“‘任凭风浪起，稳坐钓鱼台’的‘定力'”,这里说的是央行作为全国最高的货币管理机构所表现出来的淡定从容的风度，选“气度”更恰当，排除B。","no":4},{"id":"1718789646117","type":"single","material":"","stem":"个人成长进步靠什么？有人说靠组织培养，有人说靠自身努力，实际上二者并不（），在现实生活中，绝大多数的人的成长进步既离不开组织培养，也离不开自己努力。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"相关"},{"label":"B","content":"统一"},{"label":"C","content":"重复"},{"label":"D","content":"矛盾"}],"answer":"D","explanation":"由后句的“既离不开……也离不开……”可知，句意为两种说法都有道理，“组织培养”和“自身努力”都是个人成长进步的要素，二者缺一不可。能体现二者之间这一关系的只有D项的“矛盾”。","no":5},{"id":"1718789646118","type":"single","material":"","stem":"文化遗产不可复制，也不能再造，不管是申遗还是入选之后，（）应该始终放在第一位。只有这样，文化遗产才能更好地造福于民，传之子孙。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"开发"},{"label":"B","content":"保护"},{"label":"C","content":"重建"},{"label":"D","content":"研究"}],"answer":"B","explanation":"由“不可复制，也不能再造”可知，文化遗产具有唯一性，一旦毁损，后人再也不能看到。因此要使文化遗产更好地造福于民，传之子孙，首先要做好文化遗产的“保护”工作。“重建”与“不可复制，也不能再造”相悖，排除C对遗产的“开发”“研究”应建立在“保护”的基础上，因此“开发”“研究”不应放在“第一位”,排除A、D","no":6},{"id":"1718789646119","type":"single","material":"","stem":"有研究者认为人类大脑处理高级数学问题的能力与人类使用语言的能力息息相关，语言中的抽象化能力是处理高级数学问题的（）。但是，不少数学家和物理学家（）这种观点的可靠性，爱因斯坦就曾宣称：“词汇和语言，不管是写下来的还是说出口的，对我的思考过程似乎都没什么用处。”<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"条件;赞同"},{"label":"B","content":"起点;质疑"},{"label":"C","content":"前提;相信"},{"label":"D","content":"关键;否认"}],"answer":"B","explanation":"第一空，“关键”比喻事物最紧要的部分，是对情况起决定作用的因素。“关键”填入程度过重，过于夸大了“息息相关”的程度，排除D<br>第二空，由爱因斯坦的话“对我的思考过程似乎都没什么用处”可知，不少数学家和物理学家并不认可前文关于语言中的抽象化能力与大脑处理高级数学问题能力有关的观点。A项的“赞同”,C项的“相信”与此相悖，排除。","no":7},{"id":"1718789646120","type":"single","material":"","stem":"互联网与旅游各环节的深度融合，的确给人们的旅行带来很多（），例如扫一扫二维码就能收到景点的介绍。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"便利"},{"label":"B","content":"选择"},{"label":"C","content":"趣味"},{"label":"D","content":"快捷"}],"answer":"A","explanation":"“例如扫一扫二维码就能收到景点的介绍”是对空缺处词语的解释，即文段强调的是互联网给人们的旅行带来了方便，“便利”填入恰当。","no":8},{"id":"1718789646121","type":"single","material":"","stem":"科学研究的各种方法，都有各自不同的优劣势，都有不同的（）领域。研究者选择不同的研究方法，往往意味着选取了不同的研究（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"特长;结果"},{"label":"B","content":"适合;方向"},{"label":"C","content":"适用;思路"},{"label":"D","content":"使用;目的"}],"answer":"C","explanation":"第一空，句意为研究方法各有优劣，都有自己适合应用的领域。“特长”即专长，特别的长处，适用对象为人，不能用于“研究方法”,排除A<br>第二空，科学研究通常是先选择研究方向和研究目的，再根据方向和目的选择“研究方法”,方法选定了，则可由此确定研究思路。因此应选“思路”,排除B、D","no":9},{"id":"1718789646122","type":"single","material":"","stem":"干部走进基层，在实践中增长（），是锻炼干部、培养人才的重要途径。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"才学"},{"label":"B","content":"才华"},{"label":"C","content":"才干"},{"label":"D","content":"才智"}],"answer":"C","explanation":"“才学”侧重于学问；“才华”指表现于外的才能(多指文艺方面)“才干”指办事的能力；“才智”侧重于智力。根据文段中的“干部”“实践”“锻炼”可知，“才干”填在此处最恰当。","no":10},{"id":"1718789646123","type":"single","material":"","stem":"一个作家要成为著名作家、伟大作家，就不能做时代的旁观者，而是要以“在场者”的姿态切入当下，展现社会（），反映民生疾苦，歌颂人性光辉。即使写小人物，也可写出生活的幽微之处和时代的现实关照，给主人公（）上时代光影，濡染上时代色彩。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"责任;描绘"},{"label":"B","content":"全貌;描摹"},{"label":"C","content":"现实;映射"},{"label":"D","content":"变迁;投射"}],"answer":"D","explanation":"第一空，句中说的是作家应关注当下，反映当前的社会状况。“责任”与“展现”搭配不当，排除A“全貌”范围过大，作家的笔下应是有代表性的社会图景，排除B<br>第二空，与“映射”相比，“投射”体现的主动性更强，与此处作家应给主人公照射上时代光影的语境更符合。","no":11},{"id":"1718789646124","type":"single","material":"","stem":"广义相对论发表以来，一直是最成功的引力理论，已经（）了无数次的天文观测和各种实验的检验。但是几乎所有这些都是在弱引力场下，检验爱因斯坦引力和牛顿引力的微小差别。如果想使爱因斯坦引力的效应比较明显，则需要在强引力场中才能发生，而这方面的检验还是非常（）的。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"经历;罕见"},{"label":"B","content":"经过;需要"},{"label":"C","content":"通过;迫切"},{"label":"D","content":"经受;缺乏"}],"answer":"D","explanation":"第一空，“经历”指亲身见过、做过或遭受过，一般用于人，排除A“经过”“通过”“经受”填入均恰当。<br>第二空，与前文的“无数次的天文观测和各种实验的检验”表达的弱引力场方面检验多的语境构成反义对应，强引力场方面的检验应是比较少的，所填词语应体现出“少”的意思。“需要”指对事物的欲望或要求；“迫切”指需要到难以等待的程度，强调十分急切。两者均未体现“少”之意，排除B、C“缺乏”指(所需要的、想要的或一般应有的事物)没有或不够，符合句意。","no":12},{"id":"1718789646125","type":"single","material":"","stem":"环保的每一点进步，都离不开生活方式的（）。在这方面得到群众的支持，跟在治理雾霾上取得共识同等重要。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"提高"},{"label":"B","content":"转变"},{"label":"C","content":"提升"},{"label":"D","content":"转化"}],"answer":"B","explanation":"“提高”“提升”常与“水平”“质量”等搭配，与“方式”搭配不当，排除A、C“转化”常与“成果”“矛盾”等搭配，“转变”常与“思路”“方式”等搭配，此处与“生活方式”搭配，应选“转变”。","no":13},{"id":"1718789646126","type":"single","material":"","stem":"在新一轮国际秩序的重构中，国际社会对中国寄予（），我们不仅应该自觉地（）起区域乃至全球治理的责任，而且要善于提出中国方案，贡献中国智慧。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"热望;担当"},{"label":"B","content":"厚望;承担"},{"label":"C","content":"希望;承接"},{"label":"D","content":"期望;担任"}],"answer":"B","explanation":"第二空，“担当”一般与“角色”搭配，“承担”一般与“责任”搭配，“承接”一般与“工作”搭配，“担任”一般与“职务”搭配。文段中与“责任”搭配，用“承担”恰当，排除A、C、D第一空，“寄予厚望”为习惯搭配。","no":14},{"id":"1718789646127","type":"single","material":"","stem":"读书时对感兴趣的东西深钻细研，无疑有助于我们更全面、系统、深入地了解这些东西。但不感兴趣的东西，有的也可能恰恰是我们所（）的。这不仅因为兴趣本身有一定的局限性，而且因为在特定领域浸染日久，往往会（）这种兴趣，形成越不感兴趣越排斥的恶性循环，导致短板更短。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"需要;泛化"},{"label":"B","content":"忽视;僵化"},{"label":"C","content":"欠缺;固化"},{"label":"D","content":"提倡;弱化"}],"answer":"C","explanation":"本题主要从第二空解题。由“形成越不感兴趣越排斥的恶性循环”可知，在特定领域浸染久了后会强化这种兴趣，A项“泛化”、D项“弱化”都与句意不符，排除。“僵化”一般与“思想”搭配，与“兴趣”不搭配，排除BC项“固化”符合句意。第一空，“欠缺”填入也能与后文“短板更短”互相照应。","no":15},{"id":"1718789646128","type":"single","material":"","stem":"宪法是治国安邦的总（），是党和人民意志的集中（）。在我们党治国理政活动中具有十分重要的地位和作用。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"规范;呈现"},{"label":"B","content":"章法;展现"},{"label":"C","content":"章程;体现"},{"label":"D","content":"标准;表现"}],"answer":"C","explanation":"第一空，由“宪法是治国安邦的总”可知，横线处应填入一个形容“宪法”在“治国安邦”中重要作用的词语。“规范”指约定俗成或明文规定的标准；“章法”指文章的组织结构，比喻办事的程序和规则；“章程”指书面写定的组织规程或办事条例；“标准”指衡量事物的准则。宪法是一国的根本法，规定国家的根本任务和根本制度等，“总章程”更符合宪法的定位，排除A、B、D验证第二空，“体现”指某种性质或现象在某一事物上具体表现出来，用于描述宪法与党和人民意志的关系也恰当。","no":16},{"id":"1718789646129","type":"single","material":"","stem":"在“地球村”形势下，21世纪的人类需要面对的共同问题远远超过各民族（）的利益。我们不应把东方文化同西方文化（）起来。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"狭隘;对立"},{"label":"B","content":"各自;混淆"},{"label":"C","content":"有限;统一"},{"label":"D","content":"根本;联系"}],"answer":"A","explanation":"第一空，“各自”填入与“各民族”有语义重复之嫌，排除B其他三项不好判断，跳过。第二空，分析可知，文段强调的是“地球村”形势下各民族联系紧密，东西方文化不应割裂、对立。“对立”填入恰当，“统一”“联系”填入均与句意相悖，排除C、D","no":17},{"id":"1718789646130","type":"single","material":"","stem":"总理在两会上所做的政府工作报告是一个（）民心、（）民意、体现民情的报告，也是一个增强信心、鼓舞士气、催人奋进的报告。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"代表;反应"},{"label":"B","content":"表现;反映"},{"label":"C","content":"表现;反应"},{"label":"D","content":"代表;反映"}],"answer":"D","explanation":"第一空，由常识可知，政府工作报告是一个汇集民心，表达民众意见的报告。“代表”指代替个人或集体办事或表达意见；“表现”指表示出来。填入“代表”更符合语境，排除B、C<br>第二空，“反应”指机体受到体内或体外的刺激而引起相应的活动或变化；事情所引起的意见、态度或行动。“反映”指把情况、意见等告诉上级或有关部门，比喻把客观事物的实质表现出来。政府工作报告是民意的表现，应选“反映”,排除A","no":18},{"id":"1718789646131","type":"single","material":"","stem":"一个人不能失忆，一个国家当然就更不能失忆了，但是我们这个国家因为历史的原因使得有时候会有意无意地试图（）某方面的回忆。对于这种无奈的现实，我们能够理解，但是并不是说就应该支持或者默许这么做。在具备了条件之后，我们还是应该寻找和（）我们的记忆。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"回避;恢复"},{"label":"B","content":"隐藏;修复"},{"label":"C","content":"躲避;还原"},{"label":"D","content":"掩盖;复原"}],"answer":"A","explanation":"第一空，填入词语修饰的是“回忆”。“躲避”指故意离开或隐蔽起来；离开对自己不利的事物。它通常用于人或者困难，不能与“回忆”搭配，排除C<br>第二空，“恢复”通常用于还原事物状态；“修复”通常用于被损坏的事物；“复原”通常指恢复健康。“恢复记忆”为常见表述，排除B、D","no":19},{"id":"1718789646132","type":"single","material":"","stem":"这些亮相于世界互联网大会的中国创新成果，勾勒出未来生活的诱人（），也（）着“创新中国”的蓬勃生机。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"图景;彰显"},{"label":"B","content":"图画;呈现"},{"label":"C","content":"画面;凸显"},{"label":"D","content":"景象;显示"}],"answer":"A","explanation":"第一空，由“勾勒”可知，其对象应与构图相关。而“画面”多与“拍摄”“记录”搭配，“景象”多与“描绘”搭配，排除C、D第二空，“彰显”指鲜明地显示；“呈现”指显出、露出。“彰显”语义程度更重，更能突出这些创新成果的象征意义。","no":20},{"id":"1718789646133","type":"single","material":"","stem":"“直播”不等于年轻貌美的网红，当“直播+正能量”成为新（），就可以（）网络让正能量得到广泛的传播，让这一新媒体成为关注生活、融入生活、积极担当的新工具。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"风尚;倚重"},{"label":"B","content":"风范;倚重"},{"label":"C","content":"风尚;借助"},{"label":"D","content":"风范;借助"}],"answer":"C","explanation":"第一空，“风尚”指在一定社会时期中社会上流行的风气和习惯；“风范”指风度，气派。此处句意为“直播+正能量”成为新的社会流行风气，应选“风尚”,排除B、D<br>第二空，“倚重”指依靠，器重；“借助”指靠别的人或事物的帮助。此处的“网络”是正能量得以传播的媒介和平台，对正能量的传播起到的是辅助的作用，用“借助”恰当。","no":21},{"id":"1718789646134","type":"single","material":"","stem":"<p>作为一个单纯的图书设计者，设计师需要尊重书籍本身而适度地（ &nbsp; ）自己，即不能“过度设计”而使形式僭越了书籍内容。但是，作为一个创意表达者，设计师一旦参与了图书的创作，就使书籍成为表达自己独特创意的（ &nbsp; ），此时设计师已不仅仅干预了图书的形式，而是直接参与了内容的创作。</p><p>填入括号部分最恰当的一项是：</p>","options":[{"label":"A","content":"压抑;工具"},{"label":"B","content":"贬低;渠道"},{"label":"C","content":"遗忘;符号"},{"label":"D","content":"隐藏;媒介"}],"answer":"D","explanation":"第一空，由“不能‘过度设计’而使形式僭越了书籍内容”可知，句中强调的是图书设计者要为图书内容服务，不可过于彰显自己的风格，避免喧宾夺主。“贬低”指故意对人或事物给以较低的评价，据此排除B“压抑”指对感情、力量等加以限制，不适用于设计师对自己风格收敛的语境，排除A第二空，“书籍”是设计师表达自己创意的载体和形式。“符号”指记号、标记，“媒介”有介质和方式的意思，“媒介”填入更恰当。","no":22},{"id":"1718789646135","type":"single","material":"","stem":"“学如弓弩，才如箭镞。”学识是才能的（），才能是学习的（）学习的弓弩弯如满月，才识的箭才能飞似流星。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"基调;升华"},{"label":"B","content":"基本;延伸"},{"label":"C","content":"指导;释放"},{"label":"D","content":"引导;发挥"}],"answer":"D","explanation":"文段把“学识”与“才能”的关系比喻成弓与箭的关系，没有弓(学识),箭(才能)没有方向；没有箭(才能),弓(学识)的自身价值就无法实现。第一空强调的是学识对才能的导向作用。首先排除与此意不符的A、B“指导”常与“学习”“工作”搭配，“引导”常与“方向”搭配，考虑弓与箭的比喻，“引弓射箭”为习惯搭配，故此处用“引导”更恰当，排除C<br>验证第二空，“发挥”指把内在的性质或者能力表现出来，“发挥才识”搭配恰当。","no":23},{"id":"1718789646136","type":"single","material":"","stem":"人口迁移改变了中国城乡的人口格局，以最（）的方式推动了移民城市的形成，这一城市形态与传统的（）城市在性质上有着本质的区别。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"直接;地域"},{"label":"B","content":"一般;地方"},{"label":"C","content":"简单;地区"},{"label":"D","content":"基本;区域"}],"answer":"A","explanation":"第一空，通过人口迁移推动移民城市的形成，这样的方式具有目标明确、效果显著的特点，“直接”“简单”填入恰当，“一般”“基本”不符合语境，排除B、D<br>第二空，“地域城市”是与“移民城市”相对的概念，前者具有明显的地域性特征，后者则因大量移民的融入打破了地域的限制。文段中说的是与移民城市相对的形态，“地域”填入更恰当。<br>行","no":24},{"id":"1718789646137","type":"single","material":"","stem":"现代白话文与文言文的区别只是语体的不同，但它们使用的象形表意的方块字，作为中华民族文化的独特创造，其中（）的民族精神、民族生命是血脉（）的。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"蕴含;贯通"},{"label":"B","content":"沉积;相通"},{"label":"C","content":"呈现;流通"},{"label":"D","content":"体现;连通"}],"answer":"A","explanation":"第一空，“民族精神、民族生命”是沉淀在方块字这一文化形式之中的，“呈现”“体现”均表示显现在外面，填入不合语境，排除C、D<br>第二空，“贯通”的“贯”体现出了方向性，恰与文段中“文言文”与“白话文”的时间性相对应，“相通”不含有这层意思，排除B","no":25},{"id":"1718789646138","type":"single","material":"","stem":"在养老举措、制度设计等各方面（）更多“老吾老以及人之老”的同理心，是一座城市、一个社会对待老年人应有的温情与敬意。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"灌注"},{"label":"B","content":"灌溉"},{"label":"C","content":"灌输"},{"label":"D","content":"灌制"}],"answer":"A","explanation":"“灌溉”指把水输送到田地里，如灌溉农田；“灌制”指用录音设备录制，如灌制唱片。二者均不能与“同理心”搭配，排除B、D“灌注”侧重“注”,即注入；“灌输”侧重“输”,即传送。文段是说要把“老吾老以及人之老”的同理心融入、渗透进养老举措、制度设计中，“灌注”填入更恰当。","no":26},{"id":"1718789646139","type":"single","material":"","stem":"和西方的《荷马史诗》《圣经》一样，中国历史上早期的一些典籍获得了备受（）的地位。当然，这些典籍之后无一例外地经受了历史时代的文本筛选、价值（）的复杂过程。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"尊崇;阐释"},{"label":"B","content":"膜拜;诠释"},{"label":"C","content":"拥戴;注释"},{"label":"D","content":"青睐;解释"}],"answer":"A","explanation":"第一空，文段以西方的《荷马史诗》《圣经》类比中国早期的一些典籍在中国的地位。“膜拜”表示极端恭敬或畏服的行礼方式，多形容对某人崇拜得五体投地，不能描述对“典籍”的态度，且与“备受”搭配不当，排除B“青睐”意为喜爱，程度过轻，且不能描述“地位”,排除D<br>第二空，“阐释”意为解释说明，“注释”多指对文本的解释。对“价值”的阐发说明，选“阐释”更恰当。","no":27},{"id":"1718789646140","type":"single","material":"","stem":"只有一个人静静对内心（）着自己的人生故事，其中最为充实、最有意义的那段，会被你们做出的一系列决定所填满。最终，是选择（）了我们的人生。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"诉说;决定"},{"label":"B","content":"讲述;塑造"},{"label":"C","content":"叙述;描绘"},{"label":"D","content":"描述;修正"}],"answer":"B","explanation":"第一空，四个词语均可与“人生故事”搭配，较难排除，分析第二空。<br>第二空，由“最为充实、最有意义的那段，会被你们做出的一系列决定所填满”可知，句中强调的是人生是由一系列选择串联而成的，是选择成就了我们的人生。“描绘”指描画，未体现出选择对人生的影响之意，排除C“修正”指修改使正确，文段并未体现“有错”之意，且其常见搭配为“修正错误”,排除D与“决定”相比，“塑造”与“人生”搭配更恰当，排除A","no":28},{"id":"1718789646141","type":"single","material":"","stem":"不可否认，（）阻隔，是阻碍情感交流的一个重要原因。但无论是语音聊天，还是视频通信，其（）便是不断缩短空间的距离。我们或许无法做到“父母在，不远游”，但至少可以多跟家人分享一下自己的喜怒哀乐，让父母在亲情的喃语中得到心灵的慰藉。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"时空;意义"},{"label":"B","content":"地域;初衷"},{"label":"C","content":"环境;作用"},{"label":"D","content":"信息;目的"}],"answer":"B","explanation":"第一空，与后文“不断缩短空间的距离”中的“空间”相对应，第一空填“地域”最恰当，排除A、C、D第二空填入“初衷”也契合文意。","no":29},{"id":"1718789646142","type":"single","material":"","stem":"乡镇政府作为国家最基层的一级政府，（）的工作十分复杂，（）的压力十分巨大。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"承担;承载"},{"label":"B","content":"承担;承受"},{"label":"C","content":"承接;承受"},{"label":"D","content":"承接;承载"}],"answer":"B","explanation":"第一空，“承接”侧重于“接”,表交接、接受之意。“承担”侧重于“担”,表担负、担当之意。基层政府的工作是其职责所在，是必须要做的，不存在接不接受的问题，因此选“承担”更恰当，排除C、D<br>第二空，“承载”多与“梦想”“思念”“回忆”等褒义词语搭配，与“压力”搭配，选“承受”恰当，排除A","no":30},{"id":"1718789646143","type":"single","material":"","stem":"对大多数人来说，逻辑学是一门（）的学问。但是思想史上的重大事件无一不是（）人们在自己的思维和研究方法上所做的改进。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"神秘;处于"},{"label":"B","content":"枯燥;基于"},{"label":"C","content":"神奇;源于"},{"label":"D","content":"烦琐;由于"}],"answer":"B","explanation":"第一空，由“但是思想史上的重大事件无一不是人们在自己的思维和研究方法上所做的改进”可知，前文对逻辑学的评价应该是较为负面的，排除C<br>第二空，“处于”强调所处的阶段，“基于”强调依据的条件，“由于”强调引起的原因。句意为思想史上的重大事件都是人们在自己的思维和研究方法的基础上所做的改进。“基于”填入符合句意，排除A、D","no":31},{"id":"1718789646144","type":"single","material":"","stem":"各国在对外交往中常常会形成一套相对（）的话语体系，特别是拥有自己的核心话语。对外话语不仅体现一国的外交政策，更（）了一国对外沟通的基本态度和价值。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"灵活;承载"},{"label":"B","content":"独立;说明"},{"label":"C","content":"固定;代表"},{"label":"D","content":"集中;体现"}],"answer":"C","explanation":"第一空，对应后文的“体现一国的外交政策……一国对外沟通的基本态度和价值”,“外交政策”“基本态度”和“价值”都具有相对稳定性，相应地，话语体系也不应过于灵活，“固定”填入更能体现出外交话语体系的严肃性。<br>验证第二空，此处所填词语应与“体现”意思相近，表达对外话语与一国对外沟通的基本态度和价值之间的现象和本质的关系。“代表”填入符合句意。","no":32},{"id":"1718789646145","type":"single","material":"","stem":"青山隐隐，芳草萋萋，春天的脚步总是来去匆匆。“二月里来好春光”的余音还在耳畔（），（）之间便到了细雨纷纷、祭扫亲人的清明时节。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"缭绕;蓦然"},{"label":"B","content":"回响;忽然"},{"label":"C","content":"飘荡;遽然"},{"label":"D","content":"萦绕;倏忽"}],"answer":"D","explanation":"第一空，“回响”多用于形容澎湃激荡的乐章，与“二月里来好春光”的柔婉语境不符，排除B<br>第二空，文段主要表达的意思是时间飞逝，时光短暂，因此此处应填入一个形容时间过得很快的词语，“倏忽”恰有此意。“蓦然”和“遽然”侧重强调突然，排除A、C","no":33},{"id":"1718789646146","type":"single","material":"","stem":"如今越来越多没营养的综艺节目占据了市场的（），而《朗读者》却别具一格，“慢下来”用“朗读”做电视，这才是真正稀缺而有价值的电视文化。《朗读者》证明文化类节目未必“冷”。《朗读者》节目组把这份对精神文化的尊重（）到节目中来。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"主体;移植"},{"label":"B","content":"主流;传达"},{"label":"C","content":"首席;延伸"},{"label":"D","content":"份额;演绎"}],"answer":"A","explanation":"第一空意在说明目前没营养的综艺节目在市场上占据的地位，“占<br>据了首席”搭配不当，排除CD项，“份额”填入不能明确体现其在市场上的地位，排除。<br>第二空，此处说的是《朗读者》节目组把对精神文化的尊重引入节目中来。“传达”指转告，把一方的意思告诉另一方，用在这里与句意不符，排除B","no":34},{"id":"1718789646147","type":"single","material":"","stem":"在经济社会不断发展的今天，我们应将明礼知耻（）于社会主义核心价值观的实践中。同时，应（）古今中外礼仪礼教之精华，把明礼提升到一个新高度、新水平。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"贯穿;融汇"},{"label":"B","content":"贯彻;融合"},{"label":"C","content":"落实;吸取"},{"label":"D","content":"实行;继承"}],"answer":"A","explanation":"第一空，“贯彻”指彻底实现或体现；“落实”指落到实处，能够实现。两者搭配对象一般是方针、政策等，而“明礼知耻”是一种观念，搭配不当，排除B、C<br>第二空，“继承”适用于后人对前人的作风、文化、知识等的接受。对“古今中外”中“今人”的精华不能用“继承”,排除D“融汇”指融合汇聚，且“融汇古今”为常见搭配。","no":35},{"id":"1718789646148","type":"single","material":"","stem":"只要观察一下语言的变迁史，就会发现，语言体系一直具有强悍的自我（）机制，会以一种温和的集体（）模式，淘汰那些失效的语词。这意味着语言会利用时间效应来进行自我筛选和自我净化，只有数量很少的新语词能够穿越这种“时间筛子”，成为上一历史时段的“舌尖遗产”。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"更新;清洁"},{"label":"B","content":"完善;舍弃"},{"label":"C","content":"过滤;遗忘"},{"label":"D","content":"修正;扫除"}],"answer":"C","explanation":"第一空，由“淘汰那些失效的语词”“自我筛选”“自我净化”可知，填入词语应能体现这种筛选功能，“过滤”“修正”符合文意，排除A、B<br>第二空，对“温和的模式”而言，“扫除”过于强硬，排除D","no":36},{"id":"1718789646149","type":"single","material":"","stem":"①德国总理昨天在德法首脑（）中，试图弥合法国与美国在关贸总协定谈判方面的分歧，但没有取得进展。<br>②走上政商关系极端的商人和腐败官员们，通过政策资源的货币化完成了权力（）和利益输送，实现了“特权的获取”。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"会晤;勾兑"},{"label":"B","content":"会见;勾兑"},{"label":"C","content":"会晤;挤兑"},{"label":"D","content":"会见;挤兑"}],"answer":"A","explanation":"①句，“会晤”与“会见”都有会面的意思，但“会晤”专指领导人之间的会面，更符合首脑会面的语境，排除B、D<br>②句，“挤兑”指许多人到银行里挤着兑现。“勾兑”指把不同的酒适量混合，并添加调味酒，进行配制；常用来指为达成某一目的而进行的不便于公开的活动，多指暗箱操作之事。此处指的是官员和商人的权钱交易，应选“勾兑”,排除C","no":37},{"id":"1718789646150","type":"single","material":"","stem":"卫星轨道数据是一类需要严格保密的数据，卫星所有人将卫星的位置和运行路线视为机密资料。拥有卫星的那些企业担心泄密会使自己丧失竞争（），因为把（）的定位信息泄露出去，可能会向竞争对手暴露自己的实力，政府也担心这会危害国家安全。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"机遇;隐藏"},{"label":"B","content":"筹码;详细"},{"label":"C","content":"优势;确切"},{"label":"D","content":"能力;准确"}],"answer":"C","explanation":"第一空，由“把的定位信息泄露出去，可能会向竞争对手暴露自己的实力”可知，泄密会使企业在竞争中处于劣势，相应地，丧失的应是竞争“优势”。“筹码”多与“谈判”搭配，与“竞争”搭配不当，排除B丧失竞争能力的表述过于绝对，排除D第二空，描述“定位信息”,“确切”比“隐藏”更恰当，排除A","no":38},{"id":"1718789646151","type":"single","material":"","stem":"①现在果园开始（），老村长觉得要做的事情依然很多，“种果树看似简单，其实不简单”。<br>②在遇难宇航员的追悼会上，当罗明杰最后说“他们永远活在我们心中，我们微笑着等待他们回来”时，表情一直轻松的他忍不住流下了眼泪，会场一片（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"盈利;唏嘘"},{"label":"B","content":"营利;叹息"},{"label":"C","content":"营利;唏嘘"},{"label":"D","content":"盈利;叹息"}],"answer":"A","explanation":"①句，“盈利”指扣除成本后获得的利润，与“亏损”相对；“营利”指谋求利润，与“公益”相对。句中说的是果园开始赚钱了，排除B、C<br>②句，“唏嘘”指哭泣后不自主地急促呼吸，“叹息”指叹气。对应前文的“他忍不住流下了眼泪”以及追悼会的语境可知，“唏嘘”填入更恰当，排除D","no":39},{"id":"1718789646152","type":"single","material":"","stem":"在经济全球化时代，面对多元文化思潮的交流与交锋，人们常常有精神迷失的困惑。如何（）西方文化思潮的渗透，始终保持本民族的文化特色？如何实现精神富有，（）起源源不断的精神力量？这些都是当代文化发展需要深入思考的命题。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"抵挡;集聚"},{"label":"B","content":"抵触;汇集"},{"label":"C","content":"抵御;汇聚"},{"label":"D","content":"抵制;积累"}],"answer":"C","explanation":"第一空，“抵触”指跟另一方有矛盾，如抵触情绪、相互抵触等，用在表达阻止西方文化思潮渗透的语境中不恰当，排除B“抵挡”侧重于“挡”,即被动应对；“抵御”侧重于“御”,即主动防御；“抵制”侧重于“制”,即控制、制衡。综合分析三个词语，“抵御”填人更能体现出面对西方文化思潮渗透应具有的积极防备态度。<br>验证第二空，“汇聚力量”搭配亦恰当。","no":40},{"id":"1718789646153","type":"single","material":"","stem":"<p>当企业逐步完成原始积累后，企业家都开始思考更深层次的问题，越来越多的企业家不再（ &nbsp;）自己的信仰，其中就有人开始从名利场走向教堂。这种心灵（ &nbsp;）将如何改变企业的发展，现在尚不明朗。</p><p>填入括号部分最恰当的一项是：</p>","options":[{"label":"A","content":"忌讳;皈依"},{"label":"B","content":"避讳;回归"},{"label":"C","content":"忌讳;回归"},{"label":"D","content":"避讳;皈依"}],"answer":"D","explanation":"第一空，“忌讳”指因风俗习惯或个人原因等，对某些言语或举动有所顾忌，积久成为禁忌；“避讳”指不愿说出或听到某些会引起不愉快的字眼儿，回避。“忌讳”与“信仰”搭配不当。此处表达的是对信仰问题的回避、掩饰态度，应选“避讳”,排除A、C第二空，“回归”指回到原来的地方；“皈依”为宗教用语，泛指虔诚地信奉佛教或参加其他宗教组织。对应前文的“从名利场走向教堂”,“皈依”填入更恰当，排除B","no":41},{"id":"1718789646154","type":"single","material":"","stem":"在进化心理学理论中，人类的情绪可以指引和（）我们的行为，从而更好地适应周围的环境。早在远古时代，原始人处于（）的环境中，就会产生防卫反应，比如，当有野兽进入自己的领域时，便开始不安和愤怒，并试图用凶狠的表情和咆哮吓走侵入者。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"调控;危险"},{"label":"B","content":"改善;不利"},{"label":"C","content":"影响;动荡"},{"label":"D","content":"支配;陌生"}],"answer":"A","explanation":"第一空所填词语应与“指引”并列，表达人类情绪对行为的影响。“改善”常与“生活”“环境”等搭配，不能与“行为”搭配，排除B再看第二空，对应“就会产生防卫反应”以及“比如”后“野兽进入自己的领域”的例子，可知此处原始人所处的环境是“危险”的，对应A“动荡”指不稳定，不平静。环境动荡不一定就会产生防卫反应，排除C“陌生”指不熟悉，与“野兽进入自己的领域”的例子不能构成对应，排除D","no":42},{"id":"1718789646155","type":"single","material":"","stem":"欧洲科学家历时两年，（）230万欧元，开发出了一种“智能安全摄像头”。这种“智能安全摄像头”能够利用电脑，以某种运算法则分析在公共场所拍下的录像画面，查找可疑（），从中发现潜在的安全威胁。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"耗费;行迹"},{"label":"B","content":"耗资;行迹"},{"label":"C","content":"耗资;形迹"},{"label":"D","content":"耗费;形迹"}],"answer":"C","explanation":"第一空，“耗资”指耗费资财；“耗费”指消耗，包括物力、财力等。此处与“230万欧元”搭配，“耗资”更恰当，排除A、D<br>第二空，“行迹”指行动的踪迹，如行迹无定；“形迹”指举动和神色，如形迹可疑。此处与“可疑”搭配，应选“形迹”。","no":43},{"id":"1718789646156","type":"single","material":"","stem":"法治和礼治发生在两种不同的社会（）中，这里所谓的礼治也许就是通常所谓的人治，但是礼治一词不会像人治一词那样容易引起（），以致有人觉得社会秩序是可以由个人好恶来维持的了。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"形态;歧义"},{"label":"B","content":"模式;偏差"},{"label":"C","content":"情态;误解"},{"label":"D","content":"形势;干扰"}],"answer":"C","explanation":"第二空，“歧义”指语言文字的意义不明确，有两种或几种可能的解释。“偏差”指运动的物体离开确定方向的角度；工作上产生的过分或不及的差错。“误解”指理解得不正确；不正确的理解。“干扰”指扰乱，打扰。“有人觉得社会秩序是可以由个人好恶来维持的了”是对“人治”的一种错误理解。故此处填“误解”最恰当。","no":44},{"id":"1718789646157","type":"single","material":"","stem":"党的十八大以来，中央以猛药去病、重典治乱的（），以刮骨疗毒、壮士断腕的（），不断加大党风廉政建设和巡视的力度，效果显著。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"意念;底气"},{"label":"B","content":"恒心;气势"},{"label":"C","content":"意志;气魄"},{"label":"D","content":"决心;勇气"}],"answer":"D","explanation":"第一空，较难入手辨析，可选择从第二空入手。<br>第二空，“底气”指基本的信心和力量；“气势”指(人或事物)表现出来的某种力量和形势；“气魄”指魄力、气势；“勇气”指敢作敢为、毫不畏惧的气魄。对应“刮骨疗毒、壮士断腕”,“勇气”填入最恰当。<br>验证第一空，“决心”指坚定不移的意志，用于描述中央“猛药去疴、重典治乱”的坚定态度也恰当。","no":45},{"id":"1718789646158","type":"single","material":"","stem":"很多人都说哭过之后他们感觉更舒服，这是因为哭泣能够（）紧张，（）情绪的平衡。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"缓冲;平复"},{"label":"B","content":"延缓;修复"},{"label":"C","content":"缓和;回复"},{"label":"D","content":"缓解;恢复"}],"answer":"D","explanation":"第一空，“缓冲”不接宾语，可首先排除。“延缓”多用于计划、时间，“缓和”多用于气氛，“缓解”多修饰病痛、情绪。与“紧张”这一情绪搭配，“缓解”更恰当。<br>第二空，“恢复平衡”为习惯搭配。","no":46},{"id":"1718789646159","type":"single","material":"","stem":"近年来，涉及权钱交易的违纪违法案件出现了一些新情况、新问题。为教育各级党员、领导干部严格自律，加大对涉及权钱交易行为的（）力度，《中共中央纪委关于严格禁止利用职务上的便利（）不正当利益的若干规定》日前印发。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"惩罚;牟取"},{"label":"B","content":"惩处;牟取"},{"label":"C","content":"惩处;谋取"},{"label":"D","content":"惩罚;谋取"}],"answer":"C","explanation":"第一空，“惩处”除了含有惩罚的意思外，还有“处置”的意思。对于涉及权钱交易的行为，并非一罚了事，而是要根据不同情况做出不同处置，故“惩处”填入更恰当，排除A、D<br>第二空，“谋取”和“牟取”都有获取不正当利益的意思，但“谋取”的“谋”含有设法谋求的意思，与“利用职务上的便利”更能构成呼应，且“谋取利益”为习惯搭配。","no":47},{"id":"1718789646160","type":"single","material":"","stem":"会议强调，要牢固树立大边防观念，（）和谐边疆，铸就稳固边防。要建设繁荣富裕的边防，把强边固防和兴边富民有机统一起来，互相促进、双向发展，努力（）边防建设的良好氛围。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"构架;塑造"},{"label":"B","content":"架构;制造"},{"label":"C","content":"构建;营造"},{"label":"D","content":"建构;打造"}],"answer":"C","explanation":"第二空，“塑造”常与“形象”搭配，“制造”常与“产品”“矛盾”“机会”搭配，“打造”常与“品牌”“口碑”搭配，三词均不能与“氛围”搭配，排除A、B、D“营造……氛围”为习惯搭配。<br>第一空，“构建和谐社会”为常用表述。由此推知，“构建和谐边疆”搭配恰当。","no":48},{"id":"1718789646161","type":"single","material":"","stem":"在诗的最后一节，诗人写出了现代文明的冲击对他本人的影响。从寥寥数笔的（）中，我们不难体味到诗人对现代文明的大胆（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"描绘;捉弄"},{"label":"B","content":"刻画;嘲讽"},{"label":"C","content":"勾勒;嘲弄"},{"label":"D","content":"勾画;玩弄"}],"answer":"C","explanation":"第一空，由“寥寥数笔”可知，此处诗人是简略勾画，而不是细致地“描绘”或“刻画”,首先排除A、B“勾勒”指用线条画出轮廓；用简单的笔墨描写事物的大致情况。“勾画”指勾勒描绘；用简短的文字描写。C、D两项均符合题意。<br>第二空，“嘲弄”是以语言嘲笑，“玩弄”是以行为戏弄。诗人以诗歌表达对现代文明的态度，“嘲弄”填入恰当，排除D","no":49},{"id":"1718789646162","type":"single","material":"","stem":"芭蕾这门艺术不仅要用肢体演绎，还需要文化的全方位（）和浸染，否则（）的就不只是四肢，而是整个形态和表演。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"熏陶;僵硬"},{"label":"B","content":"培养;笨拙"},{"label":"C","content":"洗礼;死板"},{"label":"D","content":"渗透;禁锢"}],"answer":"A","explanation":"第一空所填词语应与“浸染”并列，表达文化对芭蕾潜移默化的影响。“培养”“洗礼”与此不符，排除B、C“渗透”与“浸染”连用，有语义重复之嫌，排除D<br>第二空填入“僵硬”也能与芭蕾“柔软”“轻灵”的特性相对应。","no":50},{"id":"1718789646163","type":"single","material":"","stem":"在偶像级人物的背后，往往有追逐经济利益的资本力量的（），它们利用舆论制造全民的娱乐狂欢，以此牟利。因此，对于追星现象，我们也要保持一分清醒，在狂热追星之前，看一些不同角度不同观点的文章，多一些思考和冷静，就不会（）。一旦看清偶像背后的真相，就不会轻易陷入狂热与沉迷。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"操纵;迷失"},{"label":"B","content":"操控;盲从"},{"label":"C","content":"挟制;冲动"},{"label":"D","content":"辖制;跟风"}],"answer":"B","explanation":"第一空，“挟制”指依仗权势使其顺从，“辖制”指管束，二者的主语一般都为人，不适于搭配“资本力量”,排除C、D“操纵”指随着自己的意向来把持支配；“操控”指操纵控制，A、B两项符合句意。<br>第二空，“迷失”多指分不清方向、找不到路；“盲从”多指不问是非地附和别人。“因此”后为文段观点，与“追星”“保持清醒”相对应，填入“盲从”更合适。","no":51},{"id":"1718789646164","type":"single","material":"","stem":"回顾历史，（）东方文化与西方文化的渊源，打破将西方文化等同于现代文化的逻辑，将西方文化（）为一个地域性文化，有助于我们今天确立文化自信。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"明白;看作"},{"label":"B","content":"了解;贬抑"},{"label":"C","content":"熟悉;回归"},{"label":"D","content":"明晰;还原"}],"answer":"D","explanation":"第一空，文段说的是弄清楚东方文化和西方文化的渊源。“熟悉”较为口语化，不符合文段较为正式的风格，排除C<br>第二空，“看作”后不能加介词“为”,排除A“贬抑”指贬低并压制，西方文化本身就是一个地域性文化，不需要贬低压制，排除B","no":52},{"id":"1718789646165","type":"single","material":"","stem":"对当代中国而言，研究草原文化的意义并非仅仅为了表现文化由精细走向（），由典雅走向质朴，而是要透过草原民俗与草原风情，（）草原风貌中保存尚好的历史文化精髓以及民族的精神和灵魂。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"全面;传承"},{"label":"B","content":"简单;探寻"},{"label":"C","content":"粗犷;发掘"},{"label":"D","content":"豪放;领略"}],"answer":"C","explanation":"第一空所填词语应与“精细”构成反义关系对应，“全面”“简单”均与此不符，排除A、B<br>第二空，“领略”与“灵魂”不搭配，排除D“发掘”指把人们不容易发现的事物揭露或揭示出来，与“研究草原文化的意义”对应恰当。","no":53},{"id":"1718789646166","type":"single","material":"","stem":"社会在变，家庭也在变。但不管交通如何便捷，通信如何发达，过年回家，都是每个家庭最（）的梦想。此后时空流转，纵使百转千回，改善生活也好，追逐理想也罢，走出去的中国人，还是会被故土的浓烈情思所（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"美好;吸引"},{"label":"B","content":"寻常;羁绊"},{"label":"C","content":"朴实;牵绊"},{"label":"D","content":"终极;引领"}],"answer":"C","explanation":"第一空，所填词语修饰每个家庭过年回家的这种梦想，这种感情应该是朴素纯粹的。“美好”形容愿望等抽象事物好；“寻常”形容平常；“朴实”形容质朴踏实。三个词语填入均符合句意。“终极”指最终，填入语义程度过重，排除D<br>第二空，所填词语用于形容游子对故乡的留恋。“吸引”指把别人的注意力引到自己这方面来，不符合游子对故土眷恋的情感，排除A“羁绊”指被缠住了不能脱身，与题意不符，排除B“牵绊”意为牵挂思念，填入符合句意。","no":54},{"id":"1718789646167","type":"single","material":"","stem":"雪的可爱处在于它覆盖大地没有差别。冬夜拥被而眠，觉寒气袭人，蜷缩不敢动，凌晨张开眼皮，窗棂窗帘隙处有强光（），大异往日，起来推窗一看，啊！白茫茫一片银世界。竹枝松叶顶着一堆堆的白雪，杈芽老树也都镶了银边，朱门与蓬户同样的蒙受它的沾被，没有差别待遇。地面上的坑穴洼溜，冰面上的枯枝断梗，路面上的残刍败屑，全都罩在天公（）下的一件鹤氅之下。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"闪烁;撒"},{"label":"B","content":"闪映;抛"},{"label":"C","content":"闪现;洒"},{"label":"D","content":"映照;织"}],"answer":"B","explanation":"第一空，“闪烁”指光亮晃动不定、忽明忽暗。文中描述的是“雪”反射出来的光，不会存在“闪烁”的情况，排除A“闪现”指短暂地出现；忽然出现。它多形容“念头”“形象”等，用于此处不恰当，排除C<br>第二空，“织”多与“就”搭配，与“下”搭配不当，排除D“鹤氅”是“天公”从天上直接丢到大地上的，“抛”字更能体现下雪的特点。","no":55},{"id":"1718789646168","type":"single","material":"","stem":"网络对儿童而言是一把双刃剑，一方面可以让儿童更早（）现代人必备的网络知识和技能，为他们打开通往未知世界的大门；另一方面，过早触网也容易让儿童（）于网络游戏等虚拟空间不能自拔，容易对儿童的正常学习和成长造成影响和干扰。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"接触;沉溺"},{"label":"B","content":"触摸;享受"},{"label":"C","content":"了解;迷惑"},{"label":"D","content":"熟练;堕落"}],"answer":"A","explanation":"第一空，“触摸”指用手接触后轻轻移动，常与具体事物搭配，题干中“网络知识和技能”为抽象事物，排除B“熟练”指工作、动作等经常做而有经验，常见搭配为“熟练运用知识”“熟练掌握知识”,故“熟练”后不能直接跟“知识”,排除D“接触”指挨上，碰着；“了解”指知道得清楚。A、C两项填入均恰当。<br>第二空，文段意在表达儿童过早触网会使其沉迷网络游戏，影响其学习和成长。“迷惑”指辨不清是非、摸不着头脑，与题意不符，排除C“沉溺”指陷入不良的境地，不能自拔，符合题意。","no":56},{"id":"1718789646169","type":"single","material":"","stem":"海洋酸化会影响珊瑚、贝类等钙化生物的正常生长，（）它们的碳酸钙外壳，甚至对它们造成（）的影响，进而破坏整个食物链。为了保护自己，这些钙化生物会长得越来越小、外壳越来越厚，这会对食用贝类养殖产业造成很大的打击。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"腐化;恶劣"},{"label":"B","content":"腐蚀;致命"},{"label":"C","content":"侵蚀;严重"},{"label":"D","content":"侵入;深远"}],"answer":"B","explanation":"第一空，句中说的是海洋酸化对钙化生物的影响，其与钙发生化学反应，从而使碳酸钙外壳受到损害。“腐蚀”“侵蚀”程度较重，填入恰当。“腐化”“侵入”程度较轻，不符合文意，排除A、D<br>第二空，“甚至”提示此处所填词语程度应比伤害碳酸钙外壳的程度重，“致命”与“腐蚀”可构成递进关系。“严重”与“侵蚀”不能构成递进关系，排除C","no":57},{"id":"1718789646170","type":"single","material":"","stem":"网络主权概念的提出，意味着国家行使主权去维护网络安全，但网络空间的特殊性决定了政府作用有限。政府决策者应关注如何在维护网络主权的同时（）互联网行业的健康发展，并且在维护网络主权与行业发展之间寻求恰当的（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"保证;平衡"},{"label":"B","content":"保护;转换"},{"label":"C","content":"保障;立场"},{"label":"D","content":"保持;时机"}],"answer":"A","explanation":"第一空，“保证”“保护”“保障”“保持”四个词语填入均符合句意。<br>第二空，由“同时”可知，政府决策者既要维护网络主权，又要促进互联网行业的健康发展，即应二者兼顾，不可偏废。“转换”指改变，改换。“立场”指认识或处理问题时所处的地位和所抱的态度。“时机”指具有时间性的客观条件(多指有利的)。三者均未<br>体现出“兼顾”之意，排除B、C、D“平衡”意为使两端承受的重量相等，不倾斜，填入句中与语境最相符。","no":58},{"id":"1718789646171","type":"single","material":"","stem":"目前，我国杂技院团和杂技从业者以及杂技市场之间缺乏有效的（），杂技院团还未对市场有充分的了解，就（）锁定目标，按照杂技先练技巧再拼接的传统方法把节目先排出来，这样虽然能保证杂技表演的质量，但未必是目前杂技演艺市场最为需要的。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"磨合;精准"},{"label":"B","content":"磨合;盲目"},{"label":"C","content":"摩擦;精准"},{"label":"D","content":"摩擦;盲目"}],"answer":"B","explanation":"第一空，“磨合”比喻在彼此合作的过程中逐渐相互适应、协调；“摩擦”指因彼此利害矛盾而引起的冲突。句中表达的是杂技院团和杂技从业者以及杂技市场之间的关系未捋顺，创造出的杂技作品不能适应市场需要。“磨合”填入符合句意。排除C、D第二空，由“还未对市场有充分的了解”可知，杂技院团锁定的目标具有一定盲目性，并不“精准”,排除A","no":59},{"id":"1718789646172","type":"single","material":"","stem":"过去，城市规模基本上是由政策决定的。如果把城市当作一个（）的系统，它的吞吐、消耗以及内部运转，所有的生态流是完全能够定量计算的。我们的城市设计，必须跟周围的生态环境形成良好的共生关系，与其生态承载力相（）。根据周围生态承载力确立城市规模，才是科学态度。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"循环;支持"},{"label":"B","content":"封闭;匹配"},{"label":"C","content":"机械;符合"},{"label":"D","content":"动态;平衡"}],"answer":"B","explanation":"第一空，“循环”指事物周而复始地运动或变化；“动态”表明事物是变化发展的。两者均表明事物是变化的，与“完全能够定量计算”相悖，排除A、D“封闭”与“机械”相比，前者侧重于不与外界发生联系，后者侧重于刻板而不知变通。“封闭”与“内部运转”“能够定量计算”的语境更相符，排除C","no":60},{"id":"1718789646173","type":"single","material":"","stem":"冷静观察，直面现实，正视困难，我们的双脚就能站到（）的大地上，拥有牢固的立足点，就能看到远方的地平线，找到（）的方位感。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"结实;正确"},{"label":"B","content":"坚韧;精准"},{"label":"C","content":"坚实;准确"},{"label":"D","content":"坚硬;精确"}],"answer":"C","explanation":"第一空，“结实”多用来描述某物(如绳子)很牢固，或某人身体很健壮；“坚韧”指坚固有韧性，多用于描述意志；“坚硬”指又结实又硬，多用于描述石头。三词修饰“大地”均不恰当，排除A、B、D<br>验证第二空，“准确”与“方位感”搭配得当。","no":61},{"id":"1718789646174","type":"single","material":"","stem":"现代人对微信（）不已，乃至几乎不能有一朝一夕的分离，与其说是微信的功能强大，不如将之理解成空虚寂寞冷的人们，需要某种精神层面的（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"崇拜;皈依"},{"label":"B","content":"痴狂;抚慰"},{"label":"C","content":"眷恋;寄托"},{"label":"D","content":"痴迷;慰藉"}],"answer":"D","explanation":"第一空，“崇拜”指尊敬佩服，对象一般为人或团体；“眷恋”指思慕、爱恋，或依恋、怀念之情。此处形容“现代人对微信”的态度，“崇拜”“眷恋”均不恰当，排除A、C“痴狂”的“狂”含有疯癫、病态的意思，用来形容人们对微信的依赖，程度过重，排除B“痴迷”指深深地迷恋，符合句意。<br>将D项代入第二空验证，“慰藉”指安慰，符合句意，且“精神慰藉”为常见搭配。","no":62},{"id":"1718789646175","type":"single","material":"","stem":"S县城玲珑娇小，整洁可爱，人口不足五万，是个风光（）的疗养胜地。但川流不息的游客当中又有几人知晓这是在反动派（）过的废墟上建立起来的呢？<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"诱人;洗劫"},{"label":"B","content":"宜人;血洗"},{"label":"C","content":"迷人;血染"},{"label":"D","content":"诱人;掠夺"}],"answer":"B","explanation":"第一空，由“疗养胜地”可知，S城应该是非常宜居的，“迷人”“诱人”侧重有吸引力，都不能体现宜居这层含义，排除A、C、D<br>第二空，“血洗”能凸显县城曾经的惨状，与现状形成了鲜明对比。","no":63},{"id":"1718789646176","type":"single","material":"","stem":"纪录片也要注重挖掘人的情感和历史，因为一部好的纪录片不仅是对人和事物的简单（），更是对世界的（）发现。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"记录;独特"},{"label":"B","content":"记叙;独到"},{"label":"C","content":"记述;独立"},{"label":"D","content":"记载;独创"}],"answer":"A","explanation":"第一空，句子强调的是纪录片的作用，纪录片是影像声音文字的结合体，可以排除强调文字叙述的“记叙”“记载”,即B、D<br>第二空，“独立”与“发现”不搭配，排除C","no":64},{"id":"1718789646177","type":"single","material":"","stem":"马克思曾说，文明如果是（）地发展，而不是（）地发展，则留给自己的是荒漠。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"自由;自觉"},{"label":"B","content":"自发;自觉"},{"label":"C","content":"自由;自发"},{"label":"D","content":"自发;自然"}],"answer":"B","explanation":"由“是……不是……”可知，两空所填的词语构成反义对应关系。“自由”指不受约束，“自觉”指自己有所觉察醒悟，“自发”指不自觉地，“自然”指天然而非人工的。只有“自觉”与“自发”能构成反义对应关系。<br>“文明如果是自发地发展，而不是自觉地发展，则留给自己的是荒漠”这句话精辟地揭示了人类文明与自然环境之间的关系。人类在改造和利用自然的过程中，如果仅仅坚持极端人类中心主义的价值取向，失去对不适度攫取自然行为的控制，就会造成生态环境的整体破坏，最终自食其果，人类命运也会受到威胁。","no":65},{"id":"1718789646178","type":"single","material":"","stem":"装在司机座位上的这个系统可以在司机疲劳驾驶的时候，发出（）或者自动刹车。此外，这个系统不但可以提醒车辆被盗，还可以通过（）到的数据识别出盗贼的身份。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"警戒;采集"},{"label":"B","content":"警报;汇集"},{"label":"C","content":"警示;收集"},{"label":"D","content":"警告;搜集"}],"answer":"C","explanation":"第一空，“警戒”指为防备出各类问题而采取保障措施，与“发出”不能搭配，排除A“警报”指通过电台、电视、喇叭等发出的将有危险到来的通知或信号；“警示”指警告，启示；“警告”指对有错误或不正当行为的个人、团体、国家提出告诫，使认识所应负的责任。三者填入均符合句意。<br>第二空，“汇集”侧重于“汇”,即汇合；“收集”侧重于“收”,即接收；“搜集”侧重于“搜”,即搜罗。这个系统是装在司机座位上的，当盗贼偷盗车辆时，其会对盗贼的身份信息进行接收，故此处用“收集”最恰当，排除B、D","no":66},{"id":"1718789646179","type":"single","material":"","stem":"大脑的衰老和疾病已经成为影响社会发展的巨大负担。中国的脑科学计划需要攀登高峰的（），也需要接地气的先锋队。在社会资源有限的当下，如何（）两者，在不忘攀登高峰搞好基础研究的同时，造福社会大众，做好转化研究，是国家科技政策的决策者和基础研究的工作者都需要深思的问题。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"火车头;整合"},{"label":"B","content":"马前卒;协调"},{"label":"C","content":"多面手;兼顾"},{"label":"D","content":"排头兵;平衡"}],"answer":"D","explanation":"第一空，由横线后的“也”可知，此处所填词语应和“先锋队”构成并列关系。A项“火车头”比喻起带头作用或领导作用的人或事物，D项“排头兵”比喻带头的人或集体，二者填入均符合句意。“多面手”指擅长多种技能的人；“马前卒”比喻在前面奔走效力的人，二者均不含带头的意思，与“先锋队”并列不当，排除B、C<br>第二空，“整合”指通过整顿、协调重新组合；“平衡”指使两端承受的重量相等，不倾斜。由“……搞好基础研究的同时，造福社会大众”可知，此处强调的是要兼顾研究和应用两个方面，“平衡”二者之间的关系，排除A","no":67},{"id":"1718789646180","type":"single","material":"","stem":"<p>作为一种现代产权制度，知识产权制度的本质是通过保护产权形成（ &nbsp; ），“给天才之火添加利益之油”，使全社会创新活力（ &nbsp; ），创新成果涌流。</p><p>填入括号部分最恰当的一项是：</p>","options":[{"label":"A","content":"吸引;释放"},{"label":"B","content":"刺激;膨胀"},{"label":"C","content":"促进;凸显"},{"label":"D","content":"激励;迸发"}],"answer":"D","explanation":"第一空，由“给天才之火添加利益之油”可知，知识产权制度的本质在于通过使产权人获得经济利益的方式鼓励创新。“吸引”指把别的物体、力量或别人的注意力引到自己这方面；“促进”指促使前进，推动发展；“刺激”指推动事物，使起积极的变化。三者均未体现“鼓励”之意，排除A、B、C“激励”指激发鼓励，为管理学术语，包括物质激励、精神激励等方式，填入最符合句意。代入第二空验证，“活力迸发”搭配恰当。","no":68},{"id":"1718789646181","type":"single","material":"","stem":"所谓“儒商”，主要是指那些以儒家思想作为自己经营理念和行为（）的商人。这些商人在自己长期的商业实践中，把中国传统文化特别是儒家文化同商品经济法则互补（），形成了一种具有东方特色的商业文化精神——儒商精神。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"风范;整合"},{"label":"B","content":"风度;结合"},{"label":"C","content":"风习;融合"},{"label":"D","content":"风致;统合"}],"answer":"A","explanation":"第一空，“风习”指风俗习惯；“风致”指风味，风趣。二者填入句中均与“行为”搭配不当，排除C、D<br>第二空，“整合”指通过整顿、协调重新组合，“结合”指人或事物间发生密切联系。二者相比，“整合”所表达的重新组合之意，与“互补”更对应，排除B","no":69},{"id":"1718789646182","type":"single","material":"","stem":"在某种程度上，各地博物馆收藏化石，是对我国化石资源最大程度的保护。但（）的是，这种方式的收藏也不能被（），因为这就像吃鱼翅的人越多，遭到杀戮的鲨鱼就越多一样。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"遗憾;复制"},{"label":"B","content":"矛盾;鼓励"},{"label":"C","content":"不幸;推广"},{"label":"D","content":"尴尬;宣传"}],"answer":"B","explanation":"第一空，“但”之前说的是博物馆收藏化石对化石资源的保护作用，之后说的是这种收藏多了会造成化石资源的破坏，前后语意相悖，填入“矛盾”最恰当。“不幸”语义过重，排除C;“遗憾”“尴尬”均不能与前文构成相对之意，排除A、D代入B项验证第二空，因为这种方式的收藏会造成化石资源的破坏，所以不能被“鼓励”。","no":70},{"id":"1718789646183","type":"single","material":"","stem":"“质疑”其实是最基本的科学精神，也就是对于以前的结果、结论，甚至广泛得到证实和接受的理论体系都需要以怀疑的眼光进行（）。但是“质疑”并不完全等同于“怀疑”，更不是全面否定。“质疑”实际上是批评地学习和接受，其目的是（）以前工作的漏洞、缺陷、不完善的地方。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"审察;发掘"},{"label":"B","content":"检视;洞悉"},{"label":"C","content":"审视;发现"},{"label":"D","content":"核查;揭露"}],"answer":"C","explanation":"第一空，四个词语都含有仔细检查、观察的意思，不易辨析，可先从第二空入手。<br>第二空，“发掘”指挖掘埋藏在底下的东西，常与“宝藏”“潜力”“人才”等搭配使用；“揭露”指使隐蔽的事物显露，常与“矛盾”“本质”“阴谋”等搭配使用。二者与“漏洞、缺陷”搭配均不恰当，排除A、D<br>再看第一空，“检视”指检验查看，对象多为“现场”“物品”等；“审视”指仔细看。此处强调的是对广泛得到证实和接受的理论体系也不能放松警惕，要时刻保持怀疑精神，“审视”体现的审慎态度更契合句意，排除B","no":71},{"id":"1718789646184","type":"single","material":"","stem":"目前，社会上对种种迷信现象，笃信、盲从者不在少数，根源就在于思辨和理性的（）。在社会的进步和发展中，科学精神是消除各种（）、破除种种迷信的利器。科学精神的核心，就是不盲从、不迷信。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"失效;误解"},{"label":"B","content":"匮乏;罪恶"},{"label":"C","content":"缺失;愚昧"},{"label":"D","content":"苍白;无知"}],"answer":"C","explanation":"第一空，分析可知，社会上的种种迷信现象的根源在于缺乏思辨和理性，A项“失效”、D项“苍白”不合句意，排除。<br>第二空，从常识来看，科学精神并不能消除“罪恶”,且“科学”与“愚昧”常作为一对反义词同时出现，排除B","no":72},{"id":"1718789646185","type":"single","material":"","stem":"在奥斯维辛解放60周年纪念活动的电视实况转播里，看到奥斯维辛正飘飞着鹅毛大雪。远处苍茫的背景下，奥斯维辛集中营那些处在低洼之地的木制和砖砌的营房和毒气室，在洁白飞舞的雪花中，静静地（）着，无言地出示着历史的一份（）着血泪的证言。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"伫立;浸透"},{"label":"B","content":"肃立;书写"},{"label":"C","content":"站立;浸染"},{"label":"D","content":"树立;饱含"}],"answer":"A","explanation":"第一空，“树立”指建立(多用于抽象的好的事情),如树立榜样，与“营房和毒气室”不能搭配，排除D与“60周年纪念活动”“在洁白飞舞的雪花中”对应，“伫立”“肃立”所含有的庄重的意思更符合语境，排除C项的“站立”。第二空，由“集中营”“毒气室”可知，这份血泪证言见证了一段惨痛的战争历史，“浸透”语义程度更重，且与“血泪”搭配更恰当。","no":73},{"id":"1718789646186","type":"single","material":"","stem":"治理环境确为政府职责，环境出现问题，其监管（）、执法不严难逃其责。但是，当大家不断（）政府不作为时，是不是也应该（）一下自己：我们有没有污染环境？<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"不当;谴责;检察"},{"label":"B","content":"不周;斥责;检查"},{"label":"C","content":"不善;苛责;检点"},{"label":"D","content":"不力;指责;检讨"}],"answer":"D","explanation":"本题可从习惯搭配角度入手，迅速得出答案。“监管不力”“检讨自己”为常见搭配，且第二空填入“指责”也符合句意。","no":74},{"id":"1718789646187","type":"single","material":"","stem":"“一带一路”更是（）“达则兼济天下”和“一花独放不是春，百花齐放春满园”的理念，准确（）沿线国家发展，（）沿线国家人民的现实诉求。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"秉承;助力;响应"},{"label":"B","content":"坚持;助力;回应"},{"label":"C","content":"秉承;对接;回应"},{"label":"D","content":"坚持;对接;响应"}],"answer":"C","explanation":"第一空，“坚持”一般用来形容意志，不能形容“理念”,且“秉承理念”为常见搭配，排除B、D<br>第二空，“助力”侧重外力推动，“对接”侧重直接联系。“一带一路”是国家间直接合作，用“对接”恰当，排除A<br>验证第三空，“回应诉求”为习惯搭配。","no":75},{"id":"1718789646188","type":"single","material":"","stem":"多名全国人大代表提出议案，建议修订我国土地管理法，兼顾土地的资源与资产双重（），坚持物权平等保护（），提高（）补偿标准。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"特征;规定;征用"},{"label":"B","content":"要素;法案;征调"},{"label":"C","content":"标准;措施;征集"},{"label":"D","content":"属性;原则;征收"}],"answer":"D","explanation":"第三空，“征调”的对象多为人员、物资，“征集”的对象多为建议、作品，此处与“土地”搭配，“征用”“征收”恰当，排除B、C<br>第二空，“物权平等保护”是物权法的基本原则，且“坚持原则”为常用搭配，排除A第一空，“资源”和“资产”是土地具有的双重性质，用“属性”描述也恰当。","no":76},{"id":"1718789646189","type":"single","material":"","stem":"魔术是一门（）的艺术，要想产生惊奇的效果，就要制造假象，将物体真实的状态（）起来。一般，魔术师们总是会将各种物体藏起来，让人们对物体的状态产生错误的想象，而事实上，魔术表演还能制造出更加有趣的（），比如：在观众的脑子里创造出一件并不存在的魔术道具。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"真实;展现;幻觉"},{"label":"B","content":"误导;隐藏;错觉"},{"label":"C","content":"错误;掩盖;想象"},{"label":"D","content":"欺骗;珍藏;画面"}],"answer":"B","explanation":"第一空，由“制造假象”可知，魔术具有误导性和欺骗性，排除A、C第二空，“珍藏”指认为有价值而妥善地收藏，此处表达的是魔术对物体真实状态的隐藏，不让人发现，排除D将B项代入验证第三空，“错觉”指由于某种原因引起的对客观事物的不正确的感觉，与前面提到的错误想象及冒号后的句子相照应，符合题意。","no":77},{"id":"1718789646190","type":"single","material":"","stem":"三千多年来浩若烟海的歌谣诗词经史曲赋铭文典籍，（）了中华民族博大精深的思想智慧，（）了中华文化不尽不竭的精神源泉。中国的语言文字在抑扬顿挫平仄韵律之中，在点横撇捺篆隶楷行之间，构建了中华民族（）的文化图谱。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"保护;蕴含;华丽"},{"label":"B","content":"保存;滋养;亮丽"},{"label":"C","content":"保全;蕴含;绚烂"},{"label":"D","content":"保有;涵养;绚丽"}],"answer":"D","explanation":"先看第三空，A项“华丽”一般形容服饰、建筑等，不能用来形容“文<br>化图谱”,排除。B项“亮丽”指明亮美丽，侧重“亮”,“文化图谱”不能用“亮”来形容，排除。<br>第二空，C项“蕴含”指包含在内；D项“涵养”指滋润养育，培养。形容“精神源泉”,“涵养”更合适。","no":78},{"id":"1718789646191","type":"single","material":"","stem":"很多时候，我们的问题在于不能正确地（）个人和社会的界限。事实上，如果（）了个人，就不可能加强集体；如果（）了个人，集体也不可能获得自由。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"区别;削减;约束"},{"label":"B","content":"分清;减弱;限制"},{"label":"C","content":"划清;削弱;束缚"},{"label":"D","content":"区分;降低;压制"}],"answer":"C","explanation":"第一空，句意为要清楚个人和社会的界限。“区别”指把两个以上的对象加以比较，认识它们不同的地方；“区分”指区别。两者均侧重区别两个事物的不同之处，与句意不符，排除A、D“分清”指分辨清楚，常见搭配为“分清是非”,排除B“划清”指区分清楚，符合句意，且“划清界限”为常见搭配。<br>将C项代入第二空验证，“削弱”指(力量、势力)变弱，与后句的“加强”构成反义对应，符合句意。<br>将C项代入第三空验证，“束缚”指使受到约束限制，填入符合句意。","no":79},{"id":"1718789646192","type":"single","material":"","stem":"生命只有一次，而人生也不过是时间的（）。若让今天的时光白白（），就等于毁掉人生最后一页。珍惜今天的一分一秒，因为它们将一去不复返。人无法把今天存入银行，明天再来取用。时间像风一样不可（）。每一分一秒，要用双手捧住，用爱心抚摸，因为它们如此宝贵。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"累积;流失;捕捉"},{"label":"B","content":"累计;流走;捕捉"},{"label":"C","content":"累计;流失;捕获"},{"label":"D","content":"累积;流走;捕获"}],"answer":"A","explanation":"第一空，“累积”指层层增加，聚积；“累计”指加起来计算，总计。此处是说人生是时间的聚积，选“累积”更恰当，排除B、C<br>第二空，“流失”泛指有用的东西流散失去。“流走”指流亡，流浪；到处走动。此处用来形容时光，用“流失”更准确，排除D<br>第三空，填入“捕捉”形容“时间像风一样”亦恰当。","no":80},{"id":"1718789646193","type":"single","material":"","stem":"①我在听先生这篇讲演后二十余年，（）获得机缘在茅津渡候船渡河。<br>②市长在两会特别节目《又是一年春来到》上，谈到（）他乡的农民工也可成为这座城市的主人。<br>③今天要（）的新机器非常先进，因为它们采用了很多先进技术。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"偶尔;做客;试验"},{"label":"B","content":"偶然;作客;试验"},{"label":"C","content":"偶然;做客;实验"},{"label":"D","content":"偶尔;作客;实验"}],"answer":"B","explanation":"①句，“偶尔”与“经常”相对，侧重有时候；“偶然”与“必然”相对，侧重超出一般规律的。此处表示机缘突然出现，“偶然”填入恰当，排除A、D<br>②句，“做客”指访问别人，自己当客人；“作客”指寄居在别处。由“他乡”可知，此处应选“作客”,排除C<br>③句，“试验”指为了察看某事的结果或某物的性能而从事某种活动；“实验”指为了检验某种科学理论或假设而进行某种操作或从事某种活动。此处是为了查看新机器的<br>性能，应选“试验”。","no":81},{"id":"1718789646194","type":"single","material":"","stem":"黄帝是中华文明的开拓者和奠基者，黄帝陵是中华民族记忆最（）的教科书，是凝聚全体炎黄子孙的鲜艳（），是我们文化自信的重要（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"生动;旗帜;源泉"},{"label":"B","content":"深刻;标识;根源"},{"label":"C","content":"有趣;标志;来源"},{"label":"D","content":"丰富;图腾;渊源"}],"answer":"A","explanation":"第一空，“有趣”不符合黄帝对中华文化的影响，排除C<br>第二空，“标识”指表明特征的记号，形容黄帝陵对炎黄子孙的意义也不恰当，排除B<br>第三空，“源泉”侧重指来源，“渊源”侧重探究事物本质根源。“文化自信”来源于黄帝文化影响力，用“源泉”更恰当。","no":82},{"id":"1718789646195","type":"single","material":"","stem":"近年来，国家有关部门加大了对非法盗版活动的打击力度，通过建立群众举报、定期检查等制度，有效（）了非法盗版活动的势头。随着市场法律环境的日趋（），这种广大人民群众深恶痛绝的社会丑恶现象，终究会被根除。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"制止;完美"},{"label":"B","content":"遏止;完备"},{"label":"C","content":"扼制;完整"},{"label":"D","content":"遏制;完善"}],"answer":"D","explanation":"第一空，“制止”多与行为搭配，与“势头”搭配不当，排除A“遏止”指阻止，“扼制”重在把守，“遏制”表示控制。文段中“势头”应是得到了有效的控制，故应选“遏制”。<br>第二空，“完善”与“环境”也搭配恰当。","no":83},{"id":"1718789646196","type":"single","material":"","stem":"<p>办公人员的座椅高度是非常有讲究的。专家（ &nbsp;），许多人办公座椅的高度都存在一定问题，久坐就会（ &nbsp;）疲劳感，并出现腰酸背痛的毛病。正确的做法是，首先根据工作性质把办公桌调整到一个（ &nbsp;）的高度，然后再依据自身情况来调整座椅的高度。</p><p>填入括号部分最恰当的一项是：</p>","options":[{"label":"A","content":"提示;产生;适合"},{"label":"B","content":"提示;引发;合适"},{"label":"C","content":"提醒;产生;合适"},{"label":"D","content":"提醒;引发;适合"}],"answer":"C","explanation":"第一空，“提示”侧重于启示；提起注意。“提醒”侧重于引起注意。文段指出久坐之后的后果，用“提醒”更符合题意，排除A、B。第三空，所填词语应选形容词，应为“合适”，排除D。","no":84},{"id":"1718789646197","type":"single","material":"","stem":"中国文化的跨语境交流与传播有广阔的发展空间，我们要（）自身文化传播的局限性，拓宽文化传播的视野，推行和而不同的对外传播（），加大文化在他者语境下的传播（），提升中国文化以及其核心价值在世界文化中的影响力。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"打破;需求;速度"},{"label":"B","content":"突破;诉求;力度"},{"label":"C","content":"超出;要求;广度"},{"label":"D","content":"超越;吁求;幅度"}],"answer":"B","explanation":"第一空，与横线后的“局限性”搭配，“超出”“超越”明显不恰当，排除C、D<br>第二空，“需求”和“诉求”意思相近，不易辨析，可从第三空入手。<br>第三空，“速度”常与“加快”搭配，与“加大”搭配不当，排除A","no":85},{"id":"1718789646198","type":"single","material":"","stem":"物品的预设用途为用户提供了该如何操作的线索，比如平板是用来推的，旋钮是用来转的。如果物品的预设用途在设计中得到（）体现，用户一看便知如何操作，无须借助任何的图解、标志和说明。如果简单物品也需要用图解、标志和说明书来（）操作方法，这个设计就是（）的。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"全面;呈现;粗糙"},{"label":"B","content":"有效;指导;落伍"},{"label":"C","content":"充分;解释;失败"},{"label":"D","content":"合理;演示;笨拙"}],"answer":"C","explanation":"第一空，由“一看便知”“无须借助任何的图解、标志和说明”可知，填入词语应表体现得很彻底之意。“合理”指合乎道理或事理，与句意无关，排除D“有效”指能实现预期的目的，有效果；“全面”指完整周密，兼顾各方面的；“充分”指足够。A、B、C三项填入均可。<br>第二空，“指导”可与“操作”搭配，与“操作方法”搭配不当，排除B<br>第三空，“粗糙”侧重于不精致。对于简单物品也需要有解释操作方法的设计，用“粗糙”描述程度过轻，“失败”更能表达其根本缺陷，排除A","no":86},{"id":"1718789646199","type":"single","material":"","stem":"保护好历史建筑，实质就是留住城市发展的（），让人真切（）到城市的“昨天”“今天”与“明天”。我们并不（）有历史的城市，但很多城市确实缺少“历史感”与“厚重感”。就此看，“不拆真遗存，不建假古董”，其实不是针对具体历史建筑的保护，而是强调对历史的敬畏，对人文本位的回归。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"痕迹;感受;存在"},{"label":"B","content":"文脉;体认;缺乏"},{"label":"C","content":"线索;了解;获得"},{"label":"D","content":"遗迹;领悟;缺少"}],"answer":"B","explanation":"第一空，由“实质”可知，此处是在论述保护历史建筑的深层意义，“遗迹”是具体的遗留物，未体现出“实质”所在，排除D第三空，由后文的“很多城市”<br>可知，“有历史的城市”不少，故第三空处所填词语应与前面的“不”字共同表达“数量多”之义，排除A、C","no":87},{"id":"1718789646200","type":"single","material":"","stem":"哥白尼所发动的这场天文学革命，（）了中世纪以来的神学权威，（）起科学的理性精神，（）了一整套观察、实验与思考的方法，由此为西方近代科学的产生奠定了基础。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"质疑;成立;发现"},{"label":"B","content":"铲除;确立;建成"},{"label":"C","content":"挑战;树立;形成"},{"label":"D","content":"打破;建立;发展"}],"answer":"C","explanation":"第一空，“铲除”多与“余孽”“土壤”等搭配，与“权威”搭配不当，排除B<br>第二空，“成立”多与“组织”“机构”等搭配，与“理性精神”搭配不当，排除A<br>第三空，“发展”与“一整套方法”搭配不当，排除D","no":88},{"id":"1718789646201","type":"single","material":"","stem":"中国共产党第十九次全国代表大会，是在全面（）小康社会（）阶段、中国特色社会主义进入新时代的关键（）召开的一次十分重要的大会。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"建设;决胜;时期"},{"label":"B","content":"建设;决战;时刻"},{"label":"C","content":"建成;决胜;时期"},{"label":"D","content":"建成;决战;时刻"}],"answer":"C","explanation":"第一空，“全面建设小康社会”是党的十六大提出的奋斗目标，党的十八大顺应国内外形势的新变化，提出了“全面建成小康社会”的目标。“建设”与“建成”一字之差，但意义深远。“建设”侧重过程，强调任重道远；“建成”侧重结果，强调小康社会即将实现。对应“中国共产党第十九次全国代表大会”的背景，此处应选“建成”,排除A、B<br>第二空，“决战”指敌对双方使用主力进行决定胜负的战役或战斗；“决胜”指决定最后的胜负。此处表达的是目前正处于全面建成小康社会的关键阶段，“决胜阶段”为习惯搭配，排除D<br>第三空，“时期”指事物发展过程中的一段具有一定特征的、较长的时间，“时刻”指特定的时间。与前文的“阶段”对应，此处填入表示较长时间的“时期”更恰当。","no":89},{"id":"1718789646202","type":"single","material":"","stem":"游览花山岩画，船行江流之上，两岸风光旖旎，茂林修竹，清秀（）。不远处的江岸边是一排拔地而起的断岩山，山势陡峭，但郁郁葱葱。临江一面有国画般（）留白的石壁，被苍翠的山脊（）着，格外显眼。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"俊逸;浸染;环绕"},{"label":"B","content":"隐约;渲染;嵌入"},{"label":"C","content":"隐逸;点染;镶嵌"},{"label":"D","content":"飘逸;点缀;装饰"}],"answer":"C","explanation":"第一空，根据文意，横线处所填词语应与“清秀”并列，描述两岸美景。A项“俊逸”、C项“隐逸”、D项“飘逸”均可与“清秀”搭配用来描述景色。B项“隐约”指看起来或听起来不很清楚，不能与“清秀”并列，排除。<br>第二空，A项“浸染”指逐渐沾染或感染，也指液体渗入而使染上颜色或被污染；C项“点染”指绘画时点缀景物和着色，也比喻修饰文字；D项“点缀”指加以衬托或装饰，使原有事物更加美好。与“国画般”相对应，C项的国画术语“点染”填入最恰当。<br>验证C项第三空，“镶嵌”指将一个物体嵌入另一个物体中，使二者固定，填入句中能够形象地体现石壁被山脊凸显的样子，与后句的“格外显眼”构成呼应。","no":90},{"id":"1718789646203","type":"single","material":"","stem":"无论是现代游戏，还是传统游戏，都（）出了一定的知识、社会和时代特征，同时也（）了团结、多样性和包容的价值。但随着社会变迁和时代发展，很多有价值的传统游戏正在一代又一代的（）中逐渐消逝。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"反射;传播;更新"},{"label":"B","content":"折射;传递;更迭"},{"label":"C","content":"影射;传承;更替"},{"label":"D","content":"投射;传达;更动"}],"answer":"B","explanation":"第一空，“反射”指自然现象中受刺激物对刺激物的逆反应，也指物理光学中的光传播现象。其用在此处不恰当，排除A“影射”指借甲指乙；暗指(某人某事)。此处没有“暗指”之意，排除C<br>第二空，“传达”多与“精神”“消息”等搭配使用，与“价值”搭配不当，排除D<br>第三空填入“更迭”,符合句意。","no":91},{"id":"1718789646204","type":"single","material":"","stem":"油菜花遍地的金黄色，虽然没有红色的浓艳，没有绿色的（），但却开出了一种（）的风格，花香之中让我嗅出了亲切的乡土气息，倍加增添了一种（）的思念之情。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"隆重;朴素;强烈"},{"label":"B","content":"庄重;淳朴;热烈"},{"label":"C","content":"沉重;娇艳;深沉"},{"label":"D","content":"厚重;朴实;浓郁"}],"answer":"D","explanation":"本题可由第一空入手破题。“隆重”“庄重”多用于形容场面的庄严，不能用于形容颜色的性状，排除A、B文段基调朴实平和，“沉重”与文段基调不符，排除C<br>验证其他两空，第二空，“朴实的风格”符合文段对油菜花的定位；第三空，“浓郁的思念之情”搭配也恰当。","no":92},{"id":"1718789646205","type":"single","material":"","stem":"总的来讲，“社会”在处理与国家的关系过程中强调其自主性的成长与释放，并（）了各种形式的自我保护运动。而且，“社会”也在改变其生存与发展策略，它不仅仅满足在国家为其（）的范围内行动，而且还通过与国家的主动接触与互动，（）与政府的相关性，并以协作或合作的方式参与社会问题的解决。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"展开;规定;保持"},{"label":"B","content":"拓展;制定;保护"},{"label":"C","content":"开展;划定;维持"},{"label":"D","content":"发展;制订;保障"}],"answer":"A","explanation":"阅读文段和选项，第一空不好入手，暂不做选择。<br>第二空，“制定”指定出(法律、规章、政策等),“制订”指创制拟定。二者均不能与“范围”搭配，排除B、D<br>第三空，“保持”指维持(原状),使不消失或减弱；“维持”指使继续存在下去，保持。二者都有继续维持现状之意，但在感情色彩上，“维持”偏消极，暗含使事物处于较为狭隘或不容乐观的境地之意。再结合题干语境，“维持”不适合修饰“社会”与政府的关系，排除C<br>第一空，“展开”填入句中，语意通顺。","no":93},{"id":"1718789646206","type":"single","material":"","stem":"小城镇具有低成本吸纳农村人口的先天性优势，是连接城市与乡村的重要（）。小城镇在促进农村人口转移、（）城乡发展、扩大消费需求及投资需求等方面具有重要作用，尤其是那些位于城市群区域内的小城镇，可以在接受来自大城市（）的同时加大对“三农”领域的服务。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"桥梁;谋划;影响"},{"label":"B","content":"节点;统筹;辐射"},{"label":"C","content":"载体;规划;优势"},{"label":"D","content":"通道;筹划;馈赠"}],"answer":"B","explanation":"第一空，四个词语填入均符合句意，较难排除，选择从第二空入手。<br>第二空，“统筹城乡发展”是科学发展观的重要概念，由此排除A、C、D<br>验证其他两空：第一空，“节点”指整体事物中的某个关键点，用于描述小城镇连接城市和乡村的位置和作用恰当；“辐射”填入第三空也符合大城市影响周边小城镇的语境。","no":94},{"id":"1718789646207","type":"single","material":"","stem":"这部著作把对历史文化追索的触角更深入地探触到历史时空的幽微之处，更敏锐地（）虽然缥缈却血脉相连的文化传承，让远逝的鸿影显现出朦胧的真相，使冰冷荒漠的历史有了人性的（）。他将华夏祖先的图腾放置在人类文明进步的历史大背景中予以（），在历史与现实之间辗转反侧、抒发见解，带给我们新的思考。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"感知;温度;观照"},{"label":"B","content":"揭示;弱点;洞察"},{"label":"C","content":"探究;纠葛;揣度"},{"label":"D","content":"体悟;温暖;臆想"}],"answer":"A","explanation":"第一空，阅读文段，四个词语填入似乎都较合理，可先从第二空入手。<br>第二空，与横线前的“冰冷”相对应，此处填“温度”“温暖”较恰当，排除B、C<br>再看第三空，由“将华夏祖先的图腾放置在……历史大背景中”可知，“他”是结合历史进行了审视、思考的，而非完全主观的“臆想”,排除D“观照”指仔细观察，审视，常与“传统文化”“现实”等搭配，填入句中与语境相符。<br>验证第一空，“感知”填入也恰当。","no":95},{"id":"1718789646208","type":"single","material":"","stem":"加入世界贸易组织以来，中国深度（）全球经济，发生了不曾（）的巨大变化。我们积极抓住战略机遇，主动（），拓展全方位的开放格局，积极参与到全球经济治理浪潮中。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"进入;预想;调节"},{"label":"B","content":"切入;预料;调整"},{"label":"C","content":"融入;预见;调适"},{"label":"D","content":"切入;预见;调节"}],"answer":"C","explanation":"第一空，“进入”指进到某个范围或某个时期里，或者进到某一种状态，例如“进入一个新纪元”;“切入”指(从某个地方)深入进去，可形容文章点明主题；“融入”泛指物质间的彼此接纳，或个人或群组从思想上和形式上融入了另一个群组，成为一个更大的群组。与“全球经济”搭配，“融入”更恰当，且更能突出加入世贸组织后中国与世界经济的紧密联系，排除A、B、D<br>验证后两空，“预见”“调适”填入均符合句意。","no":96},{"id":"1718789646209","type":"single","material":"","stem":"当企业的业务都实现计算机化后，那些从事计算机业务的企业却遭遇了（）。如果需要计算机化的业务流程没有增加，顾客对性能没有特别需求，他们就无法继续（）自己的产品。所以，所有与计算机相关的企业，都必须为已经得到满足的顾客们，提供一个购买他们更新技术的（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"瓶颈;销售;理由"},{"label":"B","content":"阻碍;生产;方法"},{"label":"C","content":"困境;改进;渠道"},{"label":"D","content":"障碍;推广;优惠"}],"answer":"A","explanation":"第二空，由后文的“购买”可知，这些企业的目的是“销售”或者“推广”自己的产品，“生产”“改进”只是达到这一目的的手段，排除B、C<br>第三空，要让需求已经得到满足的顾客们购买自己的新产品，必须提供一个能说服他们的“理由”,而非在“方法”“渠道”“优惠”方面做文章，排除D<br>第一空，“遭遇瓶颈”为习惯搭配。","no":97},{"id":"1718789646210","type":"single","material":"","stem":"在国际国内多个场合，习近平总书记的精彩阐述，让“一带一路”的（）（）（）理念传遍世界，深入人心。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"共建;共商;共享"},{"label":"B","content":"共建;共享;共商"},{"label":"C","content":"共商;共享;共建"},{"label":"D","content":"共商;共建;共享"}],"answer":"D","explanation":"本题考查顺承逻辑关系。“共商”强调的是“一带一路”建设之前的思想统一过程；“共建”强调的是“一带一路”建设的实施过程；“共享”强调的是“一带一路”建成之后分享利好的过程。与此顺序相符的为D","no":98},{"id":"1718789646211","type":"single","material":"","stem":"直觉是人类思维的一种特殊存在形态。它（）在人类意识深层，超越人类普遍的理性思维和价值判断，在人类自觉的意志和意识控制之外。受到某种特殊的心理诱因或视听感觉（）、诱发，它会突然出现在意识层，（）人类思维，直接对事物、环境状况做出判断。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"沉积;推动;引导"},{"label":"B","content":"潜藏;激活;掌控"},{"label":"C","content":"蛰伏;刺激;掌管"},{"label":"D","content":"潜伏;触动;主导"}],"answer":"D","explanation":"第一空，“沉积”可指沉淀，积聚，例如“文化沉积”“历史沉积”,用在此处形容直觉隐藏在人类意识深层不恰当，排除A<br>第二空，“激活”指刺激机体内某种物质，使其活跃地发挥作用。此处用来形容“心理诱因或视听感觉”对直觉的影响不恰当，排除B<br>第三空，“掌管”指负责管理，主持，常与“事务”“财政”等搭配，此处与“人类思维”搭配不恰当，且语义程度较重，排除C","no":99},{"id":"1718789646212","type":"single","material":"","stem":"研究表明，大脑具有自我修复的潜能，继续（）这方面的研究，有望最终确认哪些信号可用来促进神经源性反应的（），而以（）神经发生（即神经元的生成和更新）现象为目标，或可成为一种促进神经元再生的有效治疗方法。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"增强;强化;加强"},{"label":"B","content":"强化;加强;增强"},{"label":"C","content":"加强;增强;强化"},{"label":"D","content":"增强;加强;强化"}],"answer":"C","explanation":"第一空，“增强”与“研究”搭配不当，排除A、D第三空，与“现象”搭配，“强化”更恰当，排除B<br>第二空，“增强”与“反应”搭配恰当。","no":100},{"id":"1718789646213","type":"single","material":"","stem":"在充满变量的世界，我们是眼花缭乱的观望者，也是置身其间的推动者。曾经走街串巷的叫卖声不见了，只需手指轻轻一点即可享受送货上门的电商火了起来；全家人乃至几家人守着一台电视机等待每天一集电视剧的场景不见了，取而代之的是乱花渐欲迷人眼的多屏时代；人们获取信息的渠道不仅早已多样化，而且信息芜杂难辨。“（）”，是我们生活中的常态，容不得视而不见，也容不得退避。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"难"},{"label":"B","content":"变"},{"label":"C","content":"乱"},{"label":"D","content":"散"}],"answer":"B","explanation":"由“在充满变量的世界”“……不见了，……火了起来”“……不见了……取而代之的是……”可知，文段强调的是当下世界变化很快，“变”是生活的主题词。A、C、D三项均含贬义，而电商的火爆、多屏时代均代表的是时代的进步，填入不合语境。","no":101},{"id":"1718789646214","type":"single","material":"","stem":"如果把各项改革任务比作一个个盘子，那么领导干部就要学会“转盘子”，实现任务之间的（）协调，才能同时转动多个盘子，下好改革一盘棋。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"沟通"},{"label":"B","content":"统一"},{"label":"C","content":"整合"},{"label":"D","content":"耦合"}],"answer":"D","explanation":"由“同时转动多个盘子，下好改革一盘棋”可知，此处强调的是任务之间应相互配合，达到一种平衡的状态。“沟通”指使双方能通连，通常用于人、群体、组织之间，不能用于“任务”之间，排除A“统一”指部分联成整体，分歧归于一致；“整合”指通过整顿、协调重新组合。二者均侧重强调整体性，不满足句意，排除B、C“耦合”指两个或两个以上的体系或两种运动形式通过相互作用而彼此影响以至联合起来的现象。其用来描述任务之间相互作用的关系恰当。","no":102},{"id":"1718789646215","type":"single","material":"","stem":"近年来，随着飞秒脉冲激光技术的发展，飞秒时间（）光谱技术在化学（）动力学、光合作用等超快过程研究领域得到了广泛应用。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"分辩;反映"},{"label":"B","content":"分辨;反应"},{"label":"C","content":"分辩;反应"},{"label":"D","content":"分辨;反映"}],"answer":"B","explanation":"第一空，“分辩”指辩白；“分辨”指辨别。此处讲的是一种辨别技术，应选“分辨”,排除A、C第二空，“化学反应”是专用术语，指的是物质发生化学变化而产生性质、成分、结构与原来不同的新物质的过程。","no":103},{"id":"1718789646216","type":"single","material":"","stem":"慎众，慎的是（）。群体心理学认为，个体的行为容易受群体的意识、情绪和选择影响。正如《乌合之众》一书所说，“群体中的个人，不过是众多沙粒中的一颗，可以被风吹到无论什么地方”。所以，当身处群体中时，要格外注意自己的言行，不为“生态”所染、不为“氛围”所乱、不为“情绪”所惑。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"“出众”"},{"label":"B","content":"“众怒”"},{"label":"C","content":"“从众”"},{"label":"D","content":"“众说”"}],"answer":"C","explanation":"由后文的“个体的行为容易受群体的意识、情绪和选择影响”“要格外注意自己的言行，不为‘生态’所染、不为‘氛围’所乱、不为‘情绪’所惑”可知，文段强调的是个人要谨慎行事使自己的言行不受群体的干扰和影响。<br>A项“出众”指超出众人，一般用来形容“成绩”“才华”“模样”“能力”等。填入文段中与句意无关，排除。<br>B项“众怒”指众人的愤怒。填入文段亦与句意无关，排除。<br>C项“从众”指按多数人的意见或流行的做法(行事),填入最符合句意。<br>D项“众说”指各种学说或议论，与文段强调的“个人不受群体干扰和影响”的句意无关，排除。","no":104},{"id":"1718789646217","type":"single","material":"","stem":"从碎片化、孤立化应用为主的起步阶段，迈入跨界融合、集成创新的新阶段，物联网大规模爆发式增长的序幕已经开启。智能硬件、可穿戴设备、联网车辆发展迅猛，正是物与物、物与人加速连接的（）。物联网将信息化与传统领域深度融合，也在重塑生产组织方式，（）产业形态。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"诱因;调整"},{"label":"B","content":"条件;创新"},{"label":"C","content":"结果;构建"},{"label":"D","content":"印证;变革"}],"answer":"D","explanation":"第一空前后描述的是产业链之间的关系，专业性较强，难以入手破题，可从第二空入手。<br>第二空，分析可知所填词语应与前面的“重塑”构成并列关系，两个词语意思相近。<br>“重塑”有重新塑造之意。“调整”指重新调配或安排，语义程度过轻，排除A“创新”指创造新事物；“构建”指建立，强调从无到有。二者均不符合“重塑”的含义，排除B、C<br>验证第一空，由“物联网大规模爆发式增长的序幕已经开启……发展迅猛，正是·……\"”可知，“智能硬件、可穿戴设备、联网车辆发展迅猛”体现的正是“物与物、物与人加速连接”的发展现状。“印证”所体现的证明与事实相符合之意，符合句意。","no":105},{"id":"1718789646218","type":"single","material":"","stem":"树立法律权威，就要使法治原则（）到国家与社会每一层次、每一角落，让全体公民信仰法治，对法律存有敬畏之心。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"深入"},{"label":"B","content":"融入"},{"label":"C","content":"渗透"},{"label":"D","content":"扩大"}],"answer":"C","explanation":"由“每一层次、每一角落”可知，句意为让法治原则贯彻到国家和社会的各个层次、各个方面，即贯彻法治原则不仅强调广度，也强调深度。“深入”仅强调深度，对应“层次”;“扩大”仅强调广度，对应“角落”,均不全面，排除A、D“融入”侧重物质间的彼此融合；“渗透”比喻一种事物或势力逐渐进入其他方面(多用于抽象事物)。此处描述抽象的法治原则的影响，选“渗透”更恰当。","no":106},{"id":"1718789646219","type":"single","material":"","stem":"在水中自由地（），闲暇的时候挣脱一切（），到岸上享受晨风拂面，然后，一个华丽的俯冲，重新潜入关系之水，去做一条在波涛下微笑的鱼。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"翱翔;束缚"},{"label":"B","content":"遨游;羁绊"},{"label":"C","content":"游弋;牢笼"},{"label":"D","content":"徜徉;烦恼"}],"answer":"B","explanation":"第一空，文段的语境是“在水中”。A项“翱翔”一般指在空中回旋地飞，排除。D项“徜徉”指闲游或安闲自在地步行，排除。“遨游”“游弋”均符合语境，B、C两项备选。<br>第二空，与“挣脱”搭配，“羁绊”与“牢笼”均可，但“牢笼”程度过重，“挣脱羁绊”搭配恰当。","no":107},{"id":"1718789646220","type":"single","material":"","stem":"生活中细小的变化都可能让我们的感觉大不相同，我们要学会欣赏和赞扬，随时（）身边美好的事物，因为关注美好事物有助于规避不良情绪，同时切记多与乐观豁达、愉快向上的人相处。此外，（）一下日常生活节奏，也会让你的生活更有活力。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"留意;改善"},{"label":"B","content":"发现;改变"},{"label":"C","content":"寻找;调整"},{"label":"D","content":"发掘;调节"}],"answer":"B","explanation":"第一空，由“生活中细小的变化都可能让我们的感觉大不相同，我们要学会欣赏和赞扬”可知，身边美好的事物一直都存在，不需要人们去“寻找”和“发掘”,排除C、D<br>第二空，“改善”多与“环境”“关系”等搭配，与“节奏”搭配不当，排除A","no":108},{"id":"1718789646221","type":"single","material":"","stem":"①上帝此刻或许（）了这个小生命，在马志恭被丢弃在乱石岗的第二天，一位老农意外发现了他。<br>②20世纪90年代，随着电视的普及，农村电影市场日渐（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"垂青;萎靡"},{"label":"B","content":"青睐;萎缩"},{"label":"C","content":"垂青;萎缩"},{"label":"D","content":"青睐;萎靡"}],"answer":"C","explanation":"①句，“垂青”表示重视，为敬辞，多用于长辈或上级；“青睐”意为喜爱或重视。此处对象为“上帝”,选“垂青”更恰当，且受到命运、上帝的垂青为习惯表述，排除B、D<br>②句，“萎靡”常用来形容精神不振，此处形容市场的减小，应用“萎缩”。","no":109},{"id":"1718789646222","type":"single","material":"","stem":"近年来，“图说我们的价值观”公益广告以开阔的视野、（）人心的作品和（）人心的力量，传播社会正能量，引起了社会各界的高度关注和观众的热烈反响。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"鼓舞;激励"},{"label":"B","content":"深入;撼动"},{"label":"C","content":"温暖;感化"},{"label":"D","content":"凝聚;汇聚"}],"answer":"B","explanation":"由“开阔的视野、人心的作品和人心的力量”可知，三个短语分别从不同层面介绍“图说我们的价值观”公益广告的特点，因此空缺处两空词语意思也应不同。A项的“鼓舞”“激励”、C项的“温暖”“感化”、D项的“凝聚”“汇聚”意思接近，填入不合语境，排除。B项“深入”着眼于深度，“撼动”着眼于力度，意思不同，却都能突出公益广告的影响，填入并列恰当。","no":110},{"id":"1718789646223","type":"single","material":"","stem":"情绪并不是独立存在的，它常常伴随着信息而传播。作为一种态度，情绪不仅能够（）人们对所传播信息的认知，还会在一定程度上指导人们的行为。积极的情绪会促进人们积极地认识世界，消极的情绪则可能给他人甚至整个社会带来破坏性后果。人在情绪失控时，很容易不顾后果地做出（）的举动。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"影响;危险"},{"label":"B","content":"左右;出格"},{"label":"C","content":"干扰;反常"},{"label":"D","content":"支配;冲动"}],"answer":"B","explanation":"第一空，由“积极的情绪会促进人们积极地认识世界，消极的情绪则可能给他人甚至整个社会带来破坏性后果”可知，文段讲述的是情绪对人的影响，“影响”“左右”符合文意。“干扰”指扰乱、打搅，为贬义词。而由文段可知，情绪的影响并非都是负面的，“干扰”填入不当，排除C“支配”程度过重，排除D<br>第二空，人在情绪失控的情况下，很容易做出超出常规的举动，而这种举动不一定是“危险”的，因此，“出格”比“危险”更符合句意，排除A","no":111},{"id":"1718789646224","type":"single","material":"","stem":"远处云烟缭绕、植被茂密的青山，以及行走在街头身着民族服饰的不丹人，足以（）城市外观上的漏洞。廷布街头的不丹女人大多身穿宽袖窄身的“旗拉”，男人不少则穿着过膝长袍“帼”，服装的布料都是织造的，用的是自然布料，且以传统自然染料染成，即使远看也有一种（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"弥补;韵味"},{"label":"B","content":"补偿;风味"},{"label":"C","content":"抵偿;趣味"},{"label":"D","content":"填补;味道"}],"answer":"A","explanation":"第一空，“补偿”指弥补偿还，多用于“亏欠”的语境；“抵偿”指抵代偿还，一般后接“债务”等。此处与“漏洞”搭配，两词均不恰当，排除B、C“弥补”指把不够的部分填足；“填补”指补足空缺或欠缺。A、D两项均可与“漏洞”搭配，符合题意。<br>第二空，“味道”指物质所具有的能使舌头得到某种味觉的特性；“韵味”指情趣，趣味。“韵”含有风韵的意思。此处表达的是不丹人穿着民族服装体现出来的独特情调，用“韵味”更恰当，排除D","no":112},{"id":"1718789646225","type":"single","material":"","stem":"或许我们真的需要经典作品来（）我们偶尔困顿迷茫的精神，用大师的智慧烛照我们前行的步伐，他们的作品有着（）岁月阻隔的力度，唤起我们在这个浮躁时代里重新对人生的追索，从眼前困扰的现实中超脱出来。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"观照;消弭"},{"label":"B","content":"支撑;穿透"},{"label":"C","content":"唤醒;超越"},{"label":"D","content":"消除;跨越"}],"answer":"B","explanation":"第一空，“观照”“消除”都与空缺处后的“精神”搭配不当，排除A、D<br>第二空，“岁月阻隔”需要“穿透”而不是“超越”,且“穿透”与句中的“力度”也更搭配。","no":113},{"id":"1718789646226","type":"single","material":"","stem":"创新的目的不是发论文，培育新的经济增长点才能（）科技的真功夫。让创新更紧密地面向经济社会发展，把创新实实在在地（）为新产品、新项目、新产业，是创新的要义所在。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"发挥;转变"},{"label":"B","content":"凸显;催化"},{"label":"C","content":"反映;转换"},{"label":"D","content":"彰显;转化"}],"answer":"D","explanation":"第一空，此处意在强调培育新的经济增长点才能体现科技具有的真功夫。“发挥”指把内在的性质或能力表现出来，把意思或道理充分表达出来。其常见搭配为“发挥作用”“发挥技术水平”,与“真功夫”搭配不当，排除A“凸显”“反映”“彰显”均有体现之意，填入均符合题意。<br>第二空，句意为将创新转变为新产品、新项目、新产业。“催化”指促使化学反应的速率发生改变，强调速度的加快，与文意无关，排除B“转换”指改变，改换；从一种能量形式变成另一种能量形式，常用于同类事物间的改变。创新与“新产品、新项目、新产业”是不同的事物，排除C“转化”指转变，改变，用于不同类事物间的相互转变，且“科技转化为生产力”为习惯表述。","no":114},{"id":"1718789646227","type":"single","material":"","stem":"在户籍新政推出一年后，西安再出“狠招”：在校大学生仅凭学生证和身份证即可完成在线落户。在一系列新政的（）之下，年初以来新迁入人口已达21万人，直逼去年迁入人口总量。有媒体报道西安“抢人才”盛况时，配上唐太宗李世民曾在长安喜不自禁曰“天下英雄入吾彀中矣”的典故加以（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"催生;说明"},{"label":"B","content":"叠加;烘托"},{"label":"C","content":"护持;渲染"},{"label":"D","content":"效应;描述"}],"answer":"B","explanation":"第一空，由“再出‘狠招’”“一系列新政”可知，此处强调的是多重新政的累加效果。“叠加”指使一物与另一物占有相同位置并与之共存，与前面的“系列”对应恰当，且“政策叠加”为习惯表达。“催生”常用来比喻催促作品问世；“护持”指维护保持；“效应”泛指某个人物的言行或某种事物的发生、发展在社会上所引起的反应和效果。三者均无法与“系列新政”构成呼应，排除A、C、D<br>验证第二空，媒体报道西安“抢人才”盛况时配上唐太宗李世民的典故能突出艺术的效果。“烘托”指陪衬、使明显突出，填入符合句意。","no":115},{"id":"1718789646228","type":"single","material":"","stem":"利用互联网等信息技术促进留守儿童家庭的亲子交流，不仅有很强的必要性，也具备相当的（）。长期以来，我国科技和信息工作的推进，已经为（）留守儿童难题奠定了良好的软硬件基础。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"合理性;根治"},{"label":"B","content":"现实性;治理"},{"label":"C","content":"可行性;缓解"},{"label":"D","content":"针对性;解决"}],"answer":"C","explanation":"第一空，根据句意及词义较难排除，可选择从第二空入手。<br>第二空，利用互联网等信息技术促进留守儿童家庭的亲子交流，可以在一定程度上“缓解”留守儿童遇到的问题，但远远达不到“根治”“治理”“解决”这一问题的效果，排除A、B、D<br>验证第一空，与“奠定了良好的软硬件基础”相对应，此处应强调的是实现的“可行性”。","no":116},{"id":"1718789646229","type":"single","material":"","stem":"亚洲是全球最具活力的地区之一，经济规模占世界的1/3，人口有40多亿，劳动力供给充足，后发优势明显，发展潜力远未（）。同时，亚洲大多是发展中国家，人均GDP不高，地区发展水平很不平衡，还有7亿多人生活在国际贫困线以下，发展经济、改善民生的任务依然（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"开发;艰难"},{"label":"B","content":"解放;艰险"},{"label":"C","content":"释放;艰巨"},{"label":"D","content":"发挥;困难"}],"answer":"C","explanation":"第一空，“解放”指解除束缚，得到自由或发展，常与“思想”搭配，与“潜力”搭配不当，排除B“开发”指发现或发掘人才、技术等供利用；“释放”指把含有的物质或能量放出来；“发挥”指把内在的性质或能力表现出来。三者均可与“潜力”搭配。<br>第二空，由“7亿多人生活在国际贫困线以下”可知，发展经济、改善民生的任务繁重且不容易。“艰难”指困难。“艰巨”指困难而繁重。“困难”形容事情复杂，阻碍多。“艰巨”比“艰难”“困难”程度更重，且“艰巨的任务”也为习惯搭配，排除A、D","no":117},{"id":"1718789646230","type":"single","material":"","stem":"诗歌，这一文学皇冠上最古老而璀璨的明珠，在当代社会正面临着前所未有的境况。一面是大众偏见的（），譬如“诗歌就是分行”“写诗是无病呻吟”等论调甚嚣尘上；一面是诗歌内部的（），学术话语与商业话语分庭抗礼，业内与大众水火不容。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"流行;分歧"},{"label":"B","content":"蔓延;抵触"},{"label":"C","content":"横行;分裂"},{"label":"D","content":"干扰;争议"}],"answer":"C","explanation":"第一空，此处文意是错误言论很嚣张，含有贬义语境，“流行”是中性词，可首先排除A<br>第二空，由“学术话语与商业话语分庭抗礼，业内与大众水火不容”可知，“诗歌内部”的对立和矛盾已达到不可调和的情况，程度较重。比较“抵触”“分裂”“争议”,程度最重的“分裂”填入恰当。","no":118},{"id":"1718789646231","type":"single","material":"","stem":"三月的花，是迷人的。在花海里，抬头间，鼻尖就会触碰着花朵的温柔。颔首处，扑鼻而来的香氛，（）在身边。忍不住地想去，与花共眠。写不尽的花意，流水也在等待着花的（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"浮动;怜爱"},{"label":"B","content":"流动;垂爱"},{"label":"C","content":"流淌;关爱"},{"label":"D","content":"漂流;垂青"}],"answer":"B","explanation":"第一空，“流淌”“漂流”通常用来形容液体的流动，此处与“香氛”搭配，二者均不恰当，排除C、D<br>第二空，“怜爱”指对一个人的怜惜和疼爱，侧重于对对方的疼爱。其常用于男性对女性的一种感情表现，不符合流水和花之间的感情，排除A","no":119},{"id":"1718789646232","type":"single","material":"","stem":"土豆放置在潮湿环境中容易发芽，土豆发芽后会产生一种毒素叫作龙葵碱，龙葵碱对胃肠道黏膜有较强的刺激性，会产生（）效果，对中枢神经有麻痹作用，中毒的主要症状为胃痛加剧，恶心、呕吐，呼吸困难、急促，伴随全身虚弱（），严重者可导致死亡。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"消蚀;无力"},{"label":"B","content":"销蚀;衰微"},{"label":"C","content":"侵蚀;乏力"},{"label":"D","content":"腐蚀;衰竭"}],"answer":"D","explanation":"第一空，“消蚀”指由于风或其他气候因素所致的侵蚀而使地面降低，文段是说龙葵碱对人体的作用，排除A“侵蚀”指逐渐地侵害使变坏，由后文“中毒的主要症状为胃痛加剧，恶心、呕吐，呼吸困难、急促……”可推知，龙葵碱对人的伤害不是缓慢、逐渐、长期才发生效果的，排除C<br>第二空，“衰微”指(国家、民族等)衰弱、不兴旺，适用对象是无生命的事物，如家族、命运、财力，不能是人体，排除B“衰竭”指由于疾病严重而生理机能极度减弱，用于句中恰当，语义也能与后文“可导致死亡”对应。","no":120},{"id":"1718789646233","type":"single","material":"","stem":"当人类社会进入到信息时代，曾有人（），计算机是方块汉字的掘墓人。然而，事实（）了对汉字的这些偏见和悲观论调。据统计，现在已有1000多种汉字输入法，无论从速度还是准确率上看，方块汉字的计算机输入丝毫不逊色于拼音文字。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"宣称;打破"},{"label":"B","content":"断言;粉碎"},{"label":"C","content":"妄言;驳斥"},{"label":"D","content":"预言;批判"}],"answer":"B","explanation":"第一空，“宣称”指公开表示，一般用于说话者公开表示自己怎么样或要做什么,与句子语境不符，排除A“妄言”指胡说，随便说说，不合语境，排除C<br>第二空，“批判”与空缺前的“事实”不搭配，且由“无论……还是……丝毫不逊色”可知，选语义较重的“粉碎”更契合句子语境。","no":121},{"id":"1718789646234","type":"single","material":"","stem":"国家主席习近平在G20汉堡峰会上对全球经济治理的建议极具针对性。加强宏观政策（），有助于促进各方（），避免沟通不畅或是以邻为壑，进而打造开放共赢的合作模式。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"协调;互动"},{"label":"B","content":"调控;互通"},{"label":"C","content":"沟通;联动"},{"label":"D","content":"交流;联通"}],"answer":"C","explanation":"第一空，由前文“全球经济治理”、后文“避免沟通不畅或是以邻为壑”等可知，文意是强调加强各国联系、沟通，“调控”不符句意，排除B<br>第二空，“互动”指互相作用，互相影响；“联通”指互相联系相通；“联动”指若干个相关联的事物，一个运动或变化时，其他的也跟着运动或变化。对应前文“全球经济治理”和后文“打造开放共赢的合作模式”,可知句意不是强调各国间的交往，而是强调各国紧密关联，排除A与“联通”相比，“联动”指各国的紧密联系、协同发展，更契合句意，排除D","no":122},{"id":"1718789646235","type":"single","material":"","stem":"生态好转，意味着我们能遏制库木塔格大沙漠（）的脚步，让沙漠明珠——月牙泉依然（）在戈壁中，让弥足珍贵的莫高窟不会再次受到伤害。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"侵蚀;摇曳"},{"label":"B","content":"侵吞;流淌"},{"label":"C","content":"吞并;闪烁"},{"label":"D","content":"吞噬;镶嵌"}],"answer":"D","explanation":"第一空，“侵吞”指侵占吞没公物或他人资财。“吞并”指合并；并吞，兼并。二者多用于经济事务，排除B、C<br>第二空，“摇曳”形容东西在风中轻轻摆动的样子，也指悠游自得的样子，不能形容月牙泉在戈壁存在的状态，排除A<br>将D项代入验证，“吞噬的脚步”“镶嵌在戈壁中”搭配恰当。","no":123},{"id":"1718789646236","type":"single","material":"","stem":"选择是痛苦的，企业变革首先要革自己的命，企业转型升级的过程就是（）重生的过程。在这一过程中，企业家眼光既要向外，准确看到新时代环境的改变及趋势，又要向内，重新（）企业自身的优势与核心竞争力。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"蜕变;审视"},{"label":"B","content":"涅槃;考量"},{"label":"C","content":"改造;打量"},{"label":"D","content":"转化;检视"}],"answer":"A","explanation":"第一空，对应横线后的“重生”,所填词语应强调变化巨大。“蜕变”泛指人或事物发生质变；“涅槃”有重生之意；“改造”有从根本上改变旧的、建立新的的意思。三个词语均符合句意。“转化”指转变、改变。其语义程度较轻，不符合题意，排除D<br>第二空，此处意为在“重生”过程中，企业家要重新定位企业自身的优势与核心竞争力。“审视”指认真端详，与自我内省的文意符合。“考量”指考虑思量，不含有“看”的意思，不能用于“眼光向内”的语境，排除B“打量”指观察(人的衣着、外貌),不能形容企业家对企业自身状况的内省，排除C","no":124},{"id":"1718789646237","type":"single","material":"","stem":"在早已对漂亮假花、假树司空见惯的现代人眼里，干枯苍白的植物标本或许难有多少魅力可言。但在标本馆中，每一份看似不起眼的植物标本都代表着它在地球上的（）。它们虽然远离了阳光雨露，告别了生长的土地，却在科学殿堂中（）了自己的生命。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"物种;证明"},{"label":"B","content":"经历;重现"},{"label":"C","content":"存在;超越"},{"label":"D","content":"同类;延续"}],"answer":"D","explanation":"第一空，从常识来看，植物标本代表的只能是这类植物本身的形状及色彩等特征，不能代表它在地球上的“经历”,排除B<br>第二空，“证明”与“生命”不搭配，排除A植物标本“超越了自己的生命”的说法也欠妥，排除C“它们虽然远离了阳光雨露，告别了生长的土地”表示作为标本的植物已经没有了生命，故说它们在科学的殿堂中“延续”了自己的生命，契合句意。","no":125},{"id":"1718789646238","type":"single","material":"","stem":"在数字化多媒体时代，媒介参与的深度和广度日渐拓展，数字技术应用于文化遗产的保护已从原始的简单记录发展到对文化遗产的精准（），运用数字输入、摄像等各种数字化技术对文化遗产进行多形式的（），建立数字化的文化遗产档案和“非遗”博物馆等，都是当前很好的“非遗”保护方法。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"修复;展现"},{"label":"B","content":"描述;挖掘"},{"label":"C","content":"定位;探索"},{"label":"D","content":"复原;采集"}],"answer":"D","explanation":"第一空，由“从原始的简单记录发展到……\"”可知，横线处所填词语表述的行为应比简单地“记录”更进一步，“描述”与此不符，排除B“定位”不是对文化遗产的保护行为，排除C<br>第二空，运用数字技术的最终目的是“采集信息”,建立文化遗产档案和“非遗”博物馆，“展现”填入不合句意，排除A","no":126},{"id":"1718789646239","type":"single","material":"","stem":"①甲醛的有毒成分可通过呼吸道侵入人体，吸入过多易引发白血病。专家向消费者（）发出警告，尽量购买甲醛含量达到国家标准的装饰材料，要注意自我保护。<br>②最近，S政府针对某地区的房屋征收问题，专门在政府网站公布调查问卷，就是否应该征收、征收补偿以及后续安置等问题，向广大市民（）意见。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"严重;咨询"},{"label":"B","content":"郑重;征询"},{"label":"C","content":"慎重;征求"},{"label":"D","content":"审重;寻求"}],"answer":"B","explanation":"①句，“严重发出”搭配不当，排除A“郑重”指严肃认真；“慎重”指谨慎认真；“审重”指慎重。对应向消费者发出与健康相关的“警告”的语境，强调正式性、严肃性的“郑重”填入更恰当，排除C、D<br>②句，句意为通过在政府网站公布调查问卷的方式向群众询问意见，“征询”填入恰当。","no":127},{"id":"1718789646240","type":"single","material":"","stem":"十年久住的这海东的岛国，把我那同玫瑰露似的青春（）了的这异乡的天地，到了将离的时候，倒反而生出了一种不忍与她（）的心来。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"消遣;辞行"},{"label":"B","content":"消磨;诀别"},{"label":"C","content":"消磨;辞行"},{"label":"D","content":"消遣;诀别"}],"answer":"B","explanation":"第一空，由“反而生出了一种不忍”可知，作者居住在岛上时不太情愿，态度是消极的。“消遣”指设法度过闲散时间。“消磨”指耗去；逐渐消失；度过闲暇时间。“消磨时间”符合文意，排除A、D<br>第二空，“辞行”意为告别，“诀别”是不易再见的离别，二者词义相近，但“诀别”程度更重，与文段“不忍”的语境更相符，排除C","no":128},{"id":"1718789646241","type":"single","material":"","stem":"19世纪中叶以后，中国国内战争频仍，很多古籍（）海外。时至今日，究竟有多少古籍在海外存藏，还是一个未知数。而将分散在海外至少上百家图书馆的中文古籍全部统计清楚，（）在一个总目录之中，难度可想而知。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"流散;囊括"},{"label":"B","content":"流落;涵盖"},{"label":"C","content":"流失;收录"},{"label":"D","content":"散佚;罗列"}],"answer":"A","explanation":"第一空，由“分散在海外至少上百家图书馆的中文古籍”可知，此处强调的是由于中国的国内战争，很多古籍被带到海外，散落在不同国家的图书馆里。“散佚”多用于文献、诗歌等文字性著作的失传，词义与句意不符，排除D“流散”侧重于分散；“流落”侧重于沦落、失落；“流失”侧重于失踪、找不到。“流散”的“散”与后文强调整理统计工作的“难”更能构成呼应。<br>第二空，“囊括”指全部包罗，填入符合句意。","no":129},{"id":"1718789646242","type":"single","material":"","stem":"用人情做出来的朋友只是暂时的，用人格吸引来的朋友才是（）的。所以，丰富自己比取悦他人更有力量。大多时候，我们的忙碌其实是（）的。我们把自己累得气喘吁吁，最终却无功而返。与其追逐远方，不如做好脚下的事。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"长久;盲目"},{"label":"B","content":"永恒;必须"},{"label":"C","content":"确定;无奈"},{"label":"D","content":"可靠;无谓"}],"answer":"A","explanation":"第一空所填词语应与前句“暂时的”构成反义对应，据此排除无关的“确定”和“可靠”,即C、D<br>第二空，对应“我们把自己累得气喘吁吁，最终却无功而返”可知，我们的忙碌并不是“必须”的，排除B","no":130},{"id":"1718789646243","type":"single","material":"","stem":"每一项工业遗产都（）着城市社会发展的演变规律。实施对工业遗产的发掘保护、开发利用，对维护城市风貌，（）生机特色，克服千城一面现象，具有重要意义。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"凝结;保持"},{"label":"B","content":"凝集;保留"},{"label":"C","content":"凝聚;突出"},{"label":"D","content":"凝滞;凸显"}],"answer":"A","explanation":"第一空，“凝集”“凝聚”侧重“集”和“聚”,是强调把多个个体凝结聚集<br>在一起。“规律”是个体的，不是众多聚集在一起的，“凝集”“凝聚”与“规律”搭配不恰当，排除B、C“凝滞”指停止流动、不灵活，与“规律”搭配也不恰当，排除D<br>验证第二空，对应“维护城市风貌”“克服千城一面现象”等表述，“保持生机特色”符合句意。","no":131},{"id":"1718789646244","type":"single","material":"","stem":"家风是具有鲜明特征的家庭文化，良好家风是一个家庭最宝贵的精神财富，也是每个家庭成员形成正确世界观、人生观、价值观的（）。家庭是人生的第一所学校，良好家风是人生幸福生活的“第一组密码”。“积善之家，必有余庆；积不善之家，必有余殃”。只有守住和（）好温暖的家庭，才能有人生的成功。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"基点;庇护"},{"label":"B","content":"基准;保护"},{"label":"C","content":"基础;爱护"},{"label":"D","content":"基石;呵护"}],"answer":"D","explanation":"第一空，“基准”泛指标准，根据句意，空缺处是指家庭成员形成正确世界观、人生观和价值观的基础、根基，“基准”填入句意不通，排除B<br>第二空，“庇护”指袒护某对象，或保护其不受灾难，填入空缺处语义过重，排除A“爱护”与“家庭”搭配不当，排除C","no":132},{"id":"1718789646245","type":"single","material":"","stem":"一个人的成长成才，并不完全由其起点决定，而是看在这个过程之中个人所付出的努力。如果一味（）“出生在农村，注定样样落后”，不仅是对一些客观事实选择性地无视，而且（）了个人奋斗的价值。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"鼓吹;漠视"},{"label":"B","content":"宣扬;肯定"},{"label":"C","content":"渲染;抹杀"},{"label":"D","content":"鼓励;否定"}],"answer":"C","explanation":"第一空，此处表达的是夸大出身决定论的不利影响。“鼓励”指激发、勉励，填入明显与句意不符，排除D<br>第二空，“出生在农村，注定样样落后”的观念认为人的成功完全由其出身决定，否定了个人奋斗的价值，“肯定”填入与句意相悖，排除B“而且”提示此处所填词语应比前句的“选择性地无视”程度更重，“漠视”比“无视”程度轻，填入不合语境，排除A","no":133},{"id":"1718789646246","type":"single","material":"","stem":"自然是神奇美妙的。自然文学的作者（）在读者面前的，是含有风景、声音及心绪的多维画面。这三者相互交织，相辅相成，形成了自然文学的独特之处，也（）出独特的审美情趣和美学价值。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"展现;引申"},{"label":"B","content":"呈现;衍生"},{"label":"C","content":"描摹;演化"},{"label":"D","content":"描绘;发展"}],"answer":"B","explanation":"第一空，“描摹”“描绘”不能与“在……面前”搭配，排除C、D<br>第二空，“引申”指(字、词)由原义产生新义；“衍生”指演变产生。此处说的是自然文学产生的独特审美情趣和美学价值，用“衍生”更恰当，排除A","no":134},{"id":"1718789646247","type":"single","material":"","stem":"现在，创新的重要性已无须（）。这些年，无论是国家宏观层面，还是企业等微观层面，我国创新都取得了历史性成就。但也不用（），创新孤岛化问题还未根本解决。少数企业特别是一些传统企业，依然固守旧的观念。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"强调;遮掩"},{"label":"B","content":"苛求;藏匿"},{"label":"C","content":"赘述;讳言"},{"label":"D","content":"点明;噤声"}],"answer":"C","explanation":"第一空，句意为创新的重要性已经不需要再去说明。“强调”“赘述”“点明”均有说之意，“苛求”不符合文意，首先排除B<br>第二空，句意为虽然我国创新取得了历史性成就，但是还存在一些问题，对这些问题要说出来，不能不说。“遮掩”指遮蔽、掩盖、掩饰，“噤声”指闭口不作声，“讳言”指因有所顾忌而隐讳不说。“不用讳言”符合文段强调的应无所顾忌说出问题的语境，排除A、D","no":135},{"id":"1718789646248","type":"single","material":"","stem":"诗意在心头徘徊，明月在天空升腾。“举头望明月，低头思故乡。”在举头和低头之间，我们看到了千古诗仙李太白在他乡遥望故土的那份渴望和期盼，这（）的流光，却能让诗人的缠绵思绪在千万里的时空中（）而不觉遥远。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"蹉跎;穿梭"},{"label":"B","content":"斑驳;蔓延"},{"label":"C","content":"短暂;延伸"},{"label":"D","content":"瞬间;凝结"}],"answer":"C","explanation":"第一空，“蹉跎”指光阴白白地过去，形容虚度光阴。题干并未表达这一意思，排除A“斑驳”形容一种颜色中杂有别种颜色，花花搭搭的，形容“流光”,不恰当，排除B第二空，用来形容诗人的缠绵思绪在千万里时空中的状态。“凝结”指由气体变成液体或由液体变成固体，用在此处不恰当，排除D“延伸”指延长，伸展，形容诗人的思绪在时空中蔓延，恰当。","no":136},{"id":"1718789646249","type":"single","material":"","stem":"民法基本原则是贯穿于整个民事法律制度和民事规范始终的根本原则，对民事立法、民事司法和当事人民事活动具有（）的指导意义。不同的法律部门由于所（）的对象不同，所应采取的基本原则也不同。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"普遍;调整"},{"label":"B","content":"普适;针对"},{"label":"C","content":"全面;适用"},{"label":"D","content":"具体;覆盖"}],"answer":"A","explanation":"第一空，四个词语填入均符合句意，较难排除，可从第二空入手。<br>第二空，“法律的调整对象”是法律领域的专业术语。可快速锁定答案为A<br>验证第一空，此处对象为“民法基本原则”,强调的是其在民法领域适用的广泛性，“普遍”填入亦恰当。","no":137},{"id":"1718789646250","type":"single","material":"","stem":"七夕（）着传统女性乞巧习俗、忠贞不渝爱情观，被贴上现代时尚情人节的标签，已经愈加成为（）传统文化的窗口，成为青年人眼中表达浪漫爱情的舞台。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"承继;宣扬"},{"label":"B","content":"发展;弘扬"},{"label":"C","content":"沿袭;推广"},{"label":"D","content":"跟随;宣扬"}],"answer":"A","explanation":"第一空，由“传统女性乞巧习俗、忠贞不渝爱情观”可知，此处表达的是七夕这一节日中蕴含和传承的精神意义。“发展”指事物由小到大、由简单到复杂的变化；扩大(组织、规模等);为扩大组织而吸收新的成员。“跟随”指随从在后面。两词均未体现出“传承”之意，与题意不符，排除B、D“承继”有继承之意；“沿袭”指依照旧传统或原有的规定办理。二者填入均恰当。<br>第二空，“宣扬”指广泛宣传，使大家知道；“推广”指扩大事物使用的范围或起作用的范围。与“窗口”所含的展示之义相对应，“宣扬”填入更恰当，排除C","no":138},{"id":"1718789646251","type":"single","material":"","stem":"我们知道，制度是深深（）一个国家的历史、文化和现实之中的。一种制度只有与自身的历史、文化高度融合，才能最好地发挥其（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"融入;效果"},{"label":"B","content":"渗入;效用"},{"label":"C","content":"嵌入;效能"},{"label":"D","content":"切入;作用"}],"answer":"C","explanation":"第一空，“渗入”指液体慢慢地渗到里面去，也比喻某种势力无孔不入地钻进来(多含贬义);“切入”指(从某个地方)深入进去，如切入主题。二者填入均与句意不符，排除B、D<br>第二空，“效果”是由某种因素造成的结果，不能用来形容制度的作用，排除A“效能”指事物所蕴藏的有利的作用。“发挥效能”搭配恰当。","no":139},{"id":"1718789646252","type":"single","material":"","stem":"放弃语音套餐收入，才是流量经营全面成熟的开始。可喜的是，随着4G网络的普及，技术上VoLTE已经没有问题，商业上随着用户的（），移动互联网产品的（），流量经营正在迎来井喷的时代。语音通话方式也将成为流量经营的一部分，到那时，运营商将会有更充足的底气，敢于放手语音业务，彻底投入流量经营的怀抱。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"转向;进步"},{"label":"B","content":"迁移;发展"},{"label":"C","content":"移动;变更"},{"label":"D","content":"转动;更新"}],"answer":"B","explanation":"第一空，说的是随着流量经营迎来快速发展，传统语音套餐用户开始使用流量通话。“转向”“迁移”“移动”均可表达用户群体的转向。“转动”指变动，移动，走动。其多用于修饰具体事物，不适宜形容用户群的转向，排除D<br>第二空，所填词语应表述移动互联网产品的提升。“进步”多与“水平”“能力”搭配，与“产品”搭配不当，排除A“变更”不能体现互联网产品的提升，排除C","no":140},{"id":"1718789646253","type":"single","material":"","stem":"21世纪以来，大量书札文献以各种形式出版与（），也促进了学术界深入挖掘其中所包含的史料价值，阐发其中所（）的历史意义。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"披露;蕴涵"},{"label":"B","content":"问世;突显"},{"label":"C","content":"流传;显露"},{"label":"D","content":"展示;隐藏"}],"answer":"A","explanation":"第一空，根据句意，从此处入手较难辨析，可选择从第二空入手。<br>第二空，由“包含的史料价值”可知，此处的“历史意义”也应是隐含的。“突显”指突出地显露，“显露”指原来看不见的变成看得见的。二者填入均与句意相悖，排除B、C“隐藏”指藏起来不让发现，与“历史意义”搭配不当，排除D<br>验证第一空，“披露”指发表、公布。此处与“出版”并列，填入“披露”恰当。","no":141},{"id":"1718789646254","type":"single","material":"","stem":"如何去（）隐藏在已千变万化了的各种学说背后尚未完全遗失的经典原貌，获得真实的体温和人格图谱，从而剥离后世僵化、变异、乏味、随心所欲的解读，尤其是那些自以为智慧的肢解和（），当是目前国学热当中应解决的重要问题。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"探求;伪造"},{"label":"B","content":"搜寻;修改"},{"label":"C","content":"发掘;篡改"},{"label":"D","content":"挖掘;窜改"}],"answer":"C","explanation":"第一空，“探求”指探索寻求，“搜寻”指搜索寻找，“发掘”和“挖掘”指把隐藏的事物揭示出来。四词均有寻求之意。空缺处词语所搭配的宾语是“隐藏在……各种学说背后……经典原貌”,“掘”有挖开遮挡物的意思，“发掘”“挖掘”与“隐藏在……各种学说背后”更能对应，首先排除A、B第二空，“篡改”指用作伪的手段改动或曲解(经典、理论、政策等);“窜改”指改动(成语、文件、古书等)。此处表达对经典的曲解，应选“篡改”,排除D","no":142},{"id":"1718789646255","type":"single","material":"","stem":"科学家采用了一个笨办法，准备好一大片森林等兔子来撞。他们在巨大的探测器里装上大量反应物质，等待过路的暗物质粒子（）撞上其中某个原子核。当然，为了尽可能排除其他粒子撞上原子核而产生的干扰，科学家往往把这样的暗物质探测器深埋在地下，让厚厚的岩层把不会隐身的其他粒子尽可能（）在外面。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"碰巧;屏蔽"},{"label":"B","content":"突然;隔绝"},{"label":"C","content":"随机;阻挡"},{"label":"D","content":"偶然;封闭"}],"answer":"A","explanation":"第一空，由“科学家采用了一个笨办法，准备好一大片森林等兔子来撞”可知，文段把“原子核”比喻成“森林中的树”,把“暗物质粒子”比喻成“兔子”,兔子撞树是机缘巧合、偶发性的，所以第一空符合文意的是A项“碰巧”和D项“偶然”。“突然”侧重事情发生得急，事先没有准备，与“等待”语境不符，排除B“随机”是不设任何条件、随意的，侧重结果的随意性。而科学家采取的措施恰恰是为了保证暗物质粒子可以撞上某个原子核，所以不能是随意的，排除C<br>第二空，“屏蔽”是物理学领域常用术语，通常指隔离干扰的措施。科学家通过把暗物质探测器深埋在地下，尽可能排除其他粒子撞上原子核产生的干扰，符合文意。“封闭”是严密盖住或关住使不能通行或随便打开，侧重把物体封在里面，一般不能与“外面”连用，排除D","no":143},{"id":"1718789646256","type":"single","material":"","stem":"中国文化讲究因果，具体到陶瓷之上，明显能看出地域文化的影响。例如同为宋代青瓷，北方耀州青瓷与南方龙泉青瓷各自凸显性格，耀州青瓷呈橄榄绿，强调（）；龙泉青瓷呈梅子青，表现（）。演绎各自地方性格特点，色泽即可见一斑。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"豪放;婉约"},{"label":"B","content":"深沉;柔婉"},{"label":"C","content":"沉着;俏皮"},{"label":"D","content":"稳重;活泼"}],"answer":"B","explanation":"第一空，由句意可知，耀州青瓷和龙泉青瓷，同为绿色，一种颜色深，一种颜色浅。结合常识可知，深色的橄榄绿呈现出的应是沉稳的性格特点，“豪放”与此不符，排除A<br>第二空，由“各自凸显性格”“龙泉青瓷呈梅子青”可知，两种瓷器呈现深浅不同的两种绿色，进而呈现出不同的性格特点，“活泼”与“稳重”是完全相反的两种性格，差异过大，排除D“梅子青”莹润青翠，色泽柔和，“俏皮”不能体现其所代表的性格，排除C“柔婉”能体现出“梅子青”的特质，且“深沉”与“柔婉”相对，更能体现出二者性格的相关性和差异性，B项符合句意。","no":144},{"id":"1718789646257","type":"single","material":"","stem":"研究人员表示，忆阻器被植入人体内后，可以执行体征（）、疾病（）、伤口愈合跟踪的任务，并能够将信息无线传送给医生或患者，以便于采取后续措施。实验证实，可降解忆阻器可读写数百次，在干燥情况下，信息可储存3个月。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"监测;预警"},{"label":"B","content":"监控;预防"},{"label":"C","content":"监视;预报"},{"label":"D","content":"监管;预测"}],"answer":"A","explanation":"第一空，忆阻器被植入人体后，可对体征情况进行实时了解。“监测”指监察并检测；“监控”指监测并进行控制；“监视”指从旁监察注视；“监管”指监督管理。由下文“将信息无线传送给医生或患者”可知，该仪器无法对身体体征进行改变、处理，故排除B、D<br>第二空，“预警”除“预报”的意思以外，还有示警之意。在发现疾病的同时及时提醒，更符合这款仪器植入体内的目的。","no":145},{"id":"1718789646258","type":"single","material":"","stem":"当前及今后相当长的一段时期内，教育公平这一价值理念将是社会大众对教育的基本而强烈的诉求，是教育政策的核心价值追求，也是政府推动教育改革的基本（）。在教育公平价值理念的映射下，教育（）成为促进、实现教育公平的策略选择。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"目的;平等"},{"label":"B","content":"目标;均衡"},{"label":"C","content":"要求;均等"},{"label":"D","content":"需求;平衡"}],"answer":"B","explanation":"第一空，由“教育公平这一价值理念……也是政府推动教育改革的基本”可知，横线处所填词语应该体现“教育公平”与“政府”之间的关系。按照逻辑关系，“教育公平”不是“政府”的“要求”“需求”,排除C、D<br>第二空，“教育均衡”是习惯表述，排除A","no":146},{"id":"1718789646259","type":"single","material":"","stem":"缺乏必要的试错机制，很多政府部门和领导干部对改革创新都心存（）情绪，“不求有功，但求无过”，导致改革创新动力普遍不足。以此来看，（）“改革失败”的责任，创造一个宽容的创新环境，才能让更多的政府部门和官员“甩开膀子”谋改革、搞创新。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"畏难;豁免"},{"label":"B","content":"紧张;宽恕"},{"label":"C","content":"侥幸;淡化"},{"label":"D","content":"抵触;忽略"}],"answer":"A","explanation":"第一空，由“'不求有功，但求无过’,导致改革创新动力普遍不足”可知，“侥幸情绪”不合句意，排除C“畏难”指害怕困难；“紧张”指激烈或紧迫，使人精神紧张；“抵触”指跟另一方有矛盾。三词填入均符合句意。<br>第二空，与后句的“创造一个宽容的创新环境”对应，“忽略”不合句意，排除D“宽恕”常与“错误”“罪过”等搭配，与“责任”搭配不当，排除B“豁免”指免除，符合句意，且与“责任”搭配恰当。","no":147},{"id":"1718789646260","type":"single","material":"","stem":"面对逆境，尼采从来都是一个内心无比强大的人。在他的著作中，最广为人知的莫过于《查拉图斯特拉如是说》了。这本代表作在1885年出版时销量（），但这并不能阻止他继续深入思考自己的理论。在此之后，他还是不断自费印书。直到去世之后，他的思想才被重新（）和重视起来。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"下降;审视"},{"label":"B","content":"惨淡;发掘"},{"label":"C","content":"领先;评价"},{"label":"D","content":"尚可;借鉴"}],"answer":"B","explanation":"第一空，由转折词“但”可知，这本代表作在出版时销量并不好，尽管遭遇挫折，但尼采并没有放弃，此后还是不断自费印书。据此可排除表示销量很好和销量还行的C、D“下降”具有变化性，不能用于刚出版的书籍，排除A<br>第二空，“发掘”用于描述后人对尼采思想的探索研究恰当。","no":148},{"id":"1718789646261","type":"single","material":"","stem":"开花的塔黄零星分布在空旷的流石滩上，蕈蚊是如何及时发现它们的呢？原来蕈蚊头上的触角就像人类的鼻子，能感受并（）不同的气味。开花的塔黄会挥发20多种化合物，其中一种不常见的化合物（二甲基丁酸甲酯）占所有化合物的30%左右。野外诱导试验证实，这种化合物可以（）传粉的蕈蚊，为其“导航”。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"记忆;引诱"},{"label":"B","content":"区分;吸引"},{"label":"C","content":"识别;刺激"},{"label":"D","content":"追踪;迷惑"}],"answer":"B","explanation":"第一空，由“就像人类的鼻子”可知，此处所填词语应表达鼻子的功能，B项“区分”、C项“识别”符合文意，且与“不同的气味”搭配恰当。A项“记忆”与“鼻子”不搭配，排除。D项“追踪”的主体多为人，而不能是“鼻子”,且“追踪”的对象通常为某一特定的目标，即某一种气味，与“不同的气味”不搭配，排除D<br>第二空，由“导航”可知，这种不常见的化合物对蕈蚊具有一定的指引作用。B项“吸引”指把别的物体、力量或别人的注意力引到自己这方面来，能够体现“导航”之意。C项“刺激”指推动事物，使起积极的变化，与“导航”不能构成对应，排除。","no":149},{"id":"1718789646262","type":"single","material":"","stem":"如今音乐产业环境受到一定冲击，这使从业者十分茫然，但也毋须过分（）环境。相较于过去获取音乐渠道不多、选择相对较少的情况而言，现在文化消费的选择更为多元化。就此做出“现在不会有大师”这样的判断还太（），大师不可能只停留在过去。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"抱怨;武断"},{"label":"B","content":"依赖;随意"},{"label":"C","content":"重视;轻率"},{"label":"D","content":"苛求;主观"}],"answer":"A","explanation":"第一空，由“但”“相较于……而言，现在文化消费的选择更为多元化”可知，此处意为音乐产业环境虽受到一定冲击，但也有好的一面，所以无须过分指责环境。“依赖”“重视”与此不符，排除B、C<br>第二空，“武断”指主观轻率地判断，比“主观”多了一层不慎重的意思，与“就此做出”暗含的判断依据不充分的语境更对应。","no":150},{"id":"1718789646263","type":"single","material":"","stem":"区域是建构出来的。根据人为的目的划出的区域，已经不是原来在大地中生机勃勃、复杂多样的原本的那个地方了。划定的区域是简单的对世界的某一方面的一个概括而已，切不可（）我们建构的区域，认为这就是真实的世界，是天经地义的客观真理，不容他人（）或者变化一下。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"固执;申辩"},{"label":"B","content":"迷信;置喙"},{"label":"C","content":"痴迷;讨论"},{"label":"D","content":"拘泥;质疑"}],"answer":"B","explanation":"第一空，“固执”指坚持己见，不肯变通，多形容人的性格，其后不能接宾语，排除A“痴迷”指极度迷恋某人或某种事物而不能自拔。此处强调的是对建构出来的区域的错误认识，而非迷恋，排除C<br>第二空，“不容置喙”指不允许别人插嘴说话，为固定搭配的成语。“质疑”意为提出疑问以求解答，但不用于否定句式，排除D","no":151},{"id":"1718789646264","type":"single","material":"","stem":"虽然大学校园环境的文化熏陶作用是在潜移默化中逐步实现的，但为了保证校园环境有效地发挥作用，有必要对某些非言语信息有意识地进行（），让其主动争取学生的关注。不过，尽量不要让环境带有过于强制的色彩，以免使人产生（）的心理。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"引导;厌倦"},{"label":"B","content":"整合;抵触"},{"label":"C","content":"强化;排斥"},{"label":"D","content":"改造;逆反"}],"answer":"C","explanation":"第一空，根据后文“让其主动争取学生的关注”,可知句意是说有意识地对校园的非言语信息进行某种处理，使其更能吸引学生的注意。“整合”指通过整顿、协调重新组合，侧重强调使零散的事物成为系统、整体，而不是使事物发生某种可更有吸引力的改变，与句意不符，排除B<br>第二空，“厌倦”是由于接触过多而产生疲劳、厌烦；“排斥”是反感、拒绝、抵触；“逆反”是受到过多要求，反而希望按照与要求相反的方式行事。根据文段语境，“环境带有过于强制的色彩”是指环境带有过于明显、刻意的吸引学生关注的因素，这样的环境应是会引发学生的反感和抵触，而不是“厌倦”,“逆反”也无法说通，排除A、D","no":152},{"id":"1718789646265","type":"single","material":"","stem":"用饮用水国家标准衡量矿物质水，这对企业本身或许是好事，因为这（）着它不需要执行一个非常严格的标准。而在矿泉水“标准门”事件之前，消费者对饮用水安全性的（）没有上升到一个很高的层面，所以对企业产品而言，只要符合国家标准，就可以在市面上销售。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"意味;认知"},{"label":"B","content":"标志;认识"},{"label":"C","content":"预示;了解"},{"label":"D","content":"暗示;理解"}],"answer":"A","explanation":"第一空，“预示”侧重预测，用饮用水国家标准衡量矿物质水是既定事实，不存在预测的问题，排除C“暗示”侧重不明说，与文意也不相符，排除D<br>第二空，由“没有上升到一个很高的层面”可知，消费者对饮用水安全性的了解不够。与“认识”相比，“认知”表述更为正式，且“认知层面”为习惯表述。","no":153},{"id":"1718789646266","type":"single","material":"","stem":"我们应该（）“动物的大脑越大越聪明”这一观念。从19世纪的颅相学到21世纪的大脑扫描科学都认为，大脑的体积决定了认知能力。但有许多事实与此不符。有人出生时只有2/3的脑组织，但成年后并无认知（）。随着年龄增长，人的认知水平在提高，大脑体积却会缩小。对认知表现来说，重要的不是大脑的硬件，而是“软件”。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"质疑;差异"},{"label":"B","content":"抛弃;缺陷"},{"label":"C","content":"修正;障碍"},{"label":"D","content":"排除;问题"}],"answer":"B","explanation":"第一空，“排除”指除掉，消除，多指排除困难、排除险情等，与“观念”搭配不当，首先排除D“质疑”指提出疑问，由“对认知表现来说，重要的不是大脑的硬件，而是‘软件’”可知，“动物的大脑越大越聪明”这一观念已被证实是错误的，“质疑”语义程度过轻，排除A“修正”指修改使正确。文段仅指出这一观念与事实的矛盾之处，并未提出正确的观念应该是什么,排除C验证第二空，填入“缺陷”说明有人出生时部分脑组织缺少，但成年后认知正常，符合文意。","no":154},{"id":"1718789646267","type":"single","material":"","stem":"虽然太阳黑子变弱和地球变冷表面看有着70年的重合，但没有证据表明“小冰期”是由太阳黑子无记录造成的。而实际上，与太阳活动周强弱有关的全球气温变化（）其实是很小的，根据经验，最近几次太阳活动周影响全球平均气温的变化只有0.1摄氏度左右。因此，千万别随便就断言太阳周期变化能直接影响地球气温的（），以为地球马上就要进入新一轮“冰河期”了。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"范畴;突变"},{"label":"B","content":"幅度;骤变"},{"label":"C","content":"范围;剧变"},{"label":"D","content":"跨度;巨变"}],"answer":"B","explanation":"第一空，由后文“只有0.1摄氏度左右”可知，填入词语形容与太阳活动周强弱有关的气温变化，其应为气温变化的浮动，故排除表示领域的“范畴”及表示界限的“范围”,即A、C“跨度”形容距离，不能形容气温变化上数值较小的浮动，排除D<br>第二空，“气温骤变”搭配恰当。","no":155},{"id":"1718789646268","type":"single","material":"","stem":"在新时代，我们要大力提升发展质量和效益，坚持质量第一、（）质量变革、（）质量优势、建设质量强国、（）高质量发展。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"发动;增强;追求"},{"label":"B","content":"提倡;增加;达到"},{"label":"C","content":"推动;增强;实现"},{"label":"D","content":"倡导;增加;完成"}],"answer":"C","explanation":"第一空，由横线后的修饰词语“质量变革”可知，该处应填入一个能与“变革”相搭配的词语。“发动”常与“战争”“群众”“机器”等搭配。“提倡”“倡导”多与“新风尚”搭配，如“提倡勤俭节约”“倡导全民阅读”。三者均与“质量变革”搭配不当，排除A、B、D“推动变革”为习惯搭配。<br>验证后两空，“增强优势”“实现发展”均搭配恰当。","no":156},{"id":"1718789646269","type":"single","material":"","stem":"这深居太华山中的云湖，千百年来仰望着苍翠古木，（）着竹林风语，翕敛着涓涓溪流，融天地日月于怀中。见证着山河沧桑，（）着这方古老的土地。于万物生长的节奏中，感知着大地的冷暖，虚怀若谷地默默（）着历史岁月。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"聆听;守望;沉潜"},{"label":"B","content":"倾听;守护;沉潜"},{"label":"C","content":"聆听;守望;沉淀"},{"label":"D","content":"倾听;守护;沉淀"}],"answer":"C","explanation":"第一空，“聆听”指虔诚认真地听，带有尊敬色彩；“倾听”指细心地听取(多用于上对下)。由“仰望”可知，“倾听”填入不当，排除B、D<br>第二空两个词语都有“守候”之意，不易排除，可从第三空入手。<br>第三空，“沉潜”指在水里潜伏、沉没；思想感情深沉，不外露；集中精神，潜心。“沉淀”有“凝聚，积累”之意。与“历史岁月”搭配，用“沉淀”更恰当，排除A","no":157},{"id":"1718789646270","type":"single","material":"","stem":"地域可以（），职务可以（），职级可以（），但党员的身份始终不动。不管身处何地、身居何位，都理应“牢记自己的第一身份是共产党员，第一职责是为党工作，做到忠诚于组织，任何时候都与党同心同德”。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"变动;调动;流动"},{"label":"B","content":"转动;变动;流动"},{"label":"C","content":"调动;流动;变动"},{"label":"D","content":"流动;变动;调动"}],"answer":"D","explanation":"“变动”侧重“变”,强调变化多。“转动”侧重“转”,强调改变方向或情势。“调动”侧重“调”,强调安排处置。“流动”侧重“流”,强调移动。<br>第一空，说的是“地域”的变化，“转动”不合文意，排除B<br>第二空，与“职务”搭配，“流动”不恰当，排除C<br>第三空，“调动职级”是常见搭配，排除A","no":158},{"id":"1718789646271","type":"single","material":"","stem":"儒家在对“君子”进行阐述的时候，采取了一种极为（）的理论技巧。那就是，不直接定义“君子”，只是反复（）它的对立面。“君子”的对立面，就是“小人”。用一系列的否定，来完成一种肯定。这种方法，在逻辑学上，是通过（）外延，来包围内涵。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"罕见;列举;缩小"},{"label":"B","content":"精当;强调;剔除"},{"label":"C","content":"巧妙;叙述;限制"},{"label":"D","content":"高明;描绘;确认"}],"answer":"D","explanation":"第一空，此处意为儒家对“君子”下定义时，采用了什么样的叙述技巧，“那就是”后面对这种叙述技巧进行了具体阐释。“罕见”强调的是很少见到；“精当”强调的是精确恰当。“那就是”之后未体现“罕见”“精当”之意，排除A、B“巧妙”“高明”填入符合后文“不直接定义，而是通过否定、对比来定义”的方法。<br>第二空，“叙述”指记载或讲述事情的经过；“描绘”指描画或描述。对“小人”行为的阐释用“描绘”更为准确。第三空，“确认”填入也符合句意。","no":159},{"id":"1718789646272","type":"single","material":"","stem":"叶片眷恋地（），栖息在行人的身上，或是顺着头发身体（），无所依托地静卧在褐色的砖道上。深褐、暗红、浅黄及那些许丝丝绿色，在叶脉中若隐若现地（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"回旋;滑落;流淌"},{"label":"B","content":"回旋;飘落;交织"},{"label":"C","content":"舞动;滑落;交织"},{"label":"D","content":"舞动;飘落;流淌"}],"answer":"A","explanation":"第一空，由句中的“眷恋”可知，“回旋”比“舞动”更能传达出叶片对枝头的不舍，排除C、D<br>第二空，由句中的“顺着头发身体”可知，“滑落”比“飘落”更恰当。<br>第三空，对应“在叶脉中”,选“流淌”比“交织”更恰当。","no":160},{"id":"1718789646273","type":"single","material":"","stem":"①对于民众反映比较集中紧迫的事情，（）不当容易引发群体性事件。<br>②大雾天气致使飞机无法按时起飞，（）了我一天的行程。<br>③央行发布的史上最严新规是为了（）日益猖狂的金融犯罪和网络诈骗。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"应对;耽误;遏制"},{"label":"B","content":"治理;耽搁;遏止"},{"label":"C","content":"操作;耽误;遏止"},{"label":"D","content":"处置;耽搁;遏制"}],"answer":"A","explanation":"①,对于“事情”,“治理”“操作”均与其搭配不当，排除B、C②,“耽误行程”为习惯搭配，排除D③,“遏制”填入符合句意。","no":161},{"id":"1718789646274","type":"single","material":"","stem":"随着资本主义的迅猛发展，对资本主义的批判也越来越多。保守主义者们担心，与市场相适应的价值观和趋向（）到人类的其他组织形式中，会破坏国家、社区、家庭等组织。人们将自身与政府的关系简单地看作是一种市场关系，实质上是一种市场价值观的过度（）。同样，人们将市场的经济理性带到婚姻关系、家庭关系之中。不论是伯克、黑格尔、阿诺德，还是默瑟尔、哈贝马斯，事实上都在担忧市场经济的思想渗透到所有的人类关系之中，进而（）人类社会的“温情”。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"扩散;滥用;稀释"},{"label":"B","content":"散逸;蔓延;稀释"},{"label":"C","content":"外溢;蔓延;瓦解"},{"label":"D","content":"扩展;滥用;瓦解"}],"answer":"C","explanation":"第一空，由“保守主义者们担心……会破坏国家、社区、家庭等组织”可知，此处句意为保守主义者们担心市场价值观和趋向会影响人类其他组织。“散逸”指流散、散失、散适、洒脱，填入与句意不符，排除B<br>第二空，“滥用”指胡乱、过度地使用。其多指具体物质，不能修饰“市场价值观”,且填入与“过度”语义重复，排除A、D<br>第三空，“瓦解”填入符合句意，且与“渗透到所有……”构成递进关系。","no":162},{"id":"1718789646275","type":"single","material":"","stem":"新媒体的发展，尤其是自媒体的兴起，挑战着传统的新闻生产机制，在信息超载的同时，使新闻生产“去中心化”，新闻流动的把关功能（），不实消息（）网络。弥尔顿设想的“意见的自由市场”的自净功能并未实现，很多情况下谣言往往（）“真相”。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"消减;充满;淡化"},{"label":"B","content":"降低;充盈;消融"},{"label":"C","content":"削弱;充溢;消淡"},{"label":"D","content":"减弱;充斥;稀释"}],"answer":"D","explanation":"第一空，“消减”一般与“数量”搭配，“降低”一般与“质量”搭配，两词均不能与“功能”搭配，排除A、B<br>第二空，由“不实消息”“谣言”可知，此处所填词语应含贬义，“充溢”含褒义，排除C“充斥”含贬义，符合文意。<br>第三空，“稀释”能够体现“谣言”对于“真相”的负面作用。","no":163},{"id":"1718789646276","type":"single","material":"","stem":"地理位置不在沿线直接范围内的国家，也可以用新的形式加入“一带一路”合作，政策沟通、设施（）、贸易（）、资金（）、民心相通这五大合作理念与内容适用于世界上所有的国家和地区。随着形势的发展，“一带一路”也必将成为联结世界、融入全球的更为广阔的国际合作平台。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"联通;畅通;融通"},{"label":"B","content":"畅通;联通;融通"},{"label":"C","content":"畅通;融通;联通"},{"label":"D","content":"融通;畅通;联通"}],"answer":"A","explanation":"浏览选项后可知，每一项的词语都相同，只是顺序不一样，解题时可考虑从词语搭配入手。先看第三空，“融通”含有使资金流通之意，与“资金”搭配更恰当，排除C、D<br>再看第二空，“畅通”指畅行，顺利通过；“联通”指互相联系相通。与“贸易”搭配，用“畅通”更恰当，排除B<br>验证A项，“联通”与“设施”搭配恰当。","no":164},{"id":"1718789646277","type":"single","material":"","stem":"建筑设计，是一个科学问题，也是一个民主决策问题，规划设计要（）专业人士的意见，（）艺术创新。但是，城市公共建筑的设计规划，又是重要的公共事务，需要遵循民主决策、公开决策的原则，通过制度化的渠道，（）公众尤其是当地民众的意见。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"重视;保障;征集"},{"label":"B","content":"听取;保护;吸纳"},{"label":"C","content":"采纳;支持;吸收"},{"label":"D","content":"采用;维持;征求"}],"answer":"B","explanation":"第一空，由文段可知，建筑设计既是科学问题，要参考专业人士的意见，也是民主决策问题，要尊重公众的意见，故不可能直接“采纳”“采用”专业人士的意见，排除C、D“重视”“听取”填入均符合句意。<br>第二空，“保障”“保护”较难排除，继续分析第三空。<br>第三空，“吸纳”和“征集”都有收集之意，而“吸纳”多了一层“接纳”之意。结合文段，公众的意见不仅仅是收集上来即可，还需要听取、尊重，故选“吸纳”,排除A","no":165},{"id":"1718789646278","type":"single","material":"","stem":"种子，如果害怕（），那它永远不能发芽。鲜花，如果害怕（），那它永远不能开放。矿石，如果害怕（），那它永远不能成钢。航船，如果害怕风浪，那它永远不能到达彼岸。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"埋藏;凋零;燃烧"},{"label":"B","content":"掩埋;凋落;烧毁"},{"label":"C","content":"凋谢;埋没;焚烧"},{"label":"D","content":"埋没;凋谢;焚烧"}],"answer":"D","explanation":"第一空，“凋谢”只能描写鲜花，不能用于种子，排除C<br>第三空，“烧毁”强调毁坏，与“成钢”的语境不相符，排除B“燃烧”常与蜡烛搭配，与“矿石”搭配，“焚烧”更恰当。","no":166},{"id":"1718789646279","type":"single","material":"","stem":"我们是有着五千年文明传承的东方大国，儒家的“仁义礼智信”思想（）于民族精髓之中，社会主义核心价值观正是在（）传统思想精华的基础上应运而生。当下，改革释放出的红利推动中国经济的迅猛发展，与此同时，物欲膨胀带来的拜金主义、享乐主义、个人主义等一系列负面影响也（）着文明底线。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"扎根;吸收;触碰"},{"label":"B","content":"孕育;继承;挑战"},{"label":"C","content":"深植;汲取;冲击"},{"label":"D","content":"蕴藏;提炼;腐蚀"}],"answer":"C","explanation":"第一空四个词语意思相近，填入均符合句意，较难排除，可从第二空入手。第二空，“继承”与“精华”搭配不当，排除B<br>第三空，“腐蚀”与“底线”搭配不当，排除D文段意在说明物欲膨胀带来的负效应已经深深地影响到了文明底线，与“触碰”相比，“冲击”所表现的语义程度更重，更符合句意，排除A<br>将C项代入第一空验证，“深植于民族精髓之中”符合文意。","no":167},{"id":"1718789646280","type":"single","material":"","stem":"近百年来，由于过度使用照明工具而导致光污染的（），全球很多城市已看不到银河和主要的星座，人与生物圈的夜间环境遭到日益严重的（），天文科学观测也受到干扰，人类共同的星空资源正在逐渐“（）”。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"蔓生;侵袭;消解"},{"label":"B","content":"蔓延;侵蚀;消亡"},{"label":"C","content":"漫溢;侵吞;消弭"},{"label":"D","content":"漫卷;侵入;消散"}],"answer":"B","explanation":"第一空应填入一个形容“光污染”向四周扩散的词语。“蔓生”“蔓延”都可指植物向周围蔓延生长；“漫溢”指水过满向外流；“漫卷”指随风翻卷，用于形容旗帜。“漫溢”“漫卷”不能用于形容“光污染”,排除C、D<br>第二空，“侵袭”侧重突然地袭击，“侵蚀”侧重逐渐地侵害使变坏。与前文“日益严重”相对应，应选“侵蚀”,排除A<br>验证第三空，“消亡”指灭亡，消失。此处加了引号，意为星空虽然本身还存在，但是受到光污染的影响，其作为资源的价值正在消失。","no":168},{"id":"1718789646281","type":"single","material":"","stem":"在当代中国，维护社会公平正义，就是要在现代化进程中逐步建立起以权利公平、机会公平、规则公平为主要内容的社会公平保障体系，（）公平的社会环境，让公平正义的阳光（）每一个国民，使每个社会成员都能享有平等的权利，有实现个人理想的机会，有表达利益（）的合法途径。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"打造;映照;诉求"},{"label":"B","content":"营造;普照;诉求"},{"label":"C","content":"创造;照射;要求"},{"label":"D","content":"制造;照耀;要求"}],"answer":"B","explanation":"前两空词语意思相近，不易入手排除，可考虑从第三空入手。第三空，“表达利益诉求”为习惯搭配，排除C、D<br>第二空，“映照”指照射，“普照”指普遍地照耀。对应“使每个社会成员都能享有平等的权利”,“普照”所包含的“普遍”“平等”的意思更契合语境，排除A","no":169},{"id":"1718789646282","type":"single","material":"","stem":"一方面，受世界经济（）影响，大宗资源产品价格走低，资源型企业纷纷陷入困境，资源型城市财政收入也急剧下降，无力增加投入；另一方面，随着经济发展进入新常态，大规模经济刺激已经（），来自中央政府的强力支持相应减弱，资源型城市债务扩张趋于收紧。资源型城市转型面临的资金约束日益（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"下行;失效;紧张"},{"label":"B","content":"萎缩;放缓;强化"},{"label":"C","content":"低迷;弱化;严重"},{"label":"D","content":"恶化;减退;明显"}],"answer":"C","explanation":"第一空，由“大宗资源产品价格走低，资源型企业纷纷陷入困境，资源型城市财政收入也急剧下降”可知，世界经济状况不是很好，四个词语都能形容经济不好的状态，无法排除。<br>第二空，对应后句的“来自中央政府的强力支持相应减弱”,此处所填词语也应含有“减弱”的意思。C项“弱化”、D项“减退”都有程度减弱的意思，符合文段语境。“失效”程度过重，排除A“放缓”强调的是速度，而此处强调的是力度，排除B<br>第三空，与“明显”相比，“严重”更符合资源型城市转型遭遇的困境，排除D","no":170},{"id":"1718789646283","type":"single","material":"","stem":"传统曲艺中一两个演员借助简单的手持道具，靠说唱完成一场表演，没有过硬的功夫不行，不会与观众（）更不行。修养高深的曲艺表演者会使用各种手段拉近与观众的情感距离，（）引领观众参与艺术创造。在基本没有舞台布景和“灯服道效”相配合的（）表演环境中，曲艺演员要靠自身的表演征服观众，其难度远远大于其他舞台表演艺术。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"交流;主动;简约"},{"label":"B","content":"对话;巧妙;临时"},{"label":"C","content":"沟通;间接;单一"},{"label":"D","content":"互动;快速;虚拟"}],"answer":"A","explanation":"第一空，所给四个词语填入均符合句意，较难排序，可从第二空入手。<br>第二空，“主动”与“被动”相对，“巧妙”与“笨拙”相对，“间接”与“直接”相对，“快速”与“缓慢”相对。此处与“使用各种手段拉近与观众的情感距离”对应，“间接”“快速”均不恰当，排除C、D<br>第三空，“没有舞台布景和‘灯服道效’相配合”反映的是表演环境的简陋，“简约”填入恰当，“临时”与“表演环境”搭配不当，排除B","no":171},{"id":"1718789646284","type":"single","material":"","stem":"源远流长的中国传统文化，其本身即是不断变革的产物，它同样（）和促使我们，不断创新，去开创新的局面。也只有这样，我们自身传统才能被不断地（），我们才能在全球化背景下重新塑造出自己新的形象，向世界展示中华审美（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"责成;激活;风范"},{"label":"B","content":"责令;激发;境界"},{"label":"C","content":"推动;催化;格调"},{"label":"D","content":"触动;催生;特质"}],"answer":"A","explanation":"第一空，四个词语较难排除，可选择从第二空入手。<br>第二空，“激发”指刺激使奋发，常与“斗志”“积极性”等搭配，不能与“传统”搭配，排除B“催化”指促使化学反应的速率发生改变，侧重于加快进程；“催生”指因为某些原因，被迫形成当前状态；“激活”指刺激某事物，使其活跃起来。句意表达的是使传统不断活跃焕发出新的生机，用“激活”最恰当，排除C、D<br>验证其他两空：第一空，“责成”与“促使”并列恰当；第三空，“展示审美风范”搭配恰当。","no":172},{"id":"1718789646285","type":"single","material":"","stem":"父母要想让孩子接受更加大胆的早餐，就得自己也这样吃。孩子在子宫里时就开始品尝腌蛋和豆酱的味道了，出生后婴儿会喜欢他们在子宫里（）过的食物，科学家称之为产前味道学习。但孩子们天生会喜欢某种东西并不等于他们的舌头第一次（）到它时会很愉悦，网上有很多韩国婴儿第一次吃到泡菜时抓舌头甚至（）的视频。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"感应;接触;推拒"},{"label":"B","content":"感受;碰触;摇头"},{"label":"C","content":"接受;品尝;拒绝"},{"label":"D","content":"接触;体验;哭泣"}],"answer":"D","explanation":"第三空，由“甚至”可知，所填词语应与前句的“抓舌头”构成递进关系。“抓舌头”暗含了不喜欢、拒绝的意思，所填词语应表示拒绝的程度更重。只有“哭泣”与此相符，且与“婴儿”的角色契合。<br>验证前两空，“接触”“体验”填入也符合句意。","no":173},{"id":"1718789646286","type":"single","material":"","stem":"（）农业教育，（）新型职业农民，（）农技推广、服务推广等一系列举措，将促进农民科学素质提高、农村科技队伍壮大。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"发展;培育;强化"},{"label":"B","content":"加强;培训;建立"},{"label":"C","content":"创立;培养;加强"},{"label":"D","content":"发展;培训;加强"}],"answer":"A","explanation":"第一空，“创立”与“农业教育”搭配不当，排除C<br>第二空，由“新型职业农民”的“新型”可知，此处强调的是新事物从无到有的建立过程，用“培育”恰当，排除B、D<br>第三空，“强化”填入亦与“农技推广、服务推广”搭配恰当。","no":174},{"id":"1718789646287","type":"single","material":"","stem":"“心理弹性”的动力可能来自大脑激素反应、基因以及行为方式的共同作用，以保证一种情绪上的（）状态。它不仅帮助我们在人生变故、创伤面前不至于崩溃，也让我们在好的经验上不至于沉溺，比如享受美餐、赢得球赛、受到表扬，都不会持续太久，这可能因为人是天生的（）动物，在愉快的经验中沉浸太久，会（）识别新危险的能力。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"平衡;忧患;钝化"},{"label":"B","content":"应激;危险;弱化"},{"label":"C","content":"积极;健忘;异化"},{"label":"D","content":"稳定;懒散;退化"}],"answer":"A","explanation":"第一空，由“它不仅帮助我们在人生变故、创伤面前不至于崩溃，也让我们在好的经验上不至于沉溺”可知，“心理弹性”使得快乐与悲伤情绪都不会持续太久，使情绪维持在相对平稳的状态。“平衡”“稳定”符合此意，排除B、C<br>第二空，此处是在分析“我们在好的经验上不至于沉溺”的原因，后文对此进行解释，即在愉快的经验中沉浸太久会使人们丧失对危险的敏感性。时刻保持对危险的警惕性，对应的是忧患意识，A项的“忧患”填入恰当。“懒散”指精神松懈，行动散漫，不能对前文的“不至于沉溺”原因进行解释，排除D<br>代入A项第三空验证，“钝化”也与“能力”搭配恰当。","no":175},{"id":"1718789646288","type":"single","material":"","stem":"明末地理学家徐弘祖经34年旅行，写有天台山、雁荡山、黄山、庐山等名山游记17篇和《浙游日记》《江右游日记》等著作，除部分（）外，遗有60余万字游记（），去世后由他人整理成《徐霞客游记》。此书是以日记体为主的中国地理名著，对地理、水文、地质、植物等现象，均做（）记录。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"散落;素材;审慎"},{"label":"B","content":"流失;文稿;周密"},{"label":"C","content":"散佚;资料;详细"},{"label":"D","content":"缺失;著述;完备"}],"answer":"C","explanation":"第一空，与“遗有”对应，可知部分内容丢失了，“散落”侧重指分散下落，与句意不符，排除A“流失”“散佚”“缺失”侧重指丢失，填入符合句意。<br>第二空，由“去世后由他人整理成《徐霞客游记》”可知，“60余万字游记”未经整理前，不是成书，“著述”指编撰的成品，排除D“文稿”“资料”不是成品，符合句意。<br>第三空，“周密”指周到细密，多形容心思、计划等，不能修饰“记录”,排除B“详细记录”为习惯搭配。","no":176},{"id":"1718789646289","type":"single","material":"","stem":"未来将会怎样，不可准确预知，但格局和（）总有踪迹可循。在信息技术、互联网发展所（）的巨大变革面前，时代和社会呼唤产生一批真正的未来学家，能够站在历史和现实的关口，对信息社会的未来有所把握，为未来人们的生产和生活、选择和行为提供一些理论上的（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"路径;导致;服务"},{"label":"B","content":"趋势;引发;指导"},{"label":"C","content":"轨迹;带来;解释"},{"label":"D","content":"方向;造成;设想"}],"answer":"B","explanation":"前两空，所给词语较难辨析，可从第三空入手分析。<br>第三空，对应“站在历史和现实的关口”,未来学家所起到的是为未来的人们指明正确方向的作用，“指导”填入最能表达未来学家的这一作用。<br>验证前两空，第一空，“趋势”所表达的大的方向、走势的意思也与“格局”并列恰当。第二空，信息技术、互联网是引起巨大变革的导火索，“引发”填入也能准确表达这一含义，且“引发变革”搭配恰当。","no":177},{"id":"1718789646290","type":"single","material":"","stem":"当科技和生产力达到一定高度的时候，必然会（）未来人类的劳动结构和认知观念，人类的未来将不会重复自己，无须（）自身来构成生产关系，人们可以做更有价值的事情，相信那个时候就是丰富多元的文化（）的节点，也是人性最光辉的时刻。生活就不仅仅是为了生活，而是可以为了在有限的人生去（）存在的意义，多美好。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"颠覆;异化;进发;诠释"},{"label":"B","content":"革新;异化;盛开;证实"},{"label":"C","content":"颠覆;重构;进发;证实"},{"label":"D","content":"革新;重构;盛开;诠释"}],"answer":"A","explanation":"前两空所给词语词义相近，填入文段不好判断正误，可选择从第三空入手。<br>第三空，由“丰富多元的文化的节点”可知，空缺处所填词语应与“文化”搭配。分析选项，“盛开”指花朵绽放，不能与“文化”搭配，排除B、D<br>第四空，由横线后“存在的意义”可知，此处应填入一个与“意义”相搭配的词语。“证实”指确认、证明，通常与“真理”“消息”搭配，不能修饰“意义”,且“诠释……意义”为习惯搭配，排除C","no":178},{"id":"1718789646291","type":"single","material":"","stem":"为了加快供给侧结构性改革，必须（）现代产业体系，（）发展新动能，（）改革攻坚，（）国际合作。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"培育;构建;深化;推进"},{"label":"B","content":"培育;构建;推进;深化"},{"label":"C","content":"构建;培育;推进;深化"},{"label":"D","content":"构建;培育;深化;推进"}],"answer":"C","explanation":"前两空，“构建体系”“培育新动能”为习惯搭配，排除A、B后两空，“深化”与“攻坚”搭配不当，“深化合作”为习惯搭配，排除D","no":179},{"id":"1718789646292","type":"single","material":"","stem":"有人说，刘慈欣仅凭一己之力，就使中国的科幻小说（）于世界先进水平之列。这对于作家本人来说，（）是崇高的盛誉；但若从另一方面解读，其中何尝不隐含着十分的无奈。刘慈欣和《三体》的一花独放、单峰耸峙，（）出的是科幻小说界的整体低迷。就整体而言，无论是科幻小说的创作、出版、阅读和传播，还是改编拍摄成影视作品等（）艺术形式，中国跟世界先进水平都存在着巨大的差距。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"跃居;虽然;衬托;延伸"},{"label":"B","content":"跻身;固然;反衬;衍生"},{"label":"C","content":"跻身;当然;反映;派生"},{"label":"D","content":"踏入;固然;烘托;多种"}],"answer":"B","explanation":"第一空，“跻身……行列”为习惯搭配，“跃居”后常与“第一”“首位”之类的具体名次搭配，“踏入”后不能再接“于”,排除A、D<br>第三空，此处是以刘慈欣和《三体》的“一花独放”来从反面衬托国内科幻小说界整体的不景气，应选择“反衬”,排除C<br>第二空填入“固然”,第四空填入“衍生”均符合文意。","no":180},{"id":"1718789646293","type":"single","material":"","stem":"数字世界的革命固然玄妙，但其经济规模和在人们生活中的重要程度，直到今天，仍旧不能与实体世界（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"同日而语"},{"label":"B","content":"旗鼓相当"},{"label":"C","content":"一决高下"},{"label":"D","content":"平分秋色"}],"answer":"A","explanation":"句意为数字世界不能与实体世界相提并论。“同日而语”即放在同一时间讨论，指相提并论(多用于否定句),填入符合句意。“旗鼓相当”比喻双方力量不相上下，与句意相悖。“一决高下”指通过较量来分出实力的高低；“平分秋色”比喻双方各得一半，不分高低，表示平局。二者词意均与句意不符。","no":181},{"id":"1718789646294","type":"single","material":"","stem":"这篇小说的构思既精巧又严密，真是（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"无可非议"},{"label":"B","content":"无懈可击"},{"label":"C","content":"回味无穷"},{"label":"D","content":"不可思议"}],"answer":"B","explanation":"“无可非议”指没有什么可以指责的，表示言行合乎情理；“无懈可击”形容十分严密，找不到一点漏洞；“回味无穷”比喻回想某一事物，越想越觉得有意思；“不可思议”多指无法想象，难以理解。对应文中“构思既精巧又严密”,“无懈可击”填入最恰当。","no":182},{"id":"1718789646295","type":"single","material":"","stem":"数学研究所建立的各种计算方法和工具使得科学研究和现在一般意义上的哲学研究开始（），而科学研究的定量化又使得科学研究的成果能够得到实际应用，定量化正是科学和哲学彻底分离的最显著标志。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"各有怀抱"},{"label":"B","content":"各自为政"},{"label":"C","content":"分道扬镳"},{"label":"D","content":"分庭抗礼"}],"answer":"C","explanation":"由“定量化正是科学和哲学彻底分离的最显著标志”可知，空缺处应与“彻底分离”意思相近。“各有怀抱”指各人有各人的打算。“各自为政”指按照各自的主张做事，不互相配合；不顾全局，各搞自己的一套。“分道扬镳”比喻因目标不同而各奔各的前程或各干各的事情。“分庭抗礼”指双方平起平坐，实力相当，可以抗衡。比较可知，只有“分道扬镳”可修饰科学研究与哲学研究“彻底分离”的情况。","no":183},{"id":"1718789646296","type":"single","material":"","stem":"结构性改革是一项长期性任务，需要（）地推进。就当前而言，则需要针对突出问题加以解决。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"大刀阔斧"},{"label":"B","content":"持之以恒"},{"label":"C","content":"贯穿始终"},{"label":"D","content":"一劳永逸"}],"answer":"B","explanation":"空缺处所填词语应与“一项长期性任务”对应，强调推进工作的持续性。“大刀阔斧”形容办事果断而有魄力。“一劳永逸”指辛苦一次，把事情办好，以后就不再费事了。二者均不符合句意，排除A、D“贯穿始终”通常用于把某种思想、主题贯穿于某项工作始终的语境，不能描述某项工作推进的方式，排除C“持之以恒”与“长期性任务”对应恰当。","no":184},{"id":"1718789646297","type":"single","material":"","stem":"在社会中不同地位不同阶层的人的行为，对群众的影响是不同的，地位越高，影响越大，所以才会有“（）”的说法。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"人云亦云"},{"label":"B","content":"上行下效"},{"label":"C","content":"从善如流"},{"label":"D","content":"高山仰止"}],"answer":"B","explanation":"空缺处所填词语应能概括“地位越高，影响越大”。“人云亦云”指没有主见，只会随声附和。“上行下效”指上面的人怎么做，下面的人就模仿着怎么干。“从善如流”形容能迅速地接受别人的好意见。“高山仰止”比喻对高尚的品德的仰慕。根据词义，“上行下效”与强调地位高的人的行为对群众具有明显示范作用的语境相符。","no":185},{"id":"1718789646298","type":"single","material":"","stem":"“移风易俗”的口号喊了很多年，然而好的“新民俗”能诞生，不但需要有良好的愿望，还要有懂得民俗心理的“新创意”。这种创意，既衔接传统文化，又紧扣时代脉搏。唯有如此，才有可能让这种“新民俗”（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"相沿成俗"},{"label":"B","content":"蔚然成风"},{"label":"C","content":"久盛不衰"},{"label":"D","content":"约定俗成"}],"answer":"B","explanation":"由句意可知，所填词语需要承接上文，表示“‘新民俗’能顺利诞生并能够发展下去”之意。“蔚然成风”形容一种事物逐渐发展、盛行，从而形成风气，填入符合句意。<br>“相沿成俗”指因袭某种做法传下来，形成风俗习惯。由题干可知，“新民俗”是“新创意”,并非传承下来的，排除A“久盛不衰”形容事物盛行的时间很长，一直不衰退。题干中并未体现“久盛”之意，排除C“约定俗成”指事物的名称或社会习惯往往是由人民群众经过长期社会实践而确定或形成的，不符合句意，排除D","no":186},{"id":"1718789646299","type":"single","material":"","stem":"从统计学角度看，用平均数指标反映趋势虽精确敏感，但也有其致命弱点，尤其是平均数的“（）”，很容易掩盖个体之间的差异。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"以管窥天"},{"label":"B","content":"削峰填谷"},{"label":"C","content":"大而化之"},{"label":"D","content":"等量齐观"}],"answer":"B","explanation":"“平均数”是把总数按份均匀计算，以多补少。“以管窥天”指通过竹管来看天，比喻目光狭窄，只看到局部，而看不到全体。“大而化之”原指使美德发扬光大，进入化境，现用来表示做事疏忽大意。“等量齐观”指把不同的事物一律同等看待。三者均不能用来体现“平均数”的特点。因此，排除A、C、D“削峰填谷”,即削低山峰来填平山谷，取其比喻义，与“平均数”的特点相符。","no":187},{"id":"1718789646300","type":"single","material":"","stem":"如果仅仅将农村示范点建设成供人参观、应对检查的门面工程来扩造，则与示范点建设初衷（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"大相径庭"},{"label":"B","content":"不谋而合"},{"label":"C","content":"南辕北辙"},{"label":"D","content":"不约而同"}],"answer":"C","explanation":"分析可知，句意为如果仅将农村示范点建设成供人参观、应对检查的门面工程实际上与示范点建设的初衷是相背离的。“不谋而合”“不约而同”填入与句意相悖，排除B、D与“大相径庭”相比，“南辕北辙”体现的行动和目的正好相反的意思更符合句意。","no":188},{"id":"1718789646301","type":"single","material":"","stem":"国际电信世界大会上，审议具有24年历史的《国际电信规则》是一个巨大的挑战，因为要确保它能（），适应新一代信息通信技术用户的需求和全球化、激烈竞争和创新不断加深的技术环境。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"推陈出新"},{"label":"B","content":"与时俱进"},{"label":"C","content":"精益求精"},{"label":"D","content":"破旧立新"}],"answer":"B","explanation":"句意为审议“具有24年历史的”《国际电信规则》,使得它能适应新一代用户的需求和不断变化的技术环境，可见审议后的《国际电信规则》关键是要能“与时俱进”。“推陈出新”“破旧立新”侧重的都是推翻旧的，创造出新的，针对的主要为思想、文化，与《国际电信规则》不搭配。“精益求精”意为已经很好了，还要更好，没有体现适应时代的意思，排除。","no":189},{"id":"1718789646302","type":"single","material":"","stem":"意志力特训是训练孩子以坚强的意志，带领自己的团队，并百折不挠、（）、勇敢地克服困难。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"坚若磐石"},{"label":"B","content":"固若金汤"},{"label":"C","content":"坚不可摧"},{"label":"D","content":"稳如泰山"}],"answer":"A","explanation":"由顿号可知，空缺处所填词语应与“百折不挠”构成并列关系，与前文“坚强的意志”相呼应，体现意志力的坚韧。“固若金汤”形容城池和阵地非常坚固，不能指人的意志力，排除B“稳如泰山”形容像泰山一样稳固，不可动摇，也可形容人在紧急情况下的从容态度。其侧重“稳”,未体现出“坚”,排除D“坚若磐石”指像大石头一样坚固，比喻不可动摇；“坚不可摧”指非常坚固，摧毁不了。“坚不可摧”通常用于具体事物，此处描述抽象的“意志力”,用“坚若磐石”更恰当。","no":190},{"id":"1718789646303","type":"single","material":"","stem":"圆明园废墟是北京城最有历史感的文化遗迹之一，如果把它完全铲平，造一座崭新的圆明园，该是多么（）。大清王朝不见了，熊熊火光不见了，民族的郁愤不见了，历史的感悟不见了，抹去了昨夜的故事，收拾来的只是今日的游戏。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"天马行空"},{"label":"B","content":"得不偿失"},{"label":"C","content":"耸人听闻"},{"label":"D","content":"不可思议"}],"answer":"B","explanation":"分析可知，空缺处应与后文构成解释关系。由“……不见了……不见了……抹去了昨夜的故事，收拾来的只是今日的游戏”可知，题干意为造一座崭新的圆明园只会让人们忘记历史的伤痛，什么也得不到。“得不偿失”指得到的抵不上失去的，填入与句意相符。“天马行空”强调说话做事不着边际，“耸人听闻”强调令人震惊、惊骇，“不可思议”强调难以理解。三者填入句中均不恰当。","no":191},{"id":"1718789646304","type":"single","material":"","stem":"在候鸟的眼中，中国的东北是湖沼成群、草水茫茫的绝佳驿站。每年春季，鹤、鹳、天鹅等候鸟纷纷飞向安静凉爽的地球北端求偶育雏。漫漫长路之中，它们会（）地从富饶的东北湿地经过，有的吃饱睡足后继续北上，有的则干脆在这里筑巢成家，等待秋天的到来。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"千里迢迢"},{"label":"B","content":"拖家带口"},{"label":"C","content":"不约而同"},{"label":"D","content":"隔三岔五"}],"answer":"C","explanation":"由“中国的东北是湖沼成群、草水茫茫的绝佳驿站”“有的吃饱睡足后继续北上，有的则干脆在这里筑巢成家”可知，众多候鸟都把东北作为漫漫迁徙旅途的中转站。因此，尽管没有统一商量，它们也会在飞往育雏之地的途中“有默契”似的选择“中国的东北”。<br>A项的“千里迢迢”形容路途遥远，与横线前面的“漫漫长路”语义重复，排除。B项的“拖家带口”指带着一家大小，与文中“飞向安静凉爽的地球北端求偶育雏”的句意相悖，排除。C项的“不约而同”指没有事先商量而彼此见解或行动一致，填入与句意最相符合。D项的“隔三岔五”指每隔不久，时常。句意强调的是候鸟行动一致，而非行动频繁，排除。","no":192},{"id":"1718789646305","type":"single","material":"","stem":"雾霾的形成，因素很多，是个长期积累的过程。治理雾霾也不是（）的，而是要打持久战，久久为功。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"信手拈来"},{"label":"B","content":"一蹴而就"},{"label":"C","content":"立竿见影"},{"label":"D","content":"轻而易举"}],"answer":"B","explanation":"空缺处所填词语应与后句的“打持久战，久久为功”意思相反，表示雾霾治理是简单地、在短时间内能取得成效的。B项“一蹴而就”比喻事情轻而易举，一下子就成功，符合文段语境，且“一蹴而就”中的“一”与后句的“久”对应恰当。<br>“信手拈来”多指写文章时能自由纯熟地选用词语或应用典故，与“治理雾霾”搭配不当，排除A“立竿见影”比喻立刻见到功效，未体现事情容易成功，排除C“轻而易举”形容事情容易做，不费力气，不含时间短的意思，排除D","no":193},{"id":"1718789646306","type":"single","material":"","stem":"在这个万物互通互联的时代，单个企业是无法“（）”的，只有人人安全、合作伙伴都安全、整个环境都安全，才能最大限度地保障自己的网络安全，这也是网络安全的更高等级——生态安全。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"明哲保身"},{"label":"B","content":"独善其身"},{"label":"C","content":"自给自足"},{"label":"D","content":"自力更生"}],"answer":"B","explanation":"由“万物互通互联”可知，句中强调的是企业与群体、环境之间的密切关系，即任何一个企业都不可能脱离大环境而保障自己的网络安全。“自给自足”“自力更生”均强调依靠自己的力量生存，不依赖别人的救济和帮助，多用于经济方面，填入不合语境，排除C、D“明哲保身”为贬义词，指因怕连累自己而回避原则斗争的处世态度。“独善其身”为中性词，指在污浊的环境中能不受干扰地坚持自己的美好品格；也比喻只顾自身而不管他人的个人主义处世哲学。描述个人与环境的关系，填“独善其身”更恰当。","no":194},{"id":"1718789646307","type":"single","material":"","stem":"中国是文明古国，礼仪教化之邦。如果有人在大庭广众之下喧哗不止，则不免让人（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"侧目而视"},{"label":"B","content":"恨之入骨"},{"label":"C","content":"置若罔闻"},{"label":"D","content":"不以为然"}],"answer":"A","explanation":"“恨之入骨”形容痛恨到极点，用于描述对喧哗不止行为的态度语义程度过重，排除B“置若罔闻”指放在一边不管，好像没有听见一样；形容不重视、不关心。其不能表达对大庭广众喧哗这一不文明行为的否定态度，排除C“侧目而视”形容畏惧而又愤恨；“不以为然”表示不同意或否定。“不以为然”通常用于“对……不以为然”的句式，与“让人”搭配不当，排除D","no":195},{"id":"1718789646308","type":"single","material":"","stem":"科普影评的作者应寻找科学与电影的交汇点，将科普和艺术（），启迪思想。他们将前沿领域研究成果，结合电影转化为更轻松易懂的文字，面向更多读者。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"融会贯通"},{"label":"B","content":"合二为一"},{"label":"C","content":"珠联璧合"},{"label":"D","content":"相提并论"}],"answer":"A","explanation":"由“将前沿领域研究成果，结合电影转化为更轻松易懂的文字”可知，科普影评的作者将科普和电影相结合，使深奥的科学知识浅俗化，从而更容易被普通人接受。“合二为一”“相提并论”均未体现二者之间的这种结合，排除B、D“融会贯通”指融合多方面的知识道理，得到全面、透彻的领悟；“珠联璧合”比喻杰出的人才或美好的事物结合在一起，多用来形容男女之间的感情。与“启迪思想”连用，“融会贯通”更恰当。","no":196},{"id":"1718789646309","type":"single","material":"","stem":"“愤怒”是对德国作家格拉斯个人风格的准确概括。然而，在他的盖棺之作《万物归一》里，这种“愤怒”似乎已经不那么（）了。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"引人注目"},{"label":"B","content":"显而易见"},{"label":"C","content":"司空见惯"},{"label":"D","content":"锋芒毕露"}],"answer":"D","explanation":"由“然而”这一转折词可知，文段前后意思相反，即格拉斯的盖棺之作《万物归一》中，其“愤怒”的个人风格已经有所收敛，没有之前那么明显了。故所填成语应具有明显表露的意思。“引人注目”形容人或事物很具特色，引起人们的注意。“显而易见”指事情或道理很明显，极容易看清。“司空见惯”指某事常见，不足为奇。“锋芒毕露”指刀锋和矛尖都露出来；比喻锐气和才干全都表现出来。结合词义，“锋芒毕露”填入更契合句意。","no":197},{"id":"1718789646310","type":"single","material":"","stem":"19世纪末，中国维新派代表人物严复将经济学家亚当·斯密的著作译为《原富》，献给光绪皇帝，但并没有引起足够重视。可以说，与市场经济（）是近代中国经济落后的重要原因。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"若即若离"},{"label":"B","content":"分道扬镳"},{"label":"C","content":"南辕北辙"},{"label":"D","content":"失之交臂"}],"answer":"D","explanation":"分析题干可知，近代中国由于没有重视市场经济，从而导致了中国近代经济的落后，故空缺处所填词语应表示错失良机的遗憾之意。<br>“若即若离”指好像接近，又好像不接近，形容对人保持一定距离。中国近代经济并非与市场经济保持距离，而是根本没有重视，排除A“分道扬镳”比喻因目标不同而各奔各的前程或各干各的事情。文段没有近代中国经济和市场经济目标不同之意，排除B“南辕北辙”比喻行动和目的正好相反。文中强调的是错失机会，没有行动和目的之意，排除C“失之交臂”指当面错过，失掉好机会，填入符合语境，且能体现出作者的惋惜之情。","no":198},{"id":"1718789646311","type":"single","material":"","stem":"几年前，曾有人写文章发问：雄辩胜于事实的年代，谁关心真相？这话可谓（）。听清事实，是一切判断的基础。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"奇谈怪论"},{"label":"B","content":"掷地有声"},{"label":"C","content":"振聋发聩"},{"label":"D","content":"不可理喻"}],"answer":"C","explanation":"由“听清事实，是一切判断的基础”可知，作者认同前文的提问。“奇谈怪论”“不可理喻”与文意相悖，排除A、D“掷地有声”比喻文章文辞优美，语言铿锵有力；“振聋发聩”比喻用语言文字唤醒糊涂麻木的人。“振聋发聩”填入更能突出前文提问的警醒作用。","no":199},{"id":"1718789646312","type":"single","material":"","stem":"实际上雾霾形成的原因是多方面的，识别污染源是有效治理大气污染至关重要的环节。对京津冀区域而言，认清区域内污染源的共性及差别，有助于区域内地区（）地对污染源进行综合治理。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"有的放矢"},{"label":"B","content":"因地制宜"},{"label":"C","content":"齐心协力"},{"label":"D","content":"正本清源"}],"answer":"A","explanation":"文段强调的是识别污染源可以使各地区在治理雾霾时更有针对性。“有的放矢”意为放箭要对准箭靶子，比喻说话做事有明确的目的性和针对性。“污染源”恰对应雾霾的“的”,认清了污染源，治霾也就有了针对性，故空缺处填“有的放矢”最恰当。<br>“因地制宜”指根据不同地区的具体情况制定适宜的措施。文段中只是提到京津冀这一区域的污染源，并未提到其他区域，且前文说的是“共性及差别”两方面，排除B“齐心协力”指思想一致、共同努力，侧重强调共同努力，未体现出针对性，排除C“正本清源”指从根本上清理整顿。“本”“源”与后文的“污染源”语义重复，排除D","no":200},{"id":"1718789646313","type":"single","material":"","stem":"买书，是藏书家郑振铎几乎每天要做的一件事，流连于书肆地摊上“淘旧书”，几十载不曾间断。按说该有一定经验不至于上当受骗了吧？无奈率真坦诚、（）的郑先生不善委蛇之术，每次买书遇到中意的本子，便是一连串“不得了”“好极了”的激动赞叹声，接着还大侃书的种种优点和妙处，待侃完交钱时，精明的书贩当然饶不过他了。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"光明正大"},{"label":"B","content":"光明磊落"},{"label":"C","content":"胸无城府"},{"label":"D","content":"高深莫测"}],"answer":"C","explanation":"由顿号和“不善”可知，空缺处所填词语应与“率真坦诚”构成并列关系，与“委蛇之术”构成反对关系。从后文对郑振铎先生遇到好书时在书贩面前不加掩饰称赞的描述，也可判断文段是在说郑振铎先生不善心机。“光明正大”“光明磊落”侧重正直、坦白；“高深莫测”侧重难以估摸。填入三者均与句意不符，排除A、B、D“胸无城府”形容心胸坦率，填入恰合句意。","no":201},{"id":"1718789646314","type":"single","material":"","stem":"讲故事当然需要技巧，让一个无趣的人来讲，即使故事的内涵深厚，又曲折回环、跌宕起伏，也可能被讲得（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"丢三落四"},{"label":"B","content":"索然无味"},{"label":"C","content":"不堪入耳"},{"label":"D","content":"天花乱坠"}],"answer":"B","explanation":"句意为无趣的人能把本来有趣的故事讲得无趣。“丢三落四”形容因做事粗心或记忆力不好而顾此失彼；“索然无味”形容呆板枯燥，一点意味或者趣味都没有；“不堪入耳”形容脏话难听；“天花乱坠”形容人说话巧妙动听，但虚妄、空洞不着边际。只有“索然无味”与“无趣”的语境构成对应。","no":202},{"id":"1718789646315","type":"single","material":"","stem":"除了那些家喻户晓的“国宝”，中华大地上还有不少动物正处于或正在走向“濒危”行列。由于种种原因，它们所面临的危险还未被重视，甚至它们的名字和样子都（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"默默无闻"},{"label":"B","content":"鲜为人知"},{"label":"C","content":"无人问津"},{"label":"D","content":"一无所知"}],"answer":"B","explanation":"与家喻户晓的“国宝”相比，还有不少动物虽然同样濒危，却很少为世人所知。“默默无闻”指平凡，名声不显，没人知道，一般用来形容人，不能说动物的“名字和样子”默默无闻，排除A“无人问津”形容受冷落，没有人再来尝试或过问某件事、某种东西。句中这些动物是不被人所知道，而非人们不关心、刻意去冷落它们，排除C“一无所知”指什么也不知道，主语为人，一般用法为“某人对……一无所知”,此处主语为“它们的名字和样子”,填入搭配不当，排除D“鲜为人知”指极少被人们知道，用来描述很多“濒危”动物不被大众所知的情况恰当。","no":203},{"id":"1718789646316","type":"single","material":"","stem":"从十九大到二十大，是“两个一百年”奋斗目标的历史交汇期。我们既要全面建成小康社会、实现第一个百年奋斗目标，又要（）开启全面建设社会主义现代化国家新征程，向第二个百年奋斗目标进军。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"迎难而上"},{"label":"B","content":"乘势而上"},{"label":"C","content":"一鼓作气"},{"label":"D","content":"中流击水"}],"answer":"B","explanation":"由“历史交汇期”可知，我们现在处于一个承上启下的阶段，既要实现第一个百年奋斗目标，又要在已取得成绩的基础上，开启第二个百年奋斗目标的新征程。“一鼓作气”指趁劲头大的时候一口气把事情干完。“百年奋斗目标”的实现是一个长期的过程，不可能一下子完成，排除C“中流击水”的意思是在河流最湍急的地方游泳，也就是逆流而上。A项“迎难而上”和D项“中流击水”强调的都是在逆境中勇于挑战，而B项“乘势而上”强调利用有利的形势(做某事)。在第一个百年奋斗目标完成的基础上再接再厉开启第二个百年奋斗目标，属于有利的形势，而非逆境，“乘势而上”填入更恰当，排除A、D","no":204},{"id":"1718789646317","type":"single","material":"","stem":"从亚里士多德开始，让文学艺术能够真正地还原现实，从而使人们能够在各种艺术样式中复现自己、观照自己，一直是理论家、艺术家的一个永恒的梦想。没想到，这个梦想居然被电影（）地实现了。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"分毫不差"},{"label":"B","content":"出人意料"},{"label":"C","content":"轻而易举"},{"label":"D","content":"一马当先"}],"answer":"C","explanation":"“从亚里士多德开始……一直是理论家、艺术家的一个永恒的梦想”强调的是这个梦想很难实现。“没想到”和“居然”是对前面困难程度的否定，暗含了电影实现这一梦想的容易、不费力。“分毫不差”指没有一点差错；“出人意料”指在人们意料之外；“轻而易举”比喻非常轻松，不费力气；“一马当先”形容领先或带头。根据词义，“轻而易举”填入最恰当。","no":205},{"id":"1718789646318","type":"single","material":"","stem":"世界上没有完美无缺的医疗体系，无论是免费医疗还是市场化的医疗体系，都各有弊端。但从生存权和人的尊严的角度看，对个人免费或少量收费的医疗实乃（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"未雨绸缪"},{"label":"B","content":"万全之策"},{"label":"C","content":"大势所趋"},{"label":"D","content":"当务之急"}],"answer":"C","explanation":"文段首先承认免费医疗和市场化的医疗体系都有弊端，然后以“但”转折，肯定了对个人免费或少量收费的医疗体系的进步性。“万全之策”指极其周全妥当的计谋，与“没有完美无缺的医疗体系”相悖，排除B“未雨绸缪”比喻事先做好准备工作，强调事先做准备；“当务之急”指当前事务中最为紧要的事。文段并未体现事先做准备、紧要之意，排除A、D<br>“大势所趋”指整个局势发展的趋向。对应“从生存权和人的尊严的角度看”,“大势所趋”所含的未来趋向性符合句意。","no":206},{"id":"1718789646319","type":"single","material":"","stem":"传媒产业的发展史，就是一部技术发展史。所以，当互联网技术（）之时，传统媒体的处境就开始变得尴尬。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"无孔不入"},{"label":"B","content":"突飞猛进"},{"label":"C","content":"如日中天"},{"label":"D","content":"一统天下"}],"answer":"B","explanation":"空缺处所填词语应表技术发展之义。“无孔不入”比喻有空子就钻，含贬义，感情色彩与语境不符，排除A“一统天下”填入程度过重，排除D“突飞猛进”形容进步和发展特别迅速；“如日中天”比喻事物正发展到十分兴盛的阶段。此处用“突飞猛进”更能表达目前互联网技术飞速向前发展的特点。","no":207},{"id":"1718789646320","type":"single","material":"","stem":"政府部门应该在社区治理中鼓励社区自治。假如政府部门在这过程中（），没有处理好社区自治和政府管理的关系，那么，最终所做出的决策就很可能会引发社会矛盾。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"李代桃僵"},{"label":"B","content":"萧规曹随"},{"label":"C","content":"越俎代庖"},{"label":"D","content":"广纳良言"}],"answer":"C","explanation":"由“鼓励社区自治”可知，没有处理好社区自治和政府管理之间的关系可能是没有让社区自治起来，即政府部门越权干预了社区管理工作。空缺处所填词语应含贬义。“广纳良言”指广泛地听取、采纳好的建议，为褒义词，首先排除D“李代桃僵”比喻相互替代或代人受过，句中意在强调越权，并未体现取代之意，排除A“萧规曹随”比喻按照前人的成规办事，与文意无关，排除B“越俎代庖”比喻超出自己的业务范围去处理别人所管的事。政府干预社区自治工作，应填“越俎代庖”。","no":208},{"id":"1718789646321","type":"single","material":"","stem":"文化传统的延续，从来不是（）地照搬照抄。取其精华，去其糟粕，根据时代发展做出合乎社会需求的调整，才是对文化的最好传承。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"不假思索"},{"label":"B","content":"囫囵吞枣"},{"label":"C","content":"按部就班"},{"label":"D","content":"一成不变"}],"answer":"D","explanation":"由“根据时代发展做出合乎社会需求的调整，才是对文化的最好传承”可知，空缺处所填词语应与“调整”构成反义对应，表达“不变”的意思。“不假思索”形容说话做事迅速；“囫囵吞枣”指读书等不加分析笼统接受；“按部就班”指遵循一定的程序；“一成不变”指一经形成，不再改变。D项的“一成不变”符合文意，排除A、B、C","no":209},{"id":"1718789646322","type":"single","material":"","stem":"解决当今人类遭遇的各种难题和危机，单靠一种文明价值的智慧和能量，常常显得（）。只有充分挖掘和利用各种不同禀性的文明价值资源，才能帮助人类破解难题、走出危机。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"捉襟见肘"},{"label":"B","content":"格格不入"},{"label":"C","content":"于事无补"},{"label":"D","content":"顾此失彼"}],"answer":"A","explanation":"文段说的是单靠一种文明价值的智慧和能量往往很难彻底解决问题，需要发掘不同的文明价值资源。“格格不入”形容彼此不协调，不相容。“于事无补”指对事情没有什么益处。两词不合文意，排除B、C“捉襟见肘”比喻顾此失彼，穷于应付。“顾此失彼”意为顾了这个，失了那个。文段强调的是一种文明价值的局限性，“捉襟见肘”填入更形象。","no":210},{"id":"1718789646323","type":"single","material":"","stem":"<p>近两年，有一种产自东北的非主流水果——菇娘（这个“娘”在东北读作三声，并缀以儿化音）颇有（ &nbsp; ）之势。每逢春夏之交，大大小小的水果铺子，都少不了菇娘小巧的身影，而它特有的香气与口感据说确实俘获了不少姑娘的舌尖呢。</p><p>填入括号部分最恰当的一项是：</p>","options":[{"label":"A","content":"一步登天"},{"label":"B","content":"后来居上"},{"label":"C","content":"反客为主"},{"label":"D","content":"登堂入室"}],"answer":"D","explanation":"“一步登天”比喻一下子就达到很高的境界或程度，有时也用来比喻人突然得志，爬上高位。这里用其来形容“菇娘”的受欢迎程度，语义过重，排除A；“后来居上”原指资格浅的新人反居资格老的旧臣之上，有讽刺用人不当之意，后用来称赞后来的胜过先前的。句中并未拿“菇娘”与别的水果进行对比，排除B；“反客为主”指客人反过来成为主人，比喻变被动为主动。其词义不符合语境，排除C","no":211},{"id":"1718789646324","type":"single","material":"","stem":"<p>重视新生代农民工的社会诉求，（ &nbsp; ）地解决他们面临的问题，对社会的（ &nbsp; ）有着十分重要的意义。</p><p>填入括号部分最恰当的一项是：</p>","options":[{"label":"A","content":"因地制宜;全面提升"},{"label":"B","content":"因人而异;高速发展"},{"label":"C","content":"因时制宜;持续前行"},{"label":"D","content":"因势利导;长治久安"}],"answer":"D","explanation":"第一空，“因地制宜”指根据各地的具体情况，制定适宜的办法；“因时制宜”指根据不同时期的具体情况，采取适当的措施。二者用于解决农民工问题的语境均不恰当，排除A、C。第二空，农民工诉求解决得好不好，农民工满不满意，会影响社会的稳定，与社会能否高速发展关系不大，排除B。因此选D。","no":212},{"id":"1718789646325","type":"single","material":"","stem":"我们这一辈人所享受到的现代生活，就像一座越来越豪华、先进、舒适的大厦。生活在这样一座大厦中，不能只是（）。每个人不管这一辈子有多长，也不管是能力大还是能力小，总要多多少少为这座大厦的发展和完善（），多多少少为这个世界留下点什么。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"坐享其成;添砖加瓦"},{"label":"B","content":"好逸恶劳;出谋划策"},{"label":"C","content":"得过且过;竭尽全力"},{"label":"D","content":"拈轻怕重;精益求精"}],"answer":"A","explanation":"第一空，由后文强调的“要为所享受到的现代生活多少付出点自己的力量”可知，此处所填词语应表达“不付出”的意思。“得过且过”形容胸无大志。“拈轻怕重”指做事挑拣轻松的，害怕繁重的。两词均不符合句意，排除C、D第二空，与“大厦”对应，“添砖加瓦”更为形象和准确。","no":213},{"id":"1718789646326","type":"single","material":"","stem":"晚明江南的富裕，提供了附庸风雅的环境与条件，使得饮茶风尚引发了名牌效应。先是苏州虎丘茶风行，然后有大方和尚以虎丘制茶法在徽州松萝山制茶，造就了明末（）的松萝茶。一旦成了名牌，人们追求时尚，（），商家就有了商机，争相仿制，价格也直线上升。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"如雷贯耳;一掷千金"},{"label":"B","content":"闻名遐迩;如影随形"},{"label":"C","content":"声名鹊起;趋之若鹜"},{"label":"D","content":"风靡一时;蜂拥而至"}],"answer":"C","explanation":"第一空，文段强调的是松萝茶名气大、受欢迎。“如雷贯耳”形容人的名声大，不能用来形容茶的名气，排除A<br>第二空，“如影随形”比喻两个事物关系密切，文段表达人们对于松萝茶的态度，而非二者的关系，排除B对比C、D两项，“蜂拥而至”形容很多人乱哄哄地朝一个地方聚拢，“至”侧重强调的是“地点”,而文段强调的是“追求名牌、时尚”,与“地点”无关，排除D“趋之若鹜”比喻许多人争着去追逐某些事物，“趋”对应文段中“追求”,更加契合文意。","no":214},{"id":"1718789646327","type":"single","material":"","stem":"“慢”以从容恬淡之姿重出江湖。尽管讲慢生活的书（）地巡回宣传签售，尽管人们点击浏览着说慢的文字，汽车照样抢道，行人照样闯红灯，还是一个紧张拥挤恨不得什么都要赶上趟的节奏。在大干快上、只争朝夕的社会文化氛围的（）中，人们已渐次固化却甚少自知。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"马不停蹄;潜移默化"},{"label":"B","content":"争先恐后;耳濡目染"},{"label":"C","content":"层出不穷;日积月累"},{"label":"D","content":"络绎不绝;推波助澜"}],"answer":"A","explanation":"第一空，填入词语修饰“巡回宣传签售”。“马不停蹄”侧重忙碌，“争先恐后”侧重积极，“层出不穷”侧重多，“络绎不绝”侧重车马人多。此处描述书籍巡回宣传签售活动安排得密集，应选“马不停蹄”,排除B、C、D第二空，由“人们已渐次固化却甚少自知”可知，句中强调的是求快的社会文化氛围对人的无形影响，“潜移默化”与此相符。","no":215},{"id":"1718789646328","type":"single","material":"","stem":"<p>美国耶鲁大学一项持续12年的研究表明：由父母同时带大的孩子智商高，他们在学校里的成绩往往更好，将来走向社会也更容易成功。尽管很多男性已经领悟到父教的（ &nbsp; ），但现实生活中父教的缺位并不鲜见。中国家庭分工普遍注重“男主外，女主内”，投入到孩子身上的时间自然就会减少；有些男性存在浓厚的“大男子主义”情结，认为父教是“（ &nbsp; ）”，就算有时间，也不愿陪伴孩子；还有的父亲尚未认识到父教的必要性和重要性。</p><p>填入括号部分最恰当的一项是：</p>","options":[{"label":"A","content":"大有裨益;家长里短"},{"label":"B","content":"至关重要;大材小用"},{"label":"C","content":"大有可为;小题大做"},{"label":"D","content":"不可或缺;雕虫小技"}],"answer":"D","explanation":"本题可由第一空直接得出答案。由“但”可知，第一空所填词语应与“现实生活中父教的缺位并不鲜见”构成反义对应关系，表明父教在家庭教育中不可缺少。四个选项中与此最相符的是“不可或缺”。第二空填入“雕虫小技”表达有些男性对“父教”的忽视和不以为然的态度亦恰当。","no":216},{"id":"1718789646329","type":"single","material":"","stem":"城市人口过度聚集，对土地、水、空气等资源的需求与消耗（），而且由于使用不当，浪费严重，使得城市资源（），越来越短缺，结果是房地产价格不断上涨，水资源和食物供应不足，清洁空气稀缺。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"与日俱增;供不应求"},{"label":"B","content":"有增无减;山穷水尽"},{"label":"C","content":"旷日持久;左支右绌"},{"label":"D","content":"日甚一日;危在旦夕"}],"answer":"A","explanation":"第一空，填入词语应表达“需求与消耗”的量越来越多。“旷日持久”指多费时日，拖得很久；“日甚一日”形容事物发展的程度越来越深或日渐严重。二者均不能用来修饰数量的增多，排除C、D第二空，“山穷水尽”语义程度过重，与“短缺”的语境不符，排除B","no":217},{"id":"1718789646330","type":"single","material":"","stem":"<p>在娱乐方式多元化的今天，“（ &nbsp; ）”是不少人（特别是中青年群体）对待戏曲的态度。这里面固然存在（ &nbsp; ）的偏见、难以静下心来欣赏戏曲之美等因素，却也有另一个无法回避的原因：一些戏曲虽然与观众之间没有屏幕之隔，却用艺术化的表演，讲述着与观众距离较远的生活。</p><p>填入括号部分最恰当的一项是：</p>","options":[{"label":"A","content":"望洋兴叹;我行我素"},{"label":"B","content":"望而生畏;一叶障目"},{"label":"C","content":"敬而远之;先入为主"},{"label":"D","content":"知难而退;故步自封"}],"answer":"C","explanation":"第一空，由文段中的“娱乐方式多元化”和常识可知，人们现在对戏曲缺少关注。“望洋兴叹”指要做一件事而力量不够，感到无可奈何，不能用于形容人们对待戏曲的态度，排除A“知难而退”原指作战要见机而行，不要做实际上无法办到的事，后泛指知道事情困难就后退。不合文意，排除D第二空，“一叶障目”指看不到事物的全貌，不能修饰“偏见”,排除B“先入为主”符合人们对于戏曲的认识的特点。","no":218},{"id":"1718789646331","type":"single","material":"","stem":"在利益驱动下、赶稿压力下，网络写作往往（），恣情快意，顾不得考虑艺术品质和价值导向，让（）的所谓“文学”甚至文字垃圾充斥网络空间。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"运笔如飞;粗制滥造"},{"label":"B","content":"妙笔生花;泥沙俱下"},{"label":"C","content":"笔走龙蛇;良莠不齐"},{"label":"D","content":"笔下生风;鱼龙混杂"}],"answer":"A","explanation":"第一空，由“顾不得考虑艺术品质和价值导向”“文字垃圾充斥网络空间”可知，此处表达的是网络写作受利益驱动，且有赶稿压力，过于追求速度，牺牲质量的问题。“妙笔生花”形容文笔好，善于写作；“笔走龙蛇”形容书法笔势雄健活泼。二者均不含写作速度快的意思，且都为褒义词，填入不合语境，排除B、C<br>第二空，“鱼龙混杂”比喻好人和坏人混在一起，只能适用于人，不能描述“文学”,排除D“粗制滥造的所谓‘文学’”能够与“文字垃圾”构成递进关系，符合文意。","no":219},{"id":"1718789646332","type":"single","material":"","stem":"“多”与“少”，两者之间绝不仅仅是数量上的对立存在，而恰恰是“量变”与“质变”之间的一个（）。一味追求多，或一味追求少，都有可能把事物引向（）的另一面。因而，在看待“多”与“少”上，也要有辩证的观点。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"独立状态;意料之外"},{"label":"B","content":"中间过程;无法控制"},{"label":"C","content":"相对状态;难以接受"},{"label":"D","content":"演变过程;截然相反"}],"answer":"D","explanation":"第一空，由“不仅仅是……而恰恰是……”可知，此处所填词语应与“对立存在”构成反义对应关系，表示“多”与“少”并非对立关系，“独立状态”“相对状态”均表示“对立”,填入与句意不符，排除A、C<br>第二空，由“另一面”可知，此处表达的是一味追求多或少，都有可能会把事物引向与其相对的反面，“无法控制”不能体现“另一面”的特点，排除B“截然相反”填入恰当。","no":220},{"id":"1718789646333","type":"single","material":"","stem":"新媒体时代有新媒体时代的传播特点，从这些特点出发，对一些文章标题进行（），以适应网络舆论场的传播，这样的做法不可（）。但有些“标题党”为吸引眼球，故意制作带有误导性、煽动性的标题，扭曲了原意，误导了读者，滋生了不必要的价值冲突。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"精雕细琢;一语道破"},{"label":"B","content":"全盘否定;一成不变"},{"label":"C","content":"适度改造;一概否定"},{"label":"D","content":"改头换面;一笑了之"}],"answer":"C","explanation":"第一空，句意说的是根据新媒体时代的传播特点对一些文章标题进行改造是可以接受的，“精雕细琢”“全盘否定”不含改造的意思，排除A、B<br>第二空，由转折词“但”后的对“有些‘标题党’”的批判和全面否定可知，转折前表达的是，对于改造标题的做法不应该全部否定，“不可一概否定”符合句意，排除D","no":221},{"id":"1718789646334","type":"single","material":"","stem":"统计学家告诉我们，买一张彩票正好中大奖的概率（）。比如说，英国国家彩票的中奖概率大概就只有1400万分之一，相当于你连续投24次硬币全是正面朝上，远远低于被（）的陨石砸中的可能性。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"微不足道;祸从天降"},{"label":"B","content":"绝无仅有;不期而至"},{"label":"C","content":"不可多得;不期而遇"},{"label":"D","content":"微乎其微;从天而降"}],"answer":"D","explanation":"第一空，由“概率大概就只有1400万分之一”可知，此处意为中奖的概率非常小。“微不足道”指意义、价值等小得不值得一提。“绝无仅有”指只有一个，再没有别的；形容非常稀有，也用来形容人或物非常珍贵。“不可多得”形容非常稀少，很难得到(多指人才或稀有物品)。这三个词语均不能用来描述中奖的概率，排除A、B、C“微乎其微”形容非常小或非常少，填入符合句意。<br>第二空，用“从天而降”修饰陨石也恰当。","no":222},{"id":"1718789646335","type":"single","material":"","stem":"社会保障研究可能（），各国的制度特征可能（），各个学科对社会保障的解读可能（），但是社会保障力量的永恒话题说到底是要对不同国家、不同发展水平、不同文化传统背景下的平衡点位置做出解释。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"千变万化;千差万别;千头万绪"},{"label":"B","content":"千差万别;千头万绪;千变万化"},{"label":"C","content":"千变万化;千头万绪;千差万别"},{"label":"D","content":"千头万绪;千差万别;千变万化"}],"answer":"D","explanation":"“千变万化”形容变化极多，无穷无尽，侧重于变化多。“千头万绪”形容事物错综复杂，头绪很多，侧重于头绪多、复杂。“千差万别”形容差别很大或多种多样，侧重于差别大。<br>第一空，句意为社会保障研究很复杂，要研究的内容很多，选“千头万绪”恰当。验证D项后两空，描述“各国的制度特征”的差异性，“千差万别”填入合适；用“千变万化”描述各个学科对社会保障的不同解读也符合句意。","no":223},{"id":"1718789646336","type":"single","material":"","stem":"读书有两种情形，一种是看大意（）地看故事消磨时间，一种是细细品味，去（）寻找文章的构思，寻找文外的寓意。这就是读书的两种不同的方式和目的。不过，不管是哪一种读书方式都是一种知识的积累。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"走马观花;字斟句酌"},{"label":"B","content":"囫囵吞枣;字里行间"},{"label":"C","content":"一目十行;全神贯注"},{"label":"D","content":"漫不经心;片言只语"}],"answer":"B","explanation":"第一空，与“看大意”相对，此处应表达不关注细节，粗略看书的情形。“漫不经心”指随随便便，不放在心上，强调的是不用心，填入不合语境，排除D<br>第二空，“全神贯注”形容全副精神高度集中，与“细细品味”强调的着眼于细节的语境不相符，排除C“字斟句酌”形容说话或写作的态度慎重，适用对象为作者或说话者，此处对象为“读者”,填入不恰当，排除A","no":224},{"id":"1718789646337","type":"single","material":"","stem":"6世纪时，君士坦丁堡人口已逾百万，这在当时的欧洲，无城市可以（），欧亚的货物在此云集交易，这座“沟通东方与西方的黄金桥梁”是个巨大的贸易市场，（），中古时期，君士坦丁堡一直保持着首富地位直至13世纪。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"相提并论;琳琅满目"},{"label":"B","content":"与之比肩;琳琅满目"},{"label":"C","content":"相提并论;无奇不有"},{"label":"D","content":"与之比肩;无奇不有"}],"answer":"D","explanation":"第一空，此处句意为在当时，君士坦丁堡人口很多，没有城市能够与它相比。分析选项，“相提并论”的规范用法为“与……相提并论”,填入则导致语法错误，排除A、C“与之比肩”意为与它居同等地位。填入符合句意。<br>第二空，由“欧亚的货物在此云集交易……是个巨大的贸易市场”可知，横线处应填入形容东西多的词语。“琳琅满目”形容美好的事物很多；“无奇不有”指什么稀奇的事物都有。此处是指东西很多，各种东西都有，并未突出“美好”之意，排除B","no":225},{"id":"1718789646338","type":"single","material":"","stem":"华尔街股市（）。2000年3月以来，“牛”市格局长达10年之久的华尔街股市（），一路下滑。10月18日，一股强劲的寒流吹袭全球股市。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"惊弓之鸟;风云变幻"},{"label":"B","content":"杯弓蛇影;闻风而动"},{"label":"C","content":"草木皆兵;千变万化"},{"label":"D","content":"风声鹤唳;风云突变"}],"answer":"D","explanation":"第一空，分析可知，横线处所填词语应做谓语。“惊弓之鸟”是名词，不可以做谓语，排除A第二空，横线前说华尔街股市很长一段时间是“牛”市，横线后陈述的是“一路下滑”,前后语义相反，故所填词语应体现出转折的意思。“闻风而动”指听到消息就立刻行动，形容行动迅速；“千变万化”形容变化非常多，没有穷尽。两词都不具有转折意思，排除B、C“风云突变”比喻局势突然发生了巨大变化。其用来表示股市原来很好，后来下滑的形势恰当。","no":226},{"id":"1718789646339","type":"single","material":"","stem":"新，还往往伴随着快。新业态的成长有时快到（），机会宝贵到稍纵即逝，好像逼着经营者不得不“多干快上”。但从另外一个角度看，新业态往往又更敏感、更脆弱，不确定性更大，更加容不得（）“蒙眼狂奔”。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"一日千里;急功近利"},{"label":"B","content":"突飞猛进;好大喜功"},{"label":"C","content":"日新月异;浮光掠影"},{"label":"D","content":"应接不暇;好高骛远"}],"answer":"A","explanation":"第一空，由“有时快到”“机会宝贵到稍纵即逝”可知，空缺处所填词语应形象地描述“快”的程度。“一日千里”形容发展极其迅速，进步非常快。“突飞猛进”形容发展特别迅速。二者皆有“快”的含义，符合文意。“日新月异”形容进步、发展很快，新事物、新气象不断出现。它更侧重指变化大，填入不恰当，排除C“应接不暇”形容来人或事情太多，忙不过来，与文意不符，排除D<br>第二空，由“但”“蒙眼狂奔”等词可知，新业态的发展速度又不能过快。A项，“急功近利”指急于求成，贪图眼前功利。B项，“好大喜功”形容浮夸，不切实际的行为。文段中强调的是新业态的发展不能太快，过于追求成功，因此“急功近利”更符合文意，排除B","no":227},{"id":"1718789646340","type":"single","material":"","stem":"迟迟没有落地的补贴细则，让有意投资光伏发电站的企业们对光伏发电站的大蛋糕（）。上周，据某研究人员透露，对光伏发电站的补贴已经纳入财政预算，将“缺多少补多少”，但大部分企业对此却依然（）。在补贴不到位的情况下，企业还将面临垫资的风险，因此就整个光伏发电站市场而言，资金实力雄厚的大企业占据主导地位是（）的。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"望洋兴叹;举棋不定;显而易见"},{"label":"B","content":"望而生畏;犹豫不决;有目共睹"},{"label":"C","content":"望而却步;将信将疑;不言而喻"},{"label":"D","content":"望尘莫及;优柔寡断;不证自明"}],"answer":"C","explanation":"第一空，“望洋兴叹”比喻做事时因力不胜任或没有条件而感到无可奈何，“望尘莫及”比喻远远落在后面。句意为企业们因为政策没有落地而不敢投资，“望洋兴叹”“望尘莫及”不合句意，排除A、D<br>第二空，“大部分企业对此却依然……”中的“此”指的是“某研究人员透露”的政策消息，对消息只能是“将信将疑”,不能“犹豫不决”,排除B<br>验证第三空，“不言而喻”指不用说就能明白，填入符合句意。","no":228},{"id":"1718789646341","type":"single","material":"","stem":"直到3月中旬，长白山远望还是一片白雪皑皑。春天的脚步出了关外，到长白山脚下时，就有点（）了。其实，立春以后没几天，长白山区的积雪就开始悄悄融化了，别看山里依旧寒风刺骨，但这与严冬腊月已经大不一样，凛冽中还夹杂着一丝潮湿、（）的暖意。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"外强中干;乍暖还寒"},{"label":"B","content":"入不敷出;犹抱琵琶"},{"label":"C","content":"优柔寡断;东躲西藏"},{"label":"D","content":"踟蹰不前;若隐若现"}],"answer":"D","explanation":"第一空，“外强中干”形容外表好像很强大，实际上很空虚；“入不敷出”指收入不够开支；“优柔寡断”指做事犹豫，缺乏决断；“踟蹰不前”指迟疑不决，不敢前进。文段说的是春天到关外放慢了脚步，“外强中干”“入不敷出”不能形容脚步放缓，排除A、B<br>第二空，分析文段可知，所填词语应能形容严冬中夹杂着一丝丝的暖意。“东躲西藏”指到处躲避藏匿；“若隐若现”指隐隐约约，看不清楚。“若隐若现”恰能体现文段中“乍暖还寒”的情景。","no":229},{"id":"1718789646342","type":"single","material":"","stem":"历史反复昭示我们，向海而兴，背海而衰，是一条（）的铁律。中华民族要实现伟大复兴，必须（）地走向海洋、经略海洋，坚定不移地走以海富国、以海强国的和平发展之路。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"亘古不变;义无反顾"},{"label":"B","content":"一成不变;勇往直前"},{"label":"C","content":"原封不动;理直气壮"},{"label":"D","content":"颠扑不破;昂首阔步"}],"answer":"A","explanation":"第一空，句意为“向海而兴，背海而衰”是一条不变的发展规律，“一成不变”指守旧不变或固守陈法。含贬义，与句子感情色彩不符，排除B“原封不动”指保持原来的样子，不改变。与“铁律”不搭配，排除C<br>第二空，对应“必须”“坚定不移”,选语气较重的“义无反顾”比“昂首阔步”更恰当。","no":230},{"id":"1718789646343","type":"single","material":"","stem":"制定一项公共政策时就算再（）、未雨绸缪，也不能无视广大基层民众的心声，无视“公平”二字，否则只能成为（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"管中窥豹;众叛亲离"},{"label":"B","content":"居安思危;无的放矢"},{"label":"C","content":"高谈宏论;千夫所指"},{"label":"D","content":"高瞻远瞩;众矢之的"}],"answer":"D","explanation":"第一空，顿号提示横线处词语应与“未雨绸缪”构成并列关系对应，为褒义词。“管中窥豹”指从竹筒小管中看豹，所见的只是豹身上的一块斑纹，比喻见识狭小，看不到全面；“高谈宏论”指高深空洞、不切实际的鸿篇大论。两词均为贬义，排除<br>A、C“居安思危”指处在安定的环境而想到可能会出现的危难；“高瞻远瞩”形容眼光远大。二者填入均符合题意。<br>第二空所填词语是“成为”的宾语，应为名词。“无的放矢”比喻做事说话没有明确目的，为动词；“众矢之的”比喻大家攻击的对象，为名词。“众矢之的”填入恰当。","no":231},{"id":"1718789646344","type":"single","material":"","stem":"诗所具有的诸般品格中，十分重要的一条，便是对生活的（）的打量。诗人的目光仿佛具有（）的本领，生活中许多琐碎、平淡甚至枯燥的事物，经过它的抚摸，便产生了丰富的意味。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"别具一格;明察秋毫"},{"label":"B","content":"独树一帜;力透纸背"},{"label":"C","content":"别具匠心;点石成金"},{"label":"D","content":"别开生面;目光如炬"}],"answer":"C","explanation":"第二空，文段强调的是诗人的目光能使“琐碎、平淡甚至枯燥的事物”产生丰富的意味。“明察秋毫”形容为人非常精明，任何小问题都看得很清楚。“力透纸背”形容书法刚劲有力，也形容诗文深刻有力。“点石成金”比喻把不好的或平凡的事物改变成很好的事物。“目光如炬”形容见识远大。选项中能体现诗人这种化腐朽为神奇的特性的只有C项的“点石成金”。<br>第一空，“别具匠心”填入符合文意，且能与“打量”搭配。","no":232},{"id":"1718789646345","type":"single","material":"","stem":"回顾过去五年，诸多矛盾叠加，各种风险挑战（），国内外很多情况是改革开放以来没有碰到过的，我国改革发展成就实属（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"扑面而来;翻天覆地"},{"label":"B","content":"层出不穷;有目共睹"},{"label":"C","content":"接踵而至;来之不易"},{"label":"D","content":"纷至沓来;前所未有"}],"answer":"C","explanation":"第一空，句中表达的是各种风险挑战很多，应接不暇。四个词语填入都可表达此意，较难辨析，可从第二空入手。<br>第二空，由“诸多矛盾叠加”“各种风险挑战”“国内外很多情况是改革开放以来没有碰到过的”可知，横线处所填词语应表达中国改革难度大，改革开放发展能取得现在的成就很不容易。C项“来之不易”指来得很不容易，符合语境。“翻天覆地”形容变化巨大而彻底；“有目共睹”指所有的人都看得见，形容极其明显；“前所未有”指以前从来没有过。A、B、D三项均未体现“难度大”之意，排除。","no":233},{"id":"1718789646346","type":"single","material":"","stem":"一个大党诞生于一条小船。从此，中国共产党引领革命的航船，（），开天辟地，使中国革命的面貌（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"披荆斩棘;改天换地"},{"label":"B","content":"乘风破浪;改头换面"},{"label":"C","content":"踏浪而来;日新月异"},{"label":"D","content":"劈波斩浪;焕然一新"}],"answer":"D","explanation":"分析句意可知，第一空所填词语应具有排除困难、奋勇前进之意。“乘风破浪”比喻志向远大，不畏艰险，奋勇向前。“劈波斩浪”指船只行进时冲开波浪，比喻排除前进中的困难和障碍。B、D两项均符合语境。“踏浪而来”指游水技术高超，与句意不符，排除C;对应“小船”特点，所填的词语应与海洋有关。“披荆斩棘”指劈开丛生带刺的植物，与语境不符，排除A<br>第二空，由文意知，中国共产党使中国革命面貌有了更好的改变。“改头换面”比喻只改形式，不改内容(含贬义),与语境不符，排除B;“焕然一新”指改变旧面貌，出现崭新的气象。“焕然一新”符合中国革命面貌发生巨大变化的语境。","no":234},{"id":"1718789646347","type":"single","material":"","stem":"我们常说“科学是开放的”，不是“封闭的”，科学的开放性意味着它不是永恒真理，可能出错。可是现实生活中，有些人在科学研究中对科学错误（），一旦自己的科研成果遇到质疑就立刻将其（）。这看似暂时化解了危机，其实禁锢了自身的发展。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"讳莫如深;束之高阁"},{"label":"B","content":"噤若寒蝉;置之脑后"},{"label":"C","content":"避而不谈;改头换面"},{"label":"D","content":"谈虎色变;弃如敝屣"}],"answer":"A","explanation":"第一空，文段意在说明的是有些人对科学错误不能正确面对、一味回避的态度。A项“讳莫如深”指紧紧隐瞒；C项“避而不谈”形容有意避开话题不谈。二者均可用来形容“有些人”回避的态度。B项“噤若寒蝉”指像寒秋的蝉不再鸣叫，形容不敢作声；D项“谈虎色变”泛指一提到可怕的事物连脸色都变了。二者语义程度过重，排除B、D<br>第二空，“束之高阁”指扔在一边，不去用它或管它；“改头换面”比喻只改形式，不变内容。“改头换面”并没有“暂时化解了危机”的意思，也与文段中有些人对科学错误的回避态度不相符，排除C","no":235},{"id":"1718789646348","type":"single","material":"","stem":"近年来，随着金融改革开放步伐加快，多层次资本市场建设稳步推进，金融市场创新日趋活跃，与金融密切相关的金融信息服务出现（）的发展，但金融信息质量（），市场秩序有待健全规范。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"突飞猛进;参差不齐"},{"label":"B","content":"日新月异;良莠不齐"},{"label":"C","content":"江河日下;泥沙俱下"},{"label":"D","content":"与日俱增;鱼目混珠"}],"answer":"A","explanation":"第一空，由“步伐加快”“稳步推进”“日趋活跃”等词语可知，此处表达的是金融信息服务有了迅猛发展。“江河日下”比喻情况一天天变坏，与文意相悖，首先排除C“与日俱增”指随着时间的推移而不断增长，其暗含的渐进式增长的意思与迅猛增长的语境不相符，排除D“突飞猛进”形容事业、学问等进展非常迅速，侧重的是速度；“日新月异”形容发展变化很快，新事物、新气象不断涌现，侧重变化快。文段强调的是发展的速度快，“突飞猛进”填入符合题意，且能与转折后表达的超常增长带来的一系列问题构成呼应，排除B<br>代入验证第二空，题意为信息质量差别大，存在问题。“参差不齐”形容不一致，有差别，符合题意。","no":236},{"id":"1718789646349","type":"single","material":"","stem":"当下，建立网络安全防御体系尤为重要。“每一台计算机都在贯彻人类的意志，互联网是人类社会在数字空间的投影。”因此，毫无疑问，网络世界也需要技术伦理。但是面对（）的黑客，伦理层面只能是（）。因此，唯有主动出击，排查风险，防患于未然，才是真正的解决之道。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"不怀好意;缘木求鱼"},{"label":"B","content":"别有用心;对牛弹琴"},{"label":"C","content":"心术不正;鸡同鸭讲"},{"label":"D","content":"居心叵测;与虎谋皮"}],"answer":"D","explanation":"第一空，四个词语填入都符合句意，较难排除，可从第二空入手。<br>第二空，由“唯有主动出击，排查风险，防患于未然，才是真正的解决之道”可知，伦理层面的约束对打击黑客作用不大。“缘木求鱼”比喻方向、方法不对，一定达不到目的。根据“网络世界也需要技术伦理”可知，依靠伦理的方法并非完全错误，只是效果有限，排除A“对牛弹琴”用来讽刺说话的人不看对象，瞎说一气；“鸡同鸭讲”形容两个人无共同语言，无法沟通。二者均无法体现从伦理层面着手，效果不佳之意，排除B、C“与虎谋皮”比喻所商量的事与对方(多指坏人)有利害冲突，绝对办不到。句中说的是技术伦理必然会触及黑客利益，所以从伦理层面约束黑客是不会成功的，“与虎谋皮”符合文意。","no":237},{"id":"1718789646350","type":"single","material":"","stem":"2012年“蛟龙”在这里进行7000米海试第一潜时，受热带风暴“古超”影响曾一再推迟；2016年，超强台风“尼伯特”不期而至，“蛟龙”号只得取消下潜、（）。这一片大西洋海域，其上空形成的台风比世界上其他任何地方都多。好在今天（），天气晴朗。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"缘悭一面;风和日丽"},{"label":"B","content":"空手而归;月朗星稀"},{"label":"C","content":"打道回府;天公作美"},{"label":"D","content":"无功而返;万里无云"}],"answer":"C","explanation":"第一空，“缘悭一面”指想见上一面，但总是差那么一点缘分，不符合句意，排除A“无功而返”指没有任何成效而回来，与“蛟龙”号并未下潜的表述相矛盾，排除D<br>第二空，“月朗星稀”描述的是夜晚环境，与“蛟龙”号在白天下潜的情况不符，排除B","no":238},{"id":"1718789646351","type":"single","material":"","stem":"一般我们总认为，文学重视形象思维，而科学需要理性逻辑。其实，科学也可以很文艺，（），充满艺术的想象力。这两者看似关涉领域不同，其实只要有创意，便能（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"妙趣横生;水乳交融"},{"label":"B","content":"洞若观火;若合符节"},{"label":"C","content":"有声有色;相辅相成"},{"label":"D","content":"入木三分;相映成趣"}],"answer":"A","explanation":"第一空，由“科学也可以很文艺……充满艺术的想象力”可知，科学不仅严谨理性，也可以生动有趣。“妙趣横生”指洋溢着美妙意趣；“有声有色”形容表现得十分生动。A、C两项符合文意。“洞若观火”形容看得清楚明白；“入木三分”形容议论、见解深刻。二者均无法体现“科学”文艺的一面，排除B、D<br>第二空，“水乳交融”形容关系非常融洽或结合十分紧密；“相辅相成”指互相补充，互相配合。由“看似关涉领域不同，其实……”可知，此处强调的是科学和文学虽属不同领域，但只要有创意，就能融为一体，用“水乳交融”更恰当，排除C","no":239},{"id":"1718789646352","type":"single","material":"","stem":"“山一程，水一程，身向榆关那畔行，夜深千帐灯。”文化节目《经典咏流传》的舞台上，当纳兰性德的《长相思·山一程》被棋手柯洁用深情的歌声唱出时，这句（）的词句还是给予我惊艳和陌生。那份数百年前的故园情思、羁旅感慨因悠扬的旋律被再度激活，令人（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"目知眼见;心旷神怡"},{"label":"B","content":"驾轻就熟;焕然一新"},{"label":"C","content":"耳熟能详;耳目一新"},{"label":"D","content":"耳闻能诵;赏心悦目"}],"answer":"C","explanation":"第一空，由后文“词句还是给予我惊艳和陌生”可知，所填词语应表示的是这句词句很常见、不陌生之意。“驾轻就熟”比喻对事情熟悉，办起来容易。“耳闻能诵”形容记忆力强。两者均不能用来形容“词句”,排除B、D“目知眼见”形容熟悉了解。“耳熟能详”意为听的次数多了，熟悉得能详尽地说出来。二者填入均符合句意。<br>第二空，“心旷神怡”指心境开阔，精神愉快。“耳目一新”形容感觉与以往大不相同，使人振奋。此处与“再度激活”对应，“耳目一新”更恰当，排除A","no":240},{"id":"1718789646353","type":"single","material":"","stem":"文化自信不是天上掉下来的，也不是仅仅在嘴上说说的，更不是虚无缥缈的“（）”。文化自信来自对民族历史的深刻了解，对国家现实的全面把握，对发展战略的正确设计，对前途目标的精准判断。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"画饼充饥"},{"label":"B","content":"纸上谈兵"},{"label":"C","content":"空中楼阁"},{"label":"D","content":"水中捞月"}],"answer":"C","explanation":"“画饼充饥”比喻用空想来安慰自己；“纸上谈兵”比喻不联系实际情况，空发议论；“空中楼阁”比喻虚幻的事物或脱离实际的理论、计划等；“水中捞月”比喻徒劳而无功。四个词语中能用“虚无缥缈”修饰的只有“空中楼阁”。","no":241},{"id":"1718789646354","type":"single","material":"","stem":"传承红色基因，重要性不言而喻；但如何传承，同样不容忽视。怎样深入挖掘红色传统，生动展示红色基因，让普通人也能感受到力量，让红色基因（），这恐怕是一个不可回避的重大课题。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"代代相传"},{"label":"B","content":"发扬光大"},{"label":"C","content":"深入人心"},{"label":"D","content":"根深蒂固"}],"answer":"A","explanation":"文意为让红色基因传承延续。“代代相传”指一代接一代地相继传下去，填入符合文意。“发扬光大”指事业、传统等在已有的基础上进一步发展和提高；“深入人心”指思想、理论、学说、主张等被大家所深刻理解并拥护。二者均与“基因”搭配不当，排除B、C“根深蒂固”比喻根基深厚牢固，不可动摇，不含传承的意思，排除D","no":242},{"id":"1718789646355","type":"single","material":"","stem":"在上海工作和生活的外国人，已不满足仅仅看灯会、逛庙会，从（）到“身临其境”，他们中越来越多人开始与中国朋友一起聚会，体会春节时那浓浓的年味。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"浅尝辄止"},{"label":"B","content":"走马观花"},{"label":"C","content":"入境问俗"},{"label":"D","content":"浮光掠影"}],"answer":"D","explanation":"“从‘’到‘身临其境’”暗含了外国人感受中国年文化的两个层次。其中“身临其境”对应于后文的“与中国朋友一起聚会，体会春节时那浓浓的年味”,故空缺处所填词语应与前文的“看灯会、逛庙会”构成对应，表达外国人对中国年文化的理解比较肤浅，仅停留在灯会、庙会等文化符号上。“浅尝辄止”指对知识不做深入研究，“入境问俗”指进入别国前问清风俗，据此排除A、C“走马观花”偏重观察不细致、不深入，“浮光掠影”偏重印象不深。显然，“浮光掠影”用来表达外国人对中国文化的浅层次认知更恰当。","no":243},{"id":"1718789646356","type":"single","material":"","stem":"一本好的社会科学著作，不仅应该做到于无声处听惊雷，在琐屑的生活细节中（），而且应该让读者在阅读的过程中，情不自禁地借助作者的方法去检验生活和理解社会。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"见微知著"},{"label":"B","content":"管中窥豹"},{"label":"C","content":"一叶知秋"},{"label":"D","content":"洞若观火"}],"answer":"A","explanation":"“见微知著”指见到事情的苗头，就能知道它的实质和发展趋势；“管中窥豹”比喻只看到事物的一部分；“一叶知秋”比喻发现一点预兆就知道事物将来的发展趋向；“洞若观火”形容对事物观察得清楚明白。“管中窥豹”“洞若观火”与“琐屑的生活细节”不能构成对应关系，排除B、D“一叶知秋”侧重于由局部推知未来。描述“好的社会科学著作”,用“见微知著”更恰当，且能与“琐屑的生活细节”相对应，排除C","no":244},{"id":"1718789646357","type":"single","material":"","stem":"一切意义都寓于过程。然而，现代文明是（）的文明，只求结果，藐视过程。人们手捧旅游图，肩挎照相机，（），专找图上标明的去处，在某某峰、某某亭“咔嚓”几下，留下“到此一游”的证据，便心满意足地离去。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"缘木求鱼;走马观花"},{"label":"B","content":"急功近利;按图索骥"},{"label":"C","content":"浮光掠影;有的放矢"},{"label":"D","content":"急于求成;独辟蹊径"}],"answer":"B","explanation":"第一空，由“只求结果，藐视过程”可知，填入词语应有追求结果之意。“缘木求鱼”比喻方向或办法不对头，不可能达到目的。“浮光掠影”比喻观察不细致或印象很不深刻。两词都是说方法的，排除A、C<br>第二空，“按图索骥”比喻墨守成规办事；也比喻按照线索去寻求。“独辟蹊径”比喻独创一种风格或新的方法。“按图索骥”与“专找图上标明的去处”的语境相吻合，排除D","no":245},{"id":"1718789646358","type":"single","material":"","stem":"网约车平台，理应承担管理和风险连带责任，并对造成的各类事故和损害优先承担赔付责任。这样才能让平台有从严管理的高度自觉，而不能以自己是第三方为借口（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"独善其身"},{"label":"B","content":"袖手旁观"},{"label":"C","content":"逃之夭夭"},{"label":"D","content":"置身事外"}],"answer":"D","explanation":"文意是网约车平台应该承担起管理和风险连带责任，而不能以自己是第三方为借口推脱责任。“逃之夭夭”指逃跑或溜走，只适用于人，而不能用于“平台”。且此处表达的是逃避责任，而非逃走，排除C“独善其身”原指独自修养身心，保持个人的节操；后指只顾自己，不管他人的个人主义处事哲学，与“兼济天下”相对。此处批判的是网约车平台逃避应尽的责任，而非未做到“兼济天下”,排除A“袖手旁观”“置身事外”都含有不参与、不帮助的意思。“袖手旁观”侧重“旁观”,有在旁边看笑话的意思；“置身事外”侧重“事外”,有撇清责任的意思。对应“以自己是第三方为借口”,此处更强调撇清责任，选“置身事外”更恰当。","no":246},{"id":"1718789646359","type":"single","material":"","stem":"对不同季节的雨，古人的态度（），于是才有春雨如恩诏、夏雨如赦书、秋雨如挽歌的说法。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"迥然不同"},{"label":"B","content":"毫无二致"},{"label":"C","content":"大相径庭"},{"label":"D","content":"模棱两可"}],"answer":"A","explanation":"由“春雨如恩诏、夏雨如赦书、秋雨如挽歌”可知，古人对不同季节的雨的态度差异很大。故所填词语应表示“不同”之意。“毫无二致”形容完全相同；“模棱两可”指态度或主张不明确。据词义可排除B、D“迥然不同”形容差别很大，很不相同；“大相径庭”比喻相差很远或矛盾很大。“迥然不同”比“大相径庭”程度更重，更能突出“恩诏”“挽歌”之间的差异程度，排除C","no":247},{"id":"1718789646360","type":"single","material":"","stem":"透过中石油的外表，我们看到的是中国经济上升期所伴随的资本躁动，以及非理性的市场繁荣。中石油“市值第一”的名号应该激起高度警觉和担忧，而不是（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"不孚众望"},{"label":"B","content":"额手称庆"},{"label":"C","content":"弹冠相庆"},{"label":"D","content":"欣喜若狂"}],"answer":"C","explanation":"由“应该……而不是……”可知，空缺处所填词语应与“警觉和担忧”所表达的悲观情绪构成反义关系对应，含有高兴、庆祝的意思。“不孚众望”指不能使大家信服，据词义排除A文段主要表达的是中石油“市值第一”的名号背后是“资本躁动”和“非理性的市场繁荣”,因此没必要为“市值第一”的名号得意，空缺处所填词语应含贬义。“额手称庆”常用于褒义，感情色彩与文段不符，排除B“弹冠相庆”指官场中一人当了官或升了官，同伙就互相庆贺将有官可做，强调“出名后得意的样子”,含贬义；“欣喜若狂”形容高兴到了极点，语义程度较重，且没有明显的贬义色彩。二者相比，“弹冠相庆”填入更恰当。","no":248},{"id":"1718789646361","type":"single","material":"","stem":"面对时下大数据时代奔涌的多元、多源、异构的海量数据，无论是被誉为“孕育了现代科学”的统计科学，还是应大科学之运而生、正如日中天的数据科学，也都只能（）。今日之大数据，明日之大信息，扭转乾坤者，还属革新后的统计科学与数据科学。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"望其项背"},{"label":"B","content":"望洋兴叹"},{"label":"C","content":"可见一斑"},{"label":"D","content":"浅尝辄止"}],"answer":"B","explanation":"由句中的“无论是……还是……也都只能……”可知，句意为面对大数据时代的海量数据，统计科学和数据科学都感到力量不够。“望其项背”表示赶得上或比得上(多用于否定句式)。“望洋兴叹”比喻要做一件事，由于力量不够或缺乏条件而感到无可奈何。“可见一斑”比喻从一点推知全貌。“浅尝辄止”比喻不往深处研究，不深入钻研。结合词义可知，只有“望洋兴叹”填入符合句意。","no":249},{"id":"1718789646362","type":"single","material":"","stem":"物理学研究与艺术创作有异曲同工之妙，若是不能（），就只能千锤百炼，通过成年累月的辛苦工作来解开暗物质的谜团了。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"守株待兔"},{"label":"B","content":"一蹴而就"},{"label":"C","content":"妙手偶得"},{"label":"D","content":"灵机一动"}],"answer":"C","explanation":"文段把物理学研究与艺术创作相类比，由“不能……只能……”可知，空缺处所填词语应能描述艺术创作，且能与后文的“千锤百炼”“成年累月的辛苦工作”构成反义对应。“千锤百炼”比喻经历多次艰苦斗争的锻炼和考验；也指对文章和作品进行多次精心的修改。<br>A项“守株待兔”比喻不主动地努力，而存万一的侥幸心理，希望得到意外的收获；也比喻死守狭隘的经验，不知变通。<br>B项“一蹴而就”形容事情轻而易举，一下子就能完成。<br>C项“妙手偶得”指技术高超的人，偶然间得到的灵感或作品；也用来形容文学素养很深的人，出于灵感，即可偶然间得到妙语佳作。<br>D项“灵机一动”指事前没有准备，临时想出办法。<br>与“千锤百炼”表达的下苦功夫多次推敲的意思相对应，“妙手偶得”表达的依靠灵感一次获得成功的意思最符合句意。","no":250},{"id":"1718789646363","type":"single","material":"","stem":"近年来，我国公众参与环保的事件（），普通民众积极参与、献策建言，民间环保机构也频繁发声。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"层出不穷"},{"label":"B","content":"凤毛麟角"},{"label":"C","content":"不足为奇"},{"label":"D","content":"成千上万"}],"answer":"A","explanation":"空缺处所填词语应与后文的“积极参与”“频繁发声”构成对应，表达公众参与环保的事件多且连续不断。A项“层出不穷”指接连出现，没有穷尽，符合文意。<br>“凤毛麟角”比喻珍贵而稀少的人或物，强调少，填入与句意相悖，排除B“不足为奇”强调没有什么好奇怪的，与句子强调多的语境不符，排除C“成千上万”形容数量很多，没有体现连续性，且与“献策建言”“频繁发声”表达的书面语境不符，排除D","no":251},{"id":"1718789646364","type":"single","material":"","stem":"要做出正确的经济预测，并不容易。某些眼光独到的经济学家可以凭先见之明赢尽掌声；反之，如果先前做出的大胆假设落空，往往会变成（）的笑话。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"荒腔走板"},{"label":"B","content":"颜面尽失"},{"label":"C","content":"人尽皆知"},{"label":"D","content":"哗众取宠"}],"answer":"A","explanation":"句意说的是如果先前的假设落空，就会变成预测不准的笑话。“颜面尽失”侧重丢失面子，“人尽皆知”侧重事情流传广泛。二者不符合文意，排除B、C“哗众取宠”指用言论行动迎合众人，以博取众人的喜爱。经济学家并非故意预测错误来吸引关注，排除D“荒腔走板”意指演员唱曲音调不准、不和板眼，现多用来比喻说话离题或举动超出适当尺度，填入符合“大胆假设落空”的文意。","no":252},{"id":"1718789646365","type":"single","material":"","stem":"生命在于运动，运动能塑造我们强健的身体，增强抵抗疾病的能力。当然，它对大脑也是有益的。但事实上，运动应该（），否则会使人反应迟钝。长时间大强度运动会使脑组织兴奋性降低，会使能源物质ATP（腺苷三磷酸）耗竭，对大脑机能造成损害。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"因人而异"},{"label":"B","content":"张弛有道"},{"label":"C","content":"适可而止"},{"label":"D","content":"循序渐进"}],"answer":"C","explanation":"由“长时间大强度运动会……对大脑机能造成损害”可知，文段意为运动虽对大脑有益，但不应过度。长时间大强度的运动对大脑有害无益。因此空缺处所填词语应表达“适度”之意。C项“适可而止”指到了适当程度就停下，填入空缺处指运动要适度，与后文对应恰当，正确。<br>A项“因人而异”指因人的不同而有所差异，文段没有涉及对不同人运动情况的描述，排除。B项“张弛有道”比喻工作的紧松和生活的劳逸要适当调节，有节奏地进行，强调的是劳逸结合，而非适度，与文意不符，排除。D项“循序渐进”指(学习、工作)按照一定的步骤逐渐深入或提高，无法与后文对应，排除。","no":253},{"id":"1718789646366","type":"single","material":"","stem":"改革开放以来，我国文艺创作迎来了新的春天，产生了大量（）的优秀作品。同时，也不能否认，在文艺创作方面也存在着有数量缺质量、有“高原”缺“高峰”的现象，存在着抄袭模仿、（）的问题，精品之所以“精”，就在于其思想精深、艺术精湛、制作精良。文艺工作者要（），随着时代生活创新，以自己的艺术个性进行创新。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"脍炙人口;千篇一律;志存高远"},{"label":"B","content":"家喻户晓;泥沙俱下;标新立异"},{"label":"C","content":"良莠不齐;照猫画虎;精耕细作"},{"label":"D","content":"喜闻乐见;因循守旧;与时俱进"}],"answer":"A","explanation":"第一空，“良莠不齐”指好人坏人都有，混杂在一起，与“优秀作品”搭配不当，排除C<br>第二空，由顿号可知，此处所填词语应与“抄袭模仿”构成并列关系，意思相近。“泥沙俱下”比喻好坏不同的人或事物混杂在一起，“因循守旧”指不求变革沿袭老一套。二者不符合语境，排除B、D<br>把A项代入第三空验证，“志存高远”符合文艺工作者随着时代生活创新的语境。","no":254},{"id":"1718789646367","type":"single","material":"","stem":"对于人工智能来说，这种学习的广度实在是（），凡是人类社会的东西和事物，都是其学习的对象。但对它未学习过的东西，人工智能就会（），而且不知道逻辑推理，犯错误和发生事故也在所难免。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"巨细无遗;倍感沮丧"},{"label":"B","content":"不着边际;神经错乱"},{"label":"C","content":"广袤无边;不知所措"},{"label":"D","content":"浩如烟海;颠三倒四"}],"answer":"C","explanation":"第一空，“巨细无遗”指大小都没有遗漏；“不着边际”指挨不上边，形容言论空泛，不切实际，离题太远。二者都不能用来形容学习的广度，排除A、B<br>第二空，“不知所措”指不知道怎么办才好，形容处境为难或心神慌乱；“颠三倒四”<br>形容说话办事没有次序，没有条理。用于形容人工智能面对没有学过的东西时的表现，“不知所措”更恰当，排除D","no":255},{"id":"1718789646368","type":"single","material":"","stem":"中国的史学传统与古希腊（），在理路上却（）。希腊专业的史学著述仅限当代史范畴，或至多补缀少许的能为“理解之同情”所穿透的过往史实。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"双峰对峙;大异其趣"},{"label":"B","content":"隔江相望;剑走偏锋"},{"label":"C","content":"二水分流;剑走偏锋"},{"label":"D","content":"遥相对峙;大异其趣"}],"answer":"A","explanation":"第二空，文段是将古希腊史学与中国史学进行对比。“剑走偏锋”比喻不按常规、常理思维或行动；“大异其趣”指表现得大不相同、差异很大。“剑走偏锋”不含对比之义，填入语义不通，排除B、C<br>第一空，由转折词“却”可知，此处是表达中国与古希腊的史学传统地位相当。A项“双峰对峙”指两山相对耸立，不分高下；“遥相对峙”指距离很远，相对耸立。“遥相对峙”侧重距离远，体现不出中国与古希腊史学传统地位相当之意，排除D","no":256},{"id":"1718789646369","type":"single","material":"","stem":"面对共享单车炙手可热的投资风口，投资者、商家（），大肆在各大城市投放共享单车，不少城市都已（），居民生活都受到影响。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"一哄而上;捉襟见肘"},{"label":"B","content":"跃跃欲试;束手无策"},{"label":"C","content":"蜂拥而至;不堪重负"},{"label":"D","content":"争先恐后;应接不暇"}],"answer":"C","explanation":"第一空，A项“一哄而上”指没有经过认真准备和严密组织，一下子行动起来。C项“蜂拥而至”形容很多人乱哄哄地朝一个地方聚拢。D项“争先恐后”形容抢着向前、唯恐落后。这三项都可以形容投资者和商家纷纷涌入共享单车领域的情形。而“跃跃欲试”形容心里急切地想试试。由“大肆在各大城市投放共享单车”可知，投资者、商家已经付诸行动，而不仅是心情急切想要试试，排除B<br>第二空，句意为共享单车的大肆投放已经成为城市的负担，甚至影响到居民生活。“捉襟见肘”侧重顾此失彼；“应接不暇”形容人或事情太多，接待应付不过来。二者均体现不出共享单车泛滥给城市和居民生活带来的影响，排除A、D“不堪重负”指承受不了繁重的负荷，不能担当重任，填入符合文意。","no":257},{"id":"1718789646370","type":"single","material":"","stem":"市政市容委上半年就曾对全市报刊亭开展过整治，包括对破旧报亭进行维修、粉饰；重点治理亭外占道经营行为，拆除私自搭建的各类棚架等。若这类治理还止于“（）”的话，那动不动就把报亭拆除，只会是（），制造更多问题。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"纸上谈兵;适得其反"},{"label":"B","content":"公事公办;画蛇添足"},{"label":"C","content":"墨守成规;事倍功半"},{"label":"D","content":"就事论事;过犹不及"}],"answer":"D","explanation":"第一空，“纸上谈兵”比喻不联系实际情况，空发议论；“公事公办”指公事按公事的原则办，不讲私人情面；“墨守成规”指思想保守，守着老规矩不肯改变；“就事论事”指根据事情本身情况来评论是非得失。此处是拿上半年对报亭的治理与动不动拆报亭的做法进行对比，并不是批判之前的治理未落到实处，排除A<br>第二空所填词语应与“制造更多问题”对应，表达对动不动就拆报亭做法的不认同。“画蛇添足”强调多此一举，“事倍功半”强调效率低下。二者均不会制造更多问题，排除<br>B、C“过犹不及”指事情做得过头，就跟做得不够一样，都是不合适的，与“动不动”“制造更多问题”对应恰当。","no":258},{"id":"1718789646371","type":"single","material":"","stem":"以和为贵、（）的精神，贯穿中华民族发展的全部历史，渗透在社会生活的方方面面，使我们不同族群、不同地域的不同文化，不断相互吸取、相互融合，形成了（）、丰富多彩的中华文化。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"和睦相处;无与伦比"},{"label":"B","content":"谦顺礼让;不绝如缕"},{"label":"C","content":"和而不同;博大精深"},{"label":"D","content":"守望相助;兼收并蓄"}],"answer":"C","explanation":"第二空，“无与伦比”指事物非常完美，没有能够与它相比的同类的东西。此处没有强调中华文化的完美和独一无二之意，排除A“不绝如缕”用来形容局势危急或声音细微悠长，修饰“中华文化”不恰当，排除B<br>第一空，“和而不同”指和睦地相处，但不随便附和；“守望相助”指为了防御外来的侵害，邻近的村落协同看守瞭望，遇警互相帮助。与“以和为贵”并列，“和而不同”更恰当。","no":259},{"id":"1718789646372","type":"single","material":"","stem":"不管在哪里，只要听到秦腔的乐曲响起，我都会顿足倾听。那秦腔曲牌的（）顿时就把我带进戏里的情节中去了。杨继业率八子血战沙场、（）的悲壮，王宝钏苦守寒窑的辛酸都感染着我。不仅如此，我是被秦腔的艺术魅力所感染，它的唱腔，宽音大嗓，直起直落，给人一种（）、粗犷朴实之感，正如西北人那粗犷豪放、朴实憨厚的性格。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"荡气回肠;孤军奋战;舒柔缓和"},{"label":"B","content":"空灵缥缈;孤立无助;慷慨激昂"},{"label":"C","content":"婉转悠扬;孤立无援;高亢激越"},{"label":"D","content":"行云流水;孤立寡与;穿云裂石"}],"answer":"C","explanation":"第一空，“空灵缥缈”指纯净、灵活、虚幻，不可捉摸，用来形容声音时多用于女声或童音，与后文“宽音大嗓，直起直落”“粗犷豪放”不对应，排除B“行云流水”形容文章自然不受约束，就像飘浮着的云和流动着的水一样。其不能形容秦腔，排除D<br>第三空，“舒柔缓和”不符合题干末句对秦腔特点的描述，排除A","no":260},{"id":"1718789646373","type":"single","material":"","stem":"社会批评是促进社会进步的必要条件。如果一个社会批评的声音消失了，那么这个社会一定是封闭的、（）的；如果一个社会容许批评的声音，那么这个社会也一定是开放的、（）的。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"门可罗雀;与时俱进"},{"label":"B","content":"萎靡不振;异彩纷呈"},{"label":"C","content":"风雨如晦;生龙活虎"},{"label":"D","content":"暮气沉沉;生机盎然"}],"answer":"D","explanation":"由“;”可知，两句在形式上为并列关系。由“封闭”与“开放”的对比可知，空缺处两个词语也应构成反义对应。<br>A项，“门可罗雀”应与“门庭若市”对应，与“与时俱进”不能构成反义对应，排除。<br>B项，“萎靡不振”应与“神采飞扬”对应，与“异彩纷呈”也不能构成反义对应，排除。<br>C项，“风雨如晦”比喻局势动荡，社会黑暗。与之相对的应是“风和日丽”。“风雨如晦”与强调富有活力的“生龙活虎”不能构成反义对应，排除。<br>D项，“暮气沉沉”与“生机盎然”意思相对，填入符合题意。","no":261},{"id":"1718789646374","type":"single","material":"","stem":"汉语是一种能产性极强的语言，在网络语境催生下，大量新颖别致、有时代内涵的新词族（）。它们在类推机制下以共同的语素为基础，形成可不断扩充的庞大词汇家族。如：“微x”词族、“晒x”词族、“x奴”词族等。诸如此类的表达在当下的口语交流中（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"一鸣惊人;遍地开花"},{"label":"B","content":"脱颖而出;屡见不鲜"},{"label":"C","content":"横空出世;细大不捐"},{"label":"D","content":"异军突起;俯拾皆是"}],"answer":"D","explanation":"第一空，“一鸣惊人”比喻平时没有突出的表现，一下子就做出惊人的成绩。“脱颖而出”比喻本领全部显露出来。此处用来形容“新词族”这一新生事物，二者均不恰当，排除A、B<br>第二空，句意为此类的表达在当下的口语交流中很多或常见。“细大不捐”指小的大的都不抛弃，形容包罗一切，填入与句意不符，排除C","no":262},{"id":"1718789646375","type":"single","material":"","stem":"晚清官员最害怕的就是和洋人直接打交道。他们中的绝大部分人不懂外语，不明世界大势，不知国际公法，在和洋人打交道时未免（），进退失据。对于日渐增多的华洋纠纷，他们处理起来更是（），稍有不慎，就会招来严重的外交纷争。因此，他们便普遍形成了一种“畏洋如虎”的心态。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"如履薄冰;捉襟见肘"},{"label":"B","content":"瞻前顾后;手足无措"},{"label":"C","content":"妄自菲薄;眼花缭乱"},{"label":"D","content":"左支右绌;力不从心"}],"answer":"D","explanation":"第一空，分析可知，此处所填词语应与“进退失据”语义相近。“进退失据”指行事陷入困境，或临事张皇失措，用在此处表明晚清官员与洋人打交道时心里没底，应付不过来。“如履薄冰”形容谨慎戒惧。“妄自菲薄”指过分地看轻自己。二者填入均与句意不符，排除A、C“瞻前顾后”形容顾虑太多，犹豫不决。“左支右绌”指力量不足，应付了这一面，那一方面又有了问题。二者均符合语境。<br>第二空，前文“他们中的绝大部分人不懂外语，不明世界大势，不懂国际公法”是晚清官员“畏洋如虎”的主要原因，所以该空应该体现因“能力不够”而造成“想做却做不了”的局面。“手足无措”形容举动慌张，或无法应付，侧重于“无法应付”。“力不从心”指心里想做某事，但是力量不够，侧重于“力量不足”。相比较而言，“力不从心”更能与前文“不懂外语，不明世界大势，不懂国际公法”相对应，排除B","no":263},{"id":"1718789646376","type":"single","material":"","stem":"子曰：“邦有道，（）；邦无道，（）。”许多单位为了树立自己的文明形象，频频设立“委屈奖”。似乎“委屈奖”已经成为处理各种人际矛盾的不二良方。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"如坐春风;如坠寒冬"},{"label":"B","content":"千锤百炼;七零八落"},{"label":"C","content":"花团锦簇;民不聊生"},{"label":"D","content":"危言危行;危行言逊"}],"answer":"D","explanation":"“邦有道，危言危行；邦无道，危行言孙(逊)。”语出《论语》,意为“国家有道，要正言正行；国家无道，行为还要正直，但说话要随和谨慎”。文段引用此句是为了引出对某些单位设立“委屈奖”这一举动的批判，即对“委屈”行为设奖是在倡导“言孙(逊)”,这折射出某些单位的“无道”。","no":264},{"id":"1718789646377","type":"single","material":"","stem":"我们中有很多人并不甘心，想叛逆，想抵抗，他们不惜将世人视同生命的“安全感”抛之脑后。人们（）的“安全而平庸的幸福”对他们而言无异于毒药，而世人避之不及的（）的状态，却恰恰是他们最赖以生存的空气。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"心驰神往;大起大落"},{"label":"B","content":"求之不得;波翻浪涌"},{"label":"C","content":"梦寐以求;危机四伏"},{"label":"D","content":"众星捧月;动荡不安"}],"answer":"C","explanation":"第一空，此处所填词语应用于形容人们对“安全而平庸的幸福”的感受。“求之不得”指想找都找不到，语义程度过重，追求“安全而平庸的幸福”没那么难，排除B“众星捧月”比喻许多人簇拥着一个人，或许多个体拥戴一个核心，填入此处不符合句意，排除D“心驰神往”指一心向往。“梦寐以求”指有着强烈的愿望。二者填入均符合句意。<br>第二空，由“世人避之不及”可知，所填词语应表示“危险、刺激”之意，与前文的“安全而平庸的幸福”相对应。“大起大落”指大幅度地起落，形容变化大；“危机四伏”比喻到处隐藏着危险的祸根。“危机四伏”填入更符合句意，排除A","no":265},{"id":"1718789646378","type":"single","material":"","stem":"谈大学办得好不好，就看与哈佛、耶鲁的差距有多大，这已经成为一种新的“迷思”。强调东西方大学性质不同，拒绝比较，必定趋于（）；反过来，一切唯哈佛、耶鲁马首是瞻，忽略养育你的（），这同样有问题。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"固步自封;一方水土"},{"label":"B","content":"夜郎自大;八水三川"},{"label":"C","content":"裹足不前;高堂师长"},{"label":"D","content":"因循守旧;慈亲严师"}],"answer":"A","explanation":"第一空，“强调东西方大学性质不同，拒绝比较”的结果必定是看不到自己的不足，不能客观地认识自己，不能从比较中获得进步，“固步自封”“夜郎自大”符合句意，排除C、D<br>第二空，“八水三川”形容河水纵横的地理景观。此处强调养育你的地方，“一方水土养一方人”为习惯表述，排除B","no":266},{"id":"1718789646379","type":"single","material":"","stem":"客观地说，“网红”并不一定是（）。这个时代，站在互联网风口，猪都能飞起来，何况是有看点、有炒点的“网红”呢？社会原子化、娱乐疯魔化、价值的多元、舆论的分野……给了“网红”勃兴与风靡的最佳土壤。若三观正，有节操，“网红”也可以“最美”；可一旦陷入眼球经济的“名利场”，这个时候，资本只要稍稍抛个媚眼，“网红”经济就容易（）。<br>填入括号部分最恰当的一项是：","options":[{"label":"A","content":"牛鬼蛇神;剑走偏锋"},{"label":"B","content":"洪水猛兽;走火入魔"},{"label":"C","content":"妖魔鬼怪;鬼迷心窍"},{"label":"D","content":"狼烟烽火;趋之若鹜"}],"answer":"B","explanation":"第一空，“狼烟烽火”指的是古代边防军事报警信号，不能用来描述人们对“网红”的成见，排除D<br>第二空，“剑走偏锋”比喻不按常规、常理思维或行动；“走火入魔”指痴迷于某种事物到了失去理智的地步；“鬼迷心窍”指受迷惑，犯糊涂。句意为“网红”一旦陷入眼球经济的“名利场”,就很难抗拒资本的诱惑，以致走入歧途。“走火入魔”用于描述“网红”偏离正道的语境最恰当。","no":267}]};
